# Minimal ATECC608 driver over I2C for MicroPython. Just what a wallet needs:
# wake, serial, lock state, the slot table, public key of a slot, sign a 32-byte digest with a slot,
# and the one-time provisioning steps (write + lock config, GenKey, lock data, lock a slot).
# Packet format and CRC follow Microchip's cryptoauthlib.
#
# How slots work, in short (datasheet sections "Configuration Zone" and "Data Zone"):
#   The chip has 16 data slots. What each one IS (a P-256 private key, a public key, an AES key,
#   plain data) and what it MAY DO (sign external digests, be regenerated with GenKey, be written,
#   be locked on its own) is a 4-byte-per-slot table in the 128-byte config zone: SlotConfig at
#   bytes 20-51 and KeyConfig at bytes 96-127. The config zone is written once and then locked
#   forever; the chip refuses GenKey and Sign until it is. Locking the DATA zone opens reads and ends
#   clear-text writes except where WriteConfig says Always; GenKey stays allowed where the table says so. A single slot can also be locked for
#   good (KeyConfig.Lockable), after which nothing can replace the key in it.
from machine import I2C, SoftI2C, Pin
import time

# Bus pins. secrets.py may set ATECC_SDA / ATECC_SCL; the default is the wallet's GP4/GP5. A pair
# that is a hardware I2C0/I2C1 pair (SDA on 0,4,8,.. / 2,6,10,..; SCL the next pin up) uses the
# peripheral, anything else is bit-banged at 100 kHz, which this chip does not mind.
try:
    import secrets as _s
    SDA, SCL = int(getattr(_s, "ATECC_SDA", 4)), int(getattr(_s, "ATECC_SCL", 5))
except ImportError:
    SDA, SCL = 4, 5


def make_i2c(sda, scl, freq):
    if scl == sda + 1 and sda % 4 in (0, 2):
        return I2C(0 if sda % 4 == 0 else 1, sda=Pin(sda), scl=Pin(scl), freq=freq)
    return SoftI2C(sda=Pin(sda), scl=Pin(scl), freq=freq)

ADDR = 0x60
KNOWN_ADDRS = (0x60, 0x35, 0x6A, 0x58, 0x36, 0x59)   # Adafruit breakout, Trust&Go/TrustFLEX parts, others seen in the wild
WAKE_OK = b"\x04\x11\x33\x43"
OP_READ, OP_NONCE, OP_GENKEY, OP_SIGN, OP_RANDOM, OP_INFO, OP_WRITE, OP_LOCK = 0x02, 0x16, 0x40, 0x41, 0x1B, 0x30, 0x12, 0x17
OP_COUNTER, OP_SHA, OP_SELFTEST = 0x24, 0x47, 0x77

# The one status byte the chip answers with when it has no data for you (datasheet "Status/Error Codes").
STATUS = {0x00: "ok", 0x01: "checkmac or verify miscompare", 0x03: "parse error: the chip did not understand the command",
          0x05: "ecc fault: try again", 0x07: "self-test failed", 0x08: "health test error",
          0x0F: "execution error: not allowed in this state", 0x11: "just woke up: send the command again",
          0xEE: "watchdog about to expire", 0xFF: "crc or communication error"}
SLOT_BYTES = (36,) * 8 + (416,) + (72,) * 7     # data zone: slots 0-7, slot 8, slots 9-15


def explain(code):
    return STATUS.get(code, "unknown status 0x%02x" % code)

# Microchip's ATECC608 reference config (cryptoauthlib test/api_calib/test_calib_config.c,
# test_ecc608_configdata), byte for byte what reference/pi/signer.py wrote to chip #1, the chip
# that owns the mainnet vault. Bytes 0-15 (serial, revision) and 84-87 (lock bytes) are
# read-only and skipped by write_config. With this table (see decode_slot):
#   slot 0   P-256 private key, external sign, GenKey allowed, lockable   <- the wallet key
#   slot 2   P-256 private key, external sign, GenKey allowed
#   slot 7   P-256 private key, external sign, GenKey + encrypted PrivWrite, lockable
#   slots 11, 14, 15  P-256 public keys; 5, 10 AES keys; the rest plain data
# The same bytes as reference/pi/provision.py, copied by program on 2026-09-15 after a hand-copied
# table bricked a chip (upstream and this fork each found and fixed that separately; the two fixed
# tables are identical). Never edit these bytes by hand: see the fingerprint below and
# tools/check_config.
CONFIG = bytes([
    0x01, 0x23, 0x00, 0x00, 0x00, 0x00, 0x60, 0x00, 0x04, 0x05, 0x06, 0x07, 0xEE, 0x01, 0x01, 0x00,
    0xC0, 0x00, 0xA1, 0x00, 0xAF, 0x2F, 0xC4, 0x44, 0x87, 0x20, 0xC4, 0xF4, 0x8F, 0x0F, 0x0F, 0x0F,
    0x9F, 0x8F, 0x83, 0x64, 0xC4, 0x44, 0xC4, 0x64, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F, 0x0F,
    0x0F, 0x0F, 0x0F, 0x0F, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0xFF, 0xFF,
    0x00, 0x00, 0x00, 0x00, 0xFF, 0x84, 0x03, 0xBC, 0x09, 0x69, 0x76, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0x0E, 0x40, 0x00, 0x00, 0x00, 0x00,
    0x33, 0x00, 0x1C, 0x00, 0x13, 0x00, 0x1C, 0x00, 0x3C, 0x00, 0x3A, 0x10, 0x1C, 0x00, 0x33, 0x00,
    0x1C, 0x00, 0x1C, 0x00, 0x38, 0x00, 0x30, 0x00, 0x3C, 0x00, 0x3C, 0x00, 0x32, 0x00, 0x30, 0x00,
])
# Bytes 96-127 are KeyConfig for slots 0-15, two bytes each: slot 0 must be 0x0033 (P-256 private
# key, GenKey allowed). An earlier copy of this table had a spare row of 0xFF at byte 96, which
# pushed every KeyConfig one slot block down; a chip locked with that can never make a P-256 key
# (2026-09-15, serial 0123597b4f22a25eee). These checks stop that class of mistake.
assert len(CONFIG) == 128
assert CONFIG[96:98] == b"\x33\x00", "slot 0 KeyConfig must be 0x0033 at byte 96"
assert CONFIG[20:22] == b"\xAF\x2F", "slot 0 SlotConfig must be 0x2FAF at byte 20 (GenKey allowed, secret)"
# The table's fingerprint. A hand edit changes it and the module refuses to import, so nothing can
# lock a chip with an unreviewed table. To change the table on purpose: run tools/check_config,
# read the diff it prints, then update this hash and the reference in the same commit.
import hashlib as _hl
CONFIG_SHA256 = "c759db6c849668ed53957ded37264023479dfca9b719af4e22d087a1d8a7eacf"
assert _hl.sha256(CONFIG).digest().hex() == CONFIG_SHA256, "CONFIG table changed: see tools/check_config"

KEY_TYPE = {4: "P256", 6: "AES", 7: "DATA"}


def write_policy(wc):
    """SlotConfig.WriteConfig (the top 4 bits) as the Write command reads it (datasheet table
    "WriteConfig bits, Write command"): 0000 Always, 0001 PubInvalid, 001x Never, 10xx Never,
    x1xx Encrypt. An earlier decode indexed a table with wc >> 1, which was right only for 0000."""
    if wc & 4:
        return "encrypted"
    if wc & 8 or wc & 2:
        return "never"
    return "pubinvalid" if wc & 1 else "clear"


def decode_slot(cfg, slot):
    """What the config zone says about one slot. cfg = all 128 config bytes.
    kind: P256 (private key), PUB (P-256 public key), AES, DATA, or ? (reserved type)."""
    sc = cfg[20 + 2 * slot] | cfg[21 + 2 * slot] << 8
    kc = cfg[96 + 2 * slot] | cfg[97 + 2 * slot] << 8
    private = bool(kc & 1)
    ktype = (kc >> 2) & 7
    kind = KEY_TYPE.get(ktype, "?")
    if ktype == 4 and not private:
        kind = "PUB"
    wc = sc >> 12
    return {
        "slot": slot,
        "kind": kind,
        "bytes": SLOT_BYTES[slot],
        "private": private,
        "clearWrite": write_policy(wc),   # the Write command on this slot: clear, encrypted, pubinvalid, never
        "encRead": bool(sc & 0x40),       # reads come out encrypted
        "pubInfo": bool(kc & 2),          # private key: its public half may be read out
        "lockable": bool(kc & 0x20),      # this slot can be locked on its own, forever
        "reqRandom": bool(kc & 0x40),
        "reqAuth": bool(kc & 0x80),
        "isSecret": bool(sc & 0x80),
        "noMac": bool(sc & 0x10),
        "extSign": private and bool(sc & 1),        # may sign digests handed in from outside
        "intSign": private and bool(sc & 2),
        "limitedUse": bool(sc & 0x20),              # every use counts against counter 0
        "genKey": private and bool(wc & 2),         # GenKey may create a new random key here
        "privWrite": private and bool(wc & 4),      # PrivWrite may import a key (encrypted)
        "locked": not (cfg[88 + (slot >> 3)] >> (slot & 7)) & 1,   # SlotLocked: bit clear = locked
    }


# The table above must make slot 0 a P-256 private key that GenKey may fill, or locking a chip with
# it leaves the chip unable to ever hold the wallet key (that is the bug docs/UPSTREAM.md describes).
# Checked here, at import, on the Pico, before any lock can happen.
assert decode_slot(CONFIG, 0)["kind"] == "P256" and decode_slot(CONFIG, 0)["genKey"], "CONFIG does not make slot 0 a P-256 key slot"


def diff_config(cur, new):
    """What writing `new` over `cur` would change: the writable bytes that differ (16-83, 88-127), the
    per-slot fields that change, and whether the I2C address byte (16) would move."""
    changed = [i for i in range(128) if (16 <= i < 84 or i >= 88) and cur[i] != new[i]]
    slots = []
    for n in range(16):
        a, b = decode_slot(cur, n), decode_slot(new, n)
        fields = [(k, a[k], b[k]) for k in ("kind", "extSign", "intSign", "genKey", "privWrite", "pubInfo", "lockable", "isSecret",
                                            "clearWrite", "limitedUse", "reqAuth", "noMac") if a[k] != b[k]]
        if fields:
            slots.append((n, fields))
    return {"bytes": changed, "slots": slots, "addrChanges": cur[16] != new[16]}


def crc16(data):
    crc = 0
    for b in data:
        for shift in range(8):
            data_bit = (b >> shift) & 1
            crc_bit = (crc >> 15) & 1
            crc = (crc << 1) & 0xFFFF
            if data_bit != crc_bit:
                crc ^= 0x8005
    return bytes([crc & 0xFF, crc >> 8])


class AteccError(Exception):
    status = None       # the chip's status byte when it answered with one, else None (transport)


def scan(sda=None, scl=None, freq=100_000):
    """Every I2C address that answers. A sleeping ATECC does not ACK, so wake the bus first."""
    i2c = make_i2c(SDA if sda is None else sda, SCL if scl is None else scl, freq)
    try:
        i2c.writeto(0, b"\x00")
    except OSError:
        pass
    time.sleep_ms(2)
    return i2c.scan()


class ATECC608:
    def __init__(self, sda=None, scl=None, addr=None, freq=100_000):
        """addr None: use 0x60 if it answers, else the first known ATECC address on the bus."""
        sda, scl = (SDA if sda is None else sda), (SCL if scl is None else scl)
        self.i2c = make_i2c(sda, scl, freq)
        if addr is None:
            found = scan(sda, scl, freq)
            addr = ADDR if ADDR in found or not found else next((a for a in KNOWN_ADDRS if a in found), found[0])
        self.addr = addr
        self.trace = None       # the last command as sent and answered: op, p1, p2, data, resp, ms

    # --- transport ---------------------------------------------------------
    def wake(self):
        # Three rounds: the chip may still be finishing a sleep or idle command when the first wake
        # token lands, and a chip that was already awake answers nothing. Put it to sleep and try
        # again rather than fail on the first miss.
        for attempt in range(3):
            try:
                self.i2c.writeto(0, b"\x00")  # SDA held low long enough to count as the wake token
            except OSError:
                pass
            time.sleep_ms(3)
            for _ in range(3):
                try:
                    if self.i2c.readfrom(self.addr, 4) == WAKE_OK:
                        return
                except OSError:
                    time.sleep_ms(2)
            self.sleep()
            time.sleep_ms(10)
        raise AteccError("no wake response")

    def sleep(self):
        try:
            self.i2c.writeto(self.addr, b"\x01")
        except OSError:
            pass

    def idle(self):
        try:
            self.i2c.writeto(self.addr, b"\x02")
        except OSError:
            pass

    def command(self, opcode, p1, p2, data=b"", resp_len=4, wait_ms=5, timeout_ms=300, raw=False):
        """One command packet, then its answer. A 1-byte nonzero answer is a status code and raises,
        unless raw (SelfTest answers with a bitmap that looks like one). self.trace keeps the exchange."""
        body = bytes([len(data) + 7, opcode, p1, p2 & 0xFF, p2 >> 8]) + data
        pkt = b"\x03" + body + crc16(body)
        self.trace = {"op": opcode, "p1": p1, "p2": p2, "data": bytes(data), "resp": b"", "ms": 0}
        t_send = time.ticks_ms()
        self.i2c.writeto(self.addr, pkt)
        time.sleep_ms(wait_ms)
        t0 = time.ticks_ms()
        while True:
            try:
                resp = self.i2c.readfrom(self.addr, resp_len + 3)
                break
            except OSError:
                if time.ticks_diff(time.ticks_ms(), t0) > timeout_ms:
                    raise AteccError("timeout on opcode 0x%02x" % opcode)
                time.sleep_ms(3)
        self.trace["ms"] = time.ticks_diff(time.ticks_ms(), t_send)
        n = resp[0]
        if n < 4 or n > len(resp):
            raise AteccError("bad length %d" % n)
        if crc16(resp[: n - 2]) != resp[n - 2 : n]:
            raise AteccError("bad crc")
        payload = resp[1 : n - 2]
        self.trace["resp"] = bytes(payload)
        if len(payload) == 1 and payload[0] != 0 and not raw:
            e = AteccError("status 0x%02x on opcode 0x%02x" % (payload[0], opcode))
            e.status = payload[0]
            raise e
        return payload

    def run(self, *args, **kw):
        """wake, one command, back to sleep."""
        self.wake()
        try:
            return self.command(*args, **kw)
        finally:
            self.sleep()

    # --- commands ----------------------------------------------------------
    def read_config(self, block):
        """32 bytes of the config zone. block 0..3."""
        return self.run(OP_READ, 0x80, block << 3, resp_len=32, wait_ms=2)

    def read_config_all(self):
        """All 128 config bytes: serial, revision, lock bytes, the slot table."""
        return b"".join(self.read_config(b) for b in range(4))

    def serial(self):
        c = self.read_config(0)
        return c[0:4] + c[8:13]

    def revision(self):
        """4 bytes; 00006002 = 608A, 00006003 = 608B."""
        return self.run(OP_INFO, 0x00, 0x0000, resp_len=4, wait_ms=2)

    def lock_state(self):
        c = self.read_config(2)
        return {"configLocked": c[87 - 64] == 0x00, "dataLocked": c[86 - 64] == 0x00}

    def random(self):
        """32 bytes from the chip's RNG. Until the config zone is locked the chip answers the fixed
        test pattern ffff0000... instead (datasheet); that is how you know it is unlocked."""
        return self.run(OP_RANDOM, 0x00, 0x0000, resp_len=32, wait_ms=25)

    # --- read-only questions (the LAB) --------------------------------------
    def info(self, mode, param=0):
        """Info: mode 0 revision, 1 KeyValid (param = slot; byte 0 is 1 when the slot holds a usable
        key), 2 State (TempKey flags), 3 GPIO. 4 bytes."""
        return self.run(OP_INFO, mode, param, resp_len=4, wait_ms=2)

    def selftest(self, mask=0x3F):
        """608 only. Runs the chip's own tests and returns the answer byte: 0 = every test passed,
        otherwise each set bit is a failed test (0 RNG, 1 ECDSA verify, 2 ECDSA sign, 3 ECDH, 4 AES,
        5 SHA), or a status code if the chip refused (the byte alone cannot tell those apart)."""
        return self.run(OP_SELFTEST, mask, 0x0000, resp_len=1, wait_ms=250, timeout_ms=1500, raw=True)[0]

    def sha256(self, data):
        """SHA-256 of up to 63 bytes, computed on the chip: Start, then End with the bytes."""
        if len(data) > 63:
            raise ValueError("63 bytes at most here")
        self.wake()
        try:
            self.command(OP_SHA, 0x00, 0x0000, resp_len=1, wait_ms=9)
            return self.command(OP_SHA, 0x02, len(data), bytes(data), resp_len=32, wait_ms=9)
        finally:
            self.sleep()

    def counter(self, idx=0):
        """Read monotonic counter 0 or 1 (never increments)."""
        return int.from_bytes(self.run(OP_COUNTER, 0x00, idx, resp_len=4, wait_ms=20), "little")

    def read_otp(self, block=0):
        """32 bytes of the OTP zone (blocks 0 and 1). Refused until the config zone is locked."""
        return self.run(OP_READ, 0x81, block << 3, resp_len=32, wait_ms=2)

    def read_data(self, slot, block=0):
        """32 bytes of a data slot. Refused until the config zone is locked, and per the slot's rules."""
        return self.run(OP_READ, 0x82, (block << 8) | (slot << 3), resp_len=32, wait_ms=2)

    def write_data(self, slot, block, data, word=0):
        """Write 32 bytes (or 4, at `word` of the block) into a data slot in clear (Write zone 2).
        Allowed once the config zone is locked and while the data zone is open, where the slot's
        rules say clear writes are ok. Overwriting again is allowed, so this is reversible until the
        data zone is locked. The 4-byte form reaches the last 4 bytes of a 36- or 72-byte slot."""
        if len(data) not in (4, 32) or (len(data) == 32 and word):
            raise ValueError("32 bytes at a block, or 4 at a word")
        # A 32-byte write may start at a slot's last, partial block (the tail of a 36- or 72-byte
        # slot): the chip keeps the bytes that fit. Seen on silicon (chip 2, 2026-09-26), where
        # 4-byte writes into a secret slot were refused before the data lock.
        if block * 32 + word * 4 >= SLOT_BYTES[slot] or (len(data) == 4 and block * 32 + word * 4 + 4 > SLOT_BYTES[slot]):
            raise ValueError("block %d word %d is past the end of slot %d" % (block, word, slot))
        self.run(OP_WRITE, 0x82 if len(data) == 32 else 0x02, (block << 8) | (slot << 3) | word, bytes(data), resp_len=1, wait_ms=30)

    def write_otp(self, block, data):
        """Write 32 bytes of the OTP zone (blocks 0 and 1) in clear. Only while the data zone is open:
        its lock freezes the OTP zone for good."""
        if len(data) != 32 or block not in (0, 1):
            raise ValueError("32 bytes, block 0 or 1")
        self.run(OP_WRITE, 0x81, block << 3, bytes(data), resp_len=1, wait_ms=30)

    def read_config_word(self, word):
        """4 bytes of the config zone (word 4 holds the I2C address byte)."""
        return self.run(OP_READ, 0x00, word, resp_len=4, wait_ms=2)

    def pubkey(self, slot=0):
        """Public key of the private key in `slot`: (x, y) ints. Fails on an empty slot or one
        whose KeyConfig.PubInfo is clear."""
        pub = self.run(OP_GENKEY, 0x00, slot, resp_len=64, wait_ms=120)
        return int.from_bytes(pub[:32], "big"), int.from_bytes(pub[32:], "big")

    def sign(self, digest, slot=0):
        """ECDSA over a 32-byte digest with the key in `slot`. Returns (r, s) ints, s not normalized."""
        if len(digest) != 32:
            raise ValueError("digest must be 32 bytes")
        self.wake()
        try:
            self.command(OP_NONCE, 0x03, 0x0000, digest, resp_len=1, wait_ms=8)  # pass-through -> TempKey
            sig = self.command(OP_SIGN, 0x80, slot, resp_len=64, wait_ms=120)      # external message from TempKey
        finally:
            self.sleep()
        return int.from_bytes(sig[:32], "big"), int.from_bytes(sig[32:], "big")

    def slots(self, cfg=None, probe=True):
        """The slot table as the chip has it, plus (when probe and the config is locked) whether
        each P-256 private slot holds a key and its public key."""
        if cfg is None:
            cfg = self.read_config_all()
        locked = cfg[87] == 0x00
        out = []
        for n in range(16):
            s = decode_slot(cfg, n)
            if s["kind"] == "P256":
                s["hasKey"] = False
                if probe and locked and s["pubInfo"]:
                    try:
                        x, y = self.pubkey(n)
                        s["hasKey"] = True
                        s["qx"], s["qy"] = x, y
                    except AteccError:
                        pass
            out.append(s)
        return out

    # --- provisioning (once per fresh chip) --------------------------------
    def write_config(self, cfg=CONFIG):
        """Write the config zone in 4-byte words, skipping the read-only words (0-3 and 21), then read
        it back. REVERSIBLE while the zone is open: it can be written again, and again. Refuses to move
        the I2C address byte (16), since the chip would answer somewhere else after its next wake.
        Returns how many bytes changed; raises if the readback differs from what was written."""
        assert len(cfg) == 128
        before = self.read_config_all()
        if before[87] == 0x00:
            raise AteccError("config zone is locked: it can never be written again")
        if cfg[16] != before[16]:
            raise AteccError("refusing to change the I2C address byte (0x%02x -> 0x%02x)" % (before[16], cfg[16]))
        # In batches of 8 words with a fresh wake each: the chip's watchdog puts it to sleep 1.3 s
        # after a wake, and 27 writes at ~35 ms each run right up to that (upstream, seen on silicon).
        words = [w for w in range(32) if w >= 4 and w != 21]
        for i in range(0, len(words), 8):
            self.wake()
            try:
                for word in words[i:i + 8]:
                    self.command(OP_WRITE, 0x00, word, cfg[word * 4:word * 4 + 4], resp_len=1, wait_ms=30)
            finally:
                self.sleep()
                time.sleep_ms(5)
        after = self.verify_config(cfg)
        return sum(1 for i in range(128) if before[i] != after[i])

    def verify_config(self, cfg=CONFIG):
        """Read the config zone back and compare every writable byte (16-83, 88-127). Raises with the
        count and the first bad offset; returns the 128 bytes read. Run it before any lock: a lock
        over a wrong table is forever."""
        got = self.read_config_all()
        bad = [i for i in range(128) if (16 <= i < 84 or i >= 88) and got[i] != cfg[i]]
        if bad:
            raise AteccError("config differs at %d bytes (first: byte %d is 0x%02x, wanted 0x%02x)"
                             % (len(bad), bad[0], got[bad[0]], cfg[bad[0]]))
        return got

    def lock_config(self, expect=CONFIG, summary=None):
        """PERMANENT. Lock the config zone. With summary (the CRC of the 128 bytes the zone must hold,
        chipcfg.config_summary) the chip itself refuses unless its zone matches it byte for byte,
        mode 0x00; without it, no CRC check, mode 0x80 (how chip #1 was locked). Before sending the Lock it reads
        the zone back and refuses if it is already locked, if the table on the chip differs from
        `expect` in the writable bytes (16-83, 88-127; pass None to lock any table), or if slot 0
        does not decode as a P-256 private key with GenKey allowed. A chip locked with such a table
        could never hold the wallet key, and the lock cannot be undone."""
        cfg = self.read_config_all()
        if cfg[87] == 0x00:
            raise AteccError("config zone is already locked")
        if expect is not None:
            bad = [i for i in range(128) if (16 <= i < 84 or i >= 88) and cfg[i] != expect[i]]
            if bad:
                raise AteccError("refusing to lock: the chip's table differs from the expected one at %d bytes (first at byte %d)" % (len(bad), bad[0]))
        s0 = decode_slot(cfg, 0)
        if s0["kind"] != "P256" or not s0["genKey"]:
            raise AteccError("refusing to lock: slot 0 would be %s with genkey %s, not a P-256 key slot" % (s0["kind"], "allowed" if s0["genKey"] else "forbidden"))
        self.run(OP_LOCK, 0x80 if summary is None else 0x00, 0x0000 if summary is None else summary, resp_len=1, wait_ms=35)
        if not self.lock_state()["configLocked"]:
            raise AteccError("lock command returned but the zone is still unlocked")

    def lock_data(self, summary=None):
        """PERMANENT. Lock the data (and OTP) zone. With summary (chipcfg.data_summary: the CRC of every
        slot that is not a private key, then the OTP zone) the chip refuses unless what it holds
        matches, mode 0x01; without, mode 0x81. After it: reads of slots and OTP begin, and clear
        writes stay only where SlotConfig.WriteConfig says Always (slots 12 and 13 in the wallet config;
        datasheet, not yet seen on silicon). GenKey keeps working on slots whose config allows it."""
        st = self.lock_state()
        if not st["configLocked"]:
            raise AteccError("lock the config zone first")
        if st["dataLocked"]:
            raise AteccError("data zone is already locked")
        self.run(OP_LOCK, 0x81 if summary is None else 0x01, 0x0000 if summary is None else summary, resp_len=1, wait_ms=35)
        if not self.lock_state()["dataLocked"]:
            raise AteccError("lock command returned but the data zone is still unlocked")

    def lock_slot(self, slot):
        """PERMANENT. Lock one slot (mode 0x82 | slot << 2). The key in it can never be replaced.
        Needs KeyConfig.Lockable for that slot."""
        cfg = self.read_config_all()
        s = decode_slot(cfg, slot)
        if cfg[87] != 0x00:
            raise AteccError("lock the config zone first")
        if not s["lockable"]:
            raise AteccError("slot %d is not lockable" % slot)
        if s["locked"]:
            raise AteccError("slot %d is already locked" % slot)
        self.run(OP_LOCK, 0x82 | (slot << 2), 0x0000, resp_len=1, wait_ms=35)
        if not decode_slot(self.read_config_all(), slot)["locked"]:
            raise AteccError("lock command returned but slot %d is still unlocked" % slot)

    def genkey_new(self, slot=0):
        """Create a NEW random private key in `slot`, replacing whatever was there. Returns (x, y)."""
        pub = self.run(OP_GENKEY, 0x04, slot, resp_len=64, wait_ms=120)
        return int.from_bytes(pub[:32], "big"), int.from_bytes(pub[32:], "big")

    def status(self, slot=0):
        s = self.lock_state()
        s["i2cAddr"] = "0x%02x" % self.addr
        s["serial"] = "".join("%02x" % b for b in self.serial())
        try:
            s["revision"] = "".join("%02x" % b for b in self.revision())
        except AteccError:
            pass
        s["slot"] = slot
        try:
            self.pubkey(slot)
            s["hasKey"] = True
        except AteccError as e:
            s["hasKey"] = False
            s["note"] = str(e)
        return s

# The ceremony image's only app, on a 50 ms timer: a banner first, so nobody mistakes this board
# for a signing console, then A for the provisioning ceremony (provision.py: quorum v1 on a fresh
# ATECC608; provision_tm.py: quorum-tm1 on a fresh Trust M) or X for the chip map (slots.py; on a
# Trust M, its objects' metadata, read-only). Every permanent action in either still needs
# ALLOW_LOCK / ALLOW_GENKEY in secrets.py and the arm (signer.py): B+Y, or on build1 a 3 s knob hold.
# On build1 the knob drives it: turn to choose, press to open. Every screen is drawn through
# d.frames, so the strip-buffered 320x240 panel gets all of it.
import time
import machine
import lcd as L
import splash
import signer as S

d = keys = sig = ui = prov = timer = None
chip = None         # this chip's entry in chips.json (name, theme): which chip is in, at a glance
profile = ""
_busy = False
sel = 0             # the knob's choice on the banner: 0 PROVISION, 1 the map
STATE = {"factory": "FRESH: ready for PROVISION", "quorum-v1": "sealed or in progress: quorum v1",
         "quorum-tm1": "sealed: Trust M quorum-tm1", "quorum-tm1-open": "in progress: Trust M",
         "legacy-test": "test table (chip #1 style)", "unknown": "unknown table"}


def identify():
    """The chip on the bus: register it (chips.py) and say what it holds (sig.profile)."""
    global chip, profile
    chip, profile = None, ""
    if not S.is_chip(sig):
        return
    try:
        import chips
        profile = sig.profile()
        chip, new = chips.seen(sig.serial(), profile, kind=sig.name)
    except Exception as e:
        print("chip:", e)


def choices():
    """The banner's entries: (label, what). The ATECC's chip map is button-driven, so on the knob
    only a Trust M's read-only object map is offered next to PROVISION."""
    tm = sig is not None and sig.name == "trustm"
    out = [("PROVISION (Trust M)" if tm else "PROVISION (quorum v1)", "prov")]
    if tm:
        out.append(("its objects", "map"))
    elif not L.KNOB:
        out.append(("the chip map", "slots"))
    return out


def banner():
    d.frames(_banner, serial_tail())


def serial_tail():
    try:
        return sig.serial()[-8:] if S.is_chip(sig) else ""
    except Exception:
        return ""


def _banner(tail):
    import provision
    p = provision.palette(chip["theme"] if chip else "dark")
    d.fill(p["bg"])
    d.center_text("CEREMONY IMAGE", 40, p["accent"], 2)
    y = 70
    for line in ("Not a signing console:", "no Safe, no service."):
        d.center_text(line, y, p["fg"])
        y += 12
    y += 10
    if chip:
        d.center_text("%s  %s" % (chip["name"].upper(), tail), y, p["accent"], 1)
        d.center_text(STATE.get(profile, profile), y + 14, p["ok"] if profile == "factory" else p["fg"])
    else:
        d.center_text("NO CHIP on the bus", y, p["bad"])
    y += 44
    for i, (label, _) in enumerate(choices()):
        if L.KNOB:
            d.center_text(("> %s <" if i == sel else "  %s  ") % label, y, p["accent"] if i == sel else p["fg"])
        else:
            d.center_text(("A: " if i == 0 else "X: ") + label, y, p["fg"])
        y += 14
    if L.KNOB:
        d.center_text("turn: choose   press: open", y + 10, p["muted"])
    d.show()


def open_choice(what):
    global prov, ui
    import provision
    if what == "prov" and chip is not None:
        if sig.name == "trustm":
            import provision_tm
            prov = provision.UI(d, keys, sig, chip["theme"], provision_tm.Ceremony(sig))
        else:
            prov = provision.UI(d, keys, sig, chip["theme"])
        prov.draw()
    elif what == "map":
        import provision_tm
        ui = "map"
        provision_tm.draw_map(d, sig, provision.palette(chip["theme"] if chip else "dark"))
    elif what == "slots":
        import slots
        ui = slots.SlotsUI(d, sig, lambda: None)
        ui.open("zones")
        ui.draw()


def tick(t):
    global _busy, ui, prov, sel
    if _busy:
        return
    _busy = True
    try:
        pressed = keys.pressed()
        if prov is not None:
            if prov.tick(pressed) == "back":
                prov = None
                banner()
            else:
                prov.draw()
        elif ui == "map":
            if pressed:
                ui = None
                banner()
        elif ui is not None:
            if ui.tick(pressed, keys) == "home":
                ui = None
                banner()
        elif "A" in pressed:
            open_choice("prov")
        elif "X" in pressed and choices()[1:]:
            open_choice(choices()[1][1])
        elif ("up" in pressed or "down" in pressed) and len(choices()) > 1:
            sel = 1 - sel
            banner()
        elif "press" in pressed:
            open_choice(choices()[min(sel, len(choices()) - 1)][1])
    except Exception as e:
        import sys
        sys.print_exception(e)
    finally:
        _busy = False


def start_timer():
    global timer
    timer = machine.Timer(period=50, mode=machine.Timer.PERIODIC, callback=tick)


def start():
    global d, keys, sig
    splash.TITLE = "ceremony"
    d = splash.begin()
    keys = L.Keys()
    splash.finish(keys, wait=False)     # the boot art's code out of RAM before the ceremony's screens
    sig = S.load(soft=False)
    identify()
    banner()
    start_timer()


def stop():
    if timer:
        timer.deinit()

# CHIP MAP: the ATECC608 as a place you can walk through. The chip's real structure (CONFIG 128 B,
# DATA 16 slots of 36/416/72 B, OTP 64 B, two COUNTERS), a breadcrumb that says where you are, the
# CONFIG page with its snapshot and the reversible write flow, the pages that read OTP and counters,
# and the screen the chip's refusals land on: the reason first, the raw status second.
#
# Every action carries a class, shown by colour AND a glyph AND words, never colour alone:
#   o SAFE TO EXPLORE: changes nothing      ~ REVERSIBLE CHANGE: can be restored
#   ! PERMANENT: cannot be undone
# ARM is the wallet's own safety catch, not a chip feature, so it lives in the header, not on the
# map: hold B and Y together 3 s and permanent actions are armed for a minute (signer.arm).
# These functions take the SlotsUI object (slots.py) and draw on ui.d; the state machine is there.
import time
import lcd as L
import signer as S
import atecc
import theme as T
import icons as I

CLASS = {"safe": ("o", T.C["safe"], "SAFE TO EXPLORE: no changes"),
         "rev": ("~", T.C["rev"], "REVERSIBLE: can be restored"),
         "perm": ("!", T.C["perm"], "PERMANENT: cannot be undone")}
KIND_COLOR = {"P256": T.C["learn"], "PUB": T.C["config"], "AES": T.C["counters"], "DATA": T.C["grey"], "?": T.C["dim"]}
KIND_ICON = {"P256": "key", "PUB": "pub", "AES": "aes", "DATA": "bytes", "?": "bytes"}
ARM_HOLD_MS = 3000
DIM = L.color(90, 90, 100)
NAMES = {"zones": "CHIP", "list": "DATA", "cfg": "CONFIG", "raw": "RAW", "diff": "DIFF", "otp": "OTP",
         "counters": "COUNTERS", "lab": "LAB", "learn": "LEARN", "labres": "ANSWER", "why": "WHY",
         "rawcmd": "RAW", "refused": "REFUSED", "confirm": "PERMANENT", "confirm_write": "WRITE",
         "result": "RESULT", "busy": "...", "pubkey": "PUBKEY", "pubqr": "QR", "snake": "SNAKE"}


# ----------------------------------------------------------------------------- text and chrome
def wrap(s, w=29):
    """Word-wrap into lines of at most w characters (the 8x8 font gives 29 per row at x=4)."""
    out, line = [], ""
    for word in s.split(" "):
        while len(word) > w:
            if line:
                out.append(line); line = ""
            out.append(word[:w]); word = word[w:]
        if len(line) + len(word) + (1 if line else 0) > w:
            out.append(line); line = word
        else:
            line = line + " " + word if line else word
    if line:
        out.append(line)
    return out


def crumb(ui, limit=22):
    """Where you are: CHIP > DATA > SLOT 3. Long trails lose their head, never their tail."""
    parts = []
    for v, _, _ in ui.stack + [(ui.view, 0, 0)]:
        if v == "slot":
            parts.append("SLOT %d" % ui.cur)
        elif v == "card" and ui.card is not None:
            parts.append("%d" % (ui.card + 1))
        elif v in NAMES:
            parts.append(NAMES[v])
    s = " > ".join(parts)
    while len(s) > limit and len(parts) > 1:
        parts.pop(0)
        s = ".. " + " > ".join(parts)
    return s


def header(ui, text=None):
    """One line in the bar: the breadcrumb left, the wallet's ARM state right."""
    d = ui.d
    d.fill_rect(0, 0, 240, 22, T.shade(T.zone_of(ui.view), 0.35))
    left = S.armed()
    arm = ("! ARMED %ds" % left) if left else "SAFE o"
    d.text(text[:28 - len(arm)] if text is not None else crumb(ui, 28 - len(arm)), 4, 7, L.WHITE)
    d.text(arm, 236 - 8 * len(arm), 7, L.RED if left else L.GREEN)


def footer(ui, text, color=L.GREY):
    ui.d.fill_rect(0, 226, 240, 14, L.DARK)
    ui.d.text(text[:29], 4, 229, color)


def icon(d, name, x, y, c, scale=1):
    """A 16 px bitmap from icons.py in colour c: check, cross, warn, lock, unlock, key, ..."""
    I.draw(d, name, x, y, c, scale)


def badge(d, cls, x, y):
    """The class as a small filled square with its glyph: o safe, ~ reversible, ! permanent."""
    glyph, color, _ = CLASS[cls]
    d.fill_rect(x, y - 1, 10, 10, color)
    d.text(glyph, x + 1, y, L.BLACK)


def menu(ui, items, y, sel):
    """Rows of (kind, label, cls, off). Glyph in the class colour, label white (yellow when picked,
    dim when off). Returns the next y. The footer words come from menu_footer."""
    d = ui.d
    zone = T.C[T.zone_of(ui.view)]
    for i, (kind, label, cls, off) in enumerate(items):
        if i == sel:
            d.fill_rect(0, y - 2, 240, 13, T.C["ink"])
            d.fill_rect(0, y - 2, 3, 13, zone)
        badge(d, cls, 10, y)
        d.text(label[:26], 26, y, DIM if off else (L.YELLOW if i == sel else L.WHITE))
        y += 14
    return y


def menu_footer(ui, items, sel):
    if not items:
        footer(ui, "Y back")
        return
    kind, label, cls, off = items[sel]
    if off:
        footer(ui, ("off: " + off)[:29], L.RED)
    else:
        glyph, color, words = CLASS[cls]
        footer(ui, words, color)


def draw_scroll(ui, lines, y=26, bottom=224, color=L.WHITE):
    """Lines from ui.scroll down to the footer; up/down move it (scroll_tick)."""
    d = ui.d
    n = (bottom - y) // 12
    ui.scroll = max(0, min(ui.scroll, max(0, len(lines) - n)))
    for line in lines[ui.scroll:ui.scroll + n]:
        d.text(line, 4, y, color)
        y += 12
    if len(lines) > n:
        d.text("%d/%d" % (ui.scroll // n + 1, (len(lines) + n - 1) // n), 200, 229, L.GREY)


def scroll_tick(ui, pressed, step=8):
    if "up" in pressed:
        ui.scroll = max(0, ui.scroll - step); ui.dirty = True
    if "down" in pressed:
        ui.scroll += step; ui.dirty = True


def hexs(b, per=16):
    return " ".join("%02x" % x for x in b[:per])


# ----------------------------------------------------------------------------- ARM
def arm_tick(ui, pressed, keys):
    """Hold B and Y together ARM_HOLD_MS to arm the wallet (or disarm it while armed). Single B
    and Y presses are delivered on release, so the pair never triggers a back or a card first.
    Returns the presses the view should see."""
    now = time.ticks_ms()
    out = [k for k in pressed if k not in ("B", "Y")]
    for k in ("B", "Y"):
        if k in pressed:
            ui.pend[k] = now
    b, y = keys.held("B"), keys.held("Y")
    if b and y:
        ui.pend.clear()
        ui.pair = True
        if ui.armhold is None:
            ui.armhold = now
            ui.dirty = True
        elif time.ticks_diff(now, ui.armhold) >= ARM_HOLD_MS:
            if S.armed():
                S.disarm()
            else:
                S.arm()
            ui.armhold = None
            ui.pair = "done"        # swallow both keys until both are up
            ui.dirty = True
        elif ui.n % 4 == 0:
            ui.dirty = True         # the bar moves 5 times a second; a full redraw is up to 140 ms
        return out
    if ui.armhold is not None:
        ui.armhold, ui.dirty = None, True
    if not b and not y:
        ui.pair = False
    for k in ("B", "Y"):
        if k in ui.pend and not keys.held(k):
            del ui.pend[k]
            if not ui.pair:
                out.append(k)
    return out


def draw_arm_bar(ui):
    d = ui.d
    d.fill_rect(0, 200, 240, 40, L.BLACK)
    armed = S.armed()
    d.center_text("keep holding B+Y to %s" % ("DISARM" if armed else "ARM"), 204, L.YELLOW)
    d.rect(20, 218, 200, 12, L.WHITE)
    w = min(198, 198 * time.ticks_diff(time.ticks_ms(), ui.armhold) // ARM_HOLD_MS)
    d.fill_rect(21, 219, w, 10, L.GREEN if armed else L.RED)


# ----------------------------------------------------------------------------- CHIP MAP
ZONES = (("cfg", "CONFIG", "config", "the rules for every slot"),
         ("list", "DATA", "data", "keys and bytes, 36/416/72 B"),
         ("otp", "OTP", "otp", "64 write-once bytes"),
         ("counters", "COUNTERS", "counters", "two numbers, only ever up"),
         ("lab", "LAB", "lab", "ask the chip, read-only"))


def regions(x, y, w, h):
    """Where each zone sits on the die, as (rx, ry, rw, rh)."""
    return {"cfg": (x + 8, y + 8, w - 16, 26),
            "list": (x + 8, y + 40, 116, 72),
            "otp": (x + 132, y + 40, w - 140, 32),
            "counters": (x + 132, y + 80, w - 140, 32),
            "lab": (x + 8, y + 118, w - 16, 16)}


def draw_die(d, ui, x, y, w, h, sel=None, pulse=None, locked=None):
    """The chip as a floor plan: CONFIG across the top, the 4x4 field of slots, OTP, COUNTERS, the
    LAB docked at the bottom. sel gets a white frame; pulse recolours the selected region."""
    st = ui.st
    cfg = st.get("configLocked") if locked is None else locked
    data = st.get("dataLocked")
    for i in range(6):
        ly = y + 14 + i * 22
        d.fill_rect(x - 8, ly, 8, 4, T.C["dim"])
        d.fill_rect(x + w, ly, 8, 4, T.C["dim"])
    d.fill_rect(x, y, w, h, T.C["ink"])
    d.rect(x, y, w, h, T.C["chip"])
    d.fill_rect(x + 3, y + 3, 4, 4, T.C["learn"])
    R = regions(x, y, w, h)
    for key, name, zone, _ in ZONES:
        rx, ry, rw, rh = R[key]
        color = T.C[zone]
        fill = pulse if (pulse and key == sel) else T.shade(zone, 0.28)
        d.fill_rect(rx, ry, rw, rh, fill)
        d.rect(rx, ry, rw, rh, color)
        if key == "list":
            for n in range(16):
                s = ui.row(n)
                kc = KIND_COLOR.get(s["kind"], T.C["dim"]) if cfg or s["kind"] != "?" else T.C["dim"]
                tx, ty = rx + 6 + (n % 4) * 27, ry + 14 + (n // 4) * 14
                d.fill_rect(tx, ty, 20, 10, kc if s["kind"] != "DATA" else T.shade("data", 0.5))
                if n == ui.sig.slot:
                    d.rect(tx - 1, ty - 1, 22, 12, T.C["safe"])
            d.text("DATA", rx + 4, ry + 3, color)
        elif key == "cfg":
            I.draw(d, "config", rx + 4, ry + 5, color)
            d.text("CONFIG 128 B", rx + 24, ry + 9, L.WHITE)
            I.draw(d, "lock" if cfg else "unlock", rx + rw - 22, ry + 5, T.C["safe"] if cfg else T.C["perm"])
        elif key == "otp":
            I.draw(d, "otp", rx + 3, ry + 8, color)
            d.text("OTP", rx + 22, ry + 12, L.WHITE)
            if not cfg:
                d.text("?", rx + rw - 12, ry + 12, T.C["perm"])
        elif key == "counters":
            I.draw(d, "counter", rx + 3, ry + 8, color)
            d.text("CTR", rx + 22, ry + 12, L.WHITE)
        elif key == "lab":
            I.draw(d, "lab", rx + 2, ry, color)
            d.text("LAB: ask the chip", rx + 22, ry + 4, L.WHITE)
        if key == sel:
            d.rect(rx - 2, ry - 2, rw + 4, rh + 4, L.WHITE)
            d.rect(rx - 3, ry - 3, rw + 6, rh + 6, L.WHITE)
    return R


def draw_zones(ui):
    d = ui.d
    st = ui.st
    header(ui)
    draw_die(d, ui, 20, 30, 200, 140, sel=ZONES[ui.act][0])
    cfg, data = st.get("configLocked"), st.get("dataLocked")
    key, name, zone, blurb = ZONES[ui.act]
    state = {"cfg": ("LOCKED" if cfg else "OPEN", T.C["safe"] if cfg else T.C["perm"]),
             "list": (("LOCKED" if data else "write-only") if cfg else "hidden", T.C["safe"] if data else (T.C["rev"] if cfg else T.C["perm"])),
             "otp": (("LOCKED" if data else "write-only") if cfg else "hidden", T.C["safe"] if data else (T.C["rev"] if cfg else T.C["perm"])),
             "counters": ("", L.WHITE), "lab": ("", L.WHITE)}[key]
    size = {"cfg": "128 B", "list": "16 slots", "otp": "64 B", "counters": "2", "lab": ""}[key]
    y = 180
    I.draw(d, {"cfg": "config", "list": "data", "otp": "otp", "counters": "counter", "lab": "lab"}[key], 4, y - 4, T.C[zone])
    d.text(name, 24, y, T.C[zone])
    d.text(size, 24 + 8 * len(name) + 8, y, L.GREY)
    if state[0]:
        d.text(state[0], 236 - 8 * len(state[0]), y, state[1])
    d.text(blurb[:29], 4, y + 14, L.WHITE)
    d.text("%s  i2c %s" % (ui.part(), st.get("i2cAddr", "?")), 4, y + 28, DIM)
    footer(ui, "A open  B learn  Y home")


def tick_zones(ui, pressed):
    for k in pressed:
        if k == "up":
            ui.act = (ui.act - 1) % len(ZONES)
        elif k == "down":
            ui.act = (ui.act + 1) % len(ZONES)
        elif k == "A" or k == "press":
            view = ZONES[ui.act][0]
            if view in ("otp", "counters"):
                open_zone(ui, view)
            else:
                ui.go(view)
        elif k == "Y":
            ui.back()
        ui.dirty = True


def open_zone(ui, view):
    """OTP and COUNTERS: read on open; a refusal is the lesson, not an error."""
    chip = getattr(ui.sig, "chip", None)
    if chip is None:
        return refuse(ui, view, None, "There is no chip on the bus: the software key has no zones.")
    try:
        if view == "otp":
            ui.zone = chip.read_otp(0) + chip.read_otp(1)
        else:
            ui.zone = (chip.counter(0), chip.counter(1))
        ui.go(view)
    except atecc.AteccError as e:
        refuse(ui, view, e)


def draw_otp(ui):
    header(ui)
    lines = ["64 bytes you write once, in", "32-byte halves; bits only go", "from 1 to 0, never back.", ""]
    b = ui.zone
    for r in range(4):
        lines.append("%2d: %s" % (r * 16, hexs(b[r * 16:r * 16 + 16])))
    draw_scroll(ui, lines)
    footer(ui, "Y back")


def draw_counters(ui):
    header(ui)
    c0, c1 = ui.zone
    lines = wrap("Two counters that only go up, to 2 097 151 at most. A slot can be tied to counter 0 so every signature costs one.")
    lines += ["", "counter 0   %d" % c0, "counter 1   %d" % c1]
    draw_scroll(ui, lines)
    footer(ui, "Y back")


def draw_tile(d, ui, s, x, y, w, h, sel=False):
    """One slot as a tile: number, kind icon, size, and a fingerprint or state word."""
    cfg = ui.st.get("configLocked")
    kind = s["kind"]
    color = KIND_COLOR.get(kind, T.C["dim"])
    d.fill_rect(x, y, w, h, T.shade("data", 0.18) if kind == "DATA" else T.C["ink"])
    d.text("%2d" % s["slot"], x + 2, y + 3, L.WHITE if kind != "DATA" else L.GREY)
    if s["locked"]:
        I.draw(d, "lock", x + w - 19, y + 2, T.C["perm"])
    else:
        I.draw(d, KIND_ICON.get(kind, "bytes"), x + w - 19, y + 2, color)
    d.text("%dB" % s.get("bytes", 36), x + 2, y + h - 21, DIM)
    if kind == "P256":
        if s.get("hasKey"):
            what, wc = ("%08x" % (s["qx"] >> 224))[:6], L.WHITE
        elif not cfg:
            what, wc = "hidden", T.C["perm"]
        elif not s.get("pubInfo", True):
            what, wc = "secret", L.GREY
        else:
            what, wc = "empty", T.C["rev"]
        d.text(what, x + 2, y + h - 10, wc)
    elif kind == "DATA":
        d.text("secret" if s.get("isSecret") else "clear", x + 2, y + h - 10, T.C["dim"] if s.get("isSecret") else color)
    elif kind != "?":
        d.text(kind.lower(), x + 2, y + h - 10, color)
    if s["slot"] == ui.sig.slot:
        d.fill_rect(x, y + h - 2, w, 2, T.C["safe"])
    if sel:
        d.rect(x - 1, y - 1, w + 2, h + 2, L.WHITE)
        d.rect(x - 2, y - 2, w + 4, h + 4, L.WHITE)


# ----------------------------------------------------------------------------- CONFIG
def cfg_same(a, b):
    """Two config tables agree where writes can reach (bytes 16-83, 88-127)."""
    return a is not None and b is not None and a[16:84] == b[16:84] and a[88:] == b[88:]


def cfg_state(ui):
    """original | wallet | modified: what is on the chip now, against the snapshot and atecc.CONFIG."""
    if cfg_same(ui.cfgb, atecc.CONFIG):
        return "wallet"
    if ui.snap is None or cfg_same(ui.cfgb, ui.snap):
        return "original"
    return "modified"


def cfg_actions(ui):
    st = ui.st
    cfg, data = st.get("configLocked"), st.get("dataLocked")
    state = cfg_state(ui)
    out = [("raw", "RAW BYTES", "safe", "")]
    if ui.snap is not None:
        out.append(("diff", "COMPARE WITH SAVED", "safe", ""))
    # A fresh chip gets PicoQuorum's own table, quorum v1, through PROVISION (provision.py), which
    # locks each zone with a CRC the chip checks. Microchip's test table and the unchecked locks
    # stay readable here but can no longer be written or sealed from the chip map.
    if not cfg:
        out.append(("writecfg", "WRITE TEST CONFIG", "rev", "fresh chips: PROVISION (quorum v1)"))
        if ui.snap is not None:
            out.append(("restore", "RESTORE SAVED CONFIG", "rev", "" if state != "original" else "the chip holds it already"))
        out.append(("lockcfg", "LOCK CONFIG FOREVER", "perm", "PROVISION locks it, with a CRC"))
    elif not data:
        out.append(("lockdata", "LOCK DATA ZONE", "perm", "PROVISION locks it, with a CRC (LOCKING.md)"))
    out.append(("refresh", "RE-READ", "safe", ""))
    return out


def draw_cfg(ui):
    d = ui.d
    st = ui.st
    header(ui)
    y = 27
    cfg, data = st.get("configLocked"), st.get("dataLocked")
    X = 104
    d.text("CONFIG ZONE", 4, y, L.WHITE)
    d.text("128 B", X, y, L.GREY)
    d.text("LOCKED" if cfg else "OPEN", X + 56, y, L.GREEN if cfg else L.RED); y += 12
    d.text("  sealed, never changes again" if cfg else "  rewritable until locked", 4, y, L.GREY); y += 14
    state = cfg_state(ui)
    d.text("CURRENT", 4, y, L.GREY)
    d.text({"original": "original bytes", "wallet": "wallet config", "modified": "modified"}[state], X, y,
           L.WHITE if state != "modified" else L.YELLOW); y += 12
    d.text("SNAPSHOT", 4, y, L.GREY)
    d.text("none yet" if ui.snap is None else "saved", X, y, DIM if ui.snap is None else L.GREEN); y += 12
    d.text("  the original bytes, kept" if ui.snap is not None else "  taken before the first write", 4, y, DIM); y += 14
    d.text("DATA ZONE", 4, y, L.GREY)
    d.text("hidden" if not cfg else ("LOCKED" if data else "open, write-only"), X, y, L.RED if not cfg else (L.GREEN if data else L.YELLOW)); y += 12
    d.text("  until CONFIG is locked" if not cfg else ("  clear writes only in 12, 13" if data else "  clear writes ok, reads after lock"), 4, y, DIM); y += 16
    items = cfg_actions(ui)
    menu(ui, items, y, ui.act)
    menu_footer(ui, items, ui.act)


def tick_cfg(ui, pressed):
    items = cfg_actions(ui)
    for k in pressed:
        if k == "up":
            ui.act = (ui.act - 1) % len(items)
        elif k == "down":
            ui.act = (ui.act + 1) % len(items)
        elif k == "Y":
            ui.back()
        elif k == "A" or k == "press":
            kind, label, cls, off = items[ui.act]
            if off:
                ui.show_result("off: " + off + ". Nothing was changed.", False)
            elif kind == "raw":
                ui.go("raw")
            elif kind == "diff":
                ui.diff = atecc.diff_config(ui.cfgb, ui.snap)
                ui.difftitle = "chip vs saved snapshot"
                ui.go("diff")
            elif kind in ("writecfg", "restore"):
                start_write(ui, kind)
            elif kind == "refresh":
                ui.refresh()
                ui.act = 0
            else:
                ui.choose(kind, None)
        ui.dirty = True


def draw_raw(ui):
    """The 128 config bytes, 8 a row: the table the chip lives by, readable off the screen."""
    d = ui.d
    header(ui)
    cfg = ui.cfgb or b""
    for r in range(16):
        y = 26 + r * 12
        d.text("%3d" % (r * 8), 2, y, L.GREY)
        row = cfg[r * 8:r * 8 + 8]
        if r in (2, 3, 12, 13, 14, 15):
            c = L.WHITE      # SlotConfig (20-51) and KeyConfig (96-127) rows: the slot table
        elif r == 10:
            c = L.YELLOW     # 84-87 lock bytes, 88-89 slot locked
        else:
            c = L.GREY
        d.text(" ".join("%02x" % b for b in row), 30, y, c)
    footer(ui, "white=slot table  Y back")


def diff_lines(diff, full=True):
    """The change list as screen lines."""
    lines = ["%d bytes would change" % len(diff["bytes"]) if diff["bytes"] else "nothing would change"]
    if diff["addrChanges"]:
        lines.append("! I2C ADDRESS WOULD CHANGE")
    names = {"kind": "kind", "extSign": "sign", "genKey": "genkey", "privWrite": "privwrite", "pubInfo": "pub readable",
             "lockable": "lockable", "isSecret": "secret", "clearWrite": "write"}
    yn = lambda v: v if isinstance(v, str) else ("yes" if v else "no")
    for slot, fields in diff["slots"]:
        kinds = [(a, b) for k, a, b in fields if k == "kind"]
        if kinds:
            lines.append("slot %d: %s -> %s" % (slot, kinds[0][0], kinds[0][1]))
        elif full:
            lines.append("slot %d (%s):" % (slot, fields and "same kind" or ""))
        if full:
            for k, a, b in fields:
                if k != "kind":
                    lines.append("  %s: %s -> %s" % (names[k], yn(a), yn(b)))
    return lines


def draw_diff(ui):
    header(ui)
    lines = [ui.difftitle] + diff_lines(ui.diff)
    draw_scroll(ui, lines)
    footer(ui, "up/dn scroll  Y back")


# ----------------------------------------------------------------------------- the reversible write
NOTE_TEXT = "hello from picowallet"


def start_write(ui, kind, slot=None):
    """Show what a write would change, then wait for A held: a REVERSIBLE CHANGE, yellow."""
    if kind == "note":
        ui.diff = None
    else:
        target = atecc.CONFIG if kind == "writecfg" else ui.snap
        ui.diff = atecc.diff_config(ui.cfgb, target)
        ui.difftitle = "chip vs " + ("wallet config" if kind == "writecfg" else "saved snapshot")
    ui.action, ui.hold, ui.ret = (kind, slot), None, ui.view
    ui.view = "confirm_write"


def draw_confirm_write(ui):
    d = ui.d
    kind = ui.action[0]
    diff = ui.diff
    header(ui, "REVERSIBLE CHANGE")
    y = 27
    badge(d, "rev", 4, y)
    d.text({"writecfg": "WRITE WALLET CONFIG", "restore": "RESTORE SAVED CONFIG", "note": "WRITE A NOTE INTO SLOT %s" % ui.action[1]}[kind], 18, y, L.YELLOW); y += 12
    d.text("can be restored", 18, y, L.YELLOW); y += 14
    if kind == "note":
        for line in wrap("32 bytes of clear text go into slot %s (plain data, readable in clear). Writing again replaces them, so this can be undone until the data zone is locked." % ui.action[1]):
            d.text(line, 4, y, L.WHITE); y += 12
        y += 6
        d.text('"%s"' % NOTE_TEXT[:27], 4, y, L.WHITE); y += 12
    else:
        for line in diff_lines(diff, full=False)[:6]:
            d.text(line[:29], 4, y, L.WHITE); y += 12
        d.text("I2C address unchanged 0x%02x" % ((ui.cfgb[16] >> 1) if ui.cfgb else 0), 4, y, L.GREEN if not diff["addrChanges"] else L.RED); y += 12
        d.text("config zone stays OPEN", 4, y, L.GREEN); y += 12
    d.center_text("hold A to write", 176, L.YELLOW)
    d.rect(20, 192, 200, 14, L.WHITE)
    if ui.hold is not None:
        w = min(198, 198 * time.ticks_diff(time.ticks_ms(), ui.hold) // ui.HOLD_REV)
        d.fill_rect(21, 193, w, 12, L.YELLOW)
    footer(ui, "B cancel" if kind == "note" else "Y details  B cancel")


def run_write(ui, kind, slot=None):
    """The write itself, then the checks."""
    try:
        if kind == "note":
            ui.sig.write_note(NOTE_TEXT, slot)
            if ui.st.get("dataLocked"):
                back = ui.sig.read_note(slot)
                ui.checks = (("WRITE COMPLETE", True), ("READ BACK: " + back[:14], back == NOTE_TEXT))
                ui.show_result("Slot %d holds the note; READ THE BYTES shows it." % slot, True)
            else:
                ui.checks = (("WRITE COMPLETE", True), ("READ BACK: after data lock", True), ("DATA ZONE STILL OPEN", True))
                ui.show_result("Slot %d took the 32 bytes. The chip will not read them back while the DATA zone is open; "
                               "writing again replaces them meanwhile." % slot, True)
            return
        n = ui.sig.write_config() if kind == "writecfg" else ui.sig.restore_snapshot()
        ui.refresh()
        ui.checks = (("WRITE COMPLETE", True), ("READBACK MATCHES", True), ("CONFIG STILL OPEN", not ui.st.get("configLocked")))
        ui.show_result("%d bytes changed. Nothing has been permanently locked." % n, True)
    except Exception as e:
        ui.refresh()
        ui.checks = (("WRITE COMPLETE", False),)
        if kind == "note":
            ui.show_result("%s." % e, False)
        else:
            ui.show_result("%s. The chip's table may now be a mix: RESTORE SAVED CONFIG puts the snapshot back." % e, False)
    ui.on_change()


# ----------------------------------------------------------------------------- refusals
WRITE_ONLY = ("The rules are sealed, but the DATA zone is still open. While it is open the chip takes clear "
              "writes into slots and OTP but reads nothing back. Reads start once the DATA zone is locked.")


def why_refused(ui, what, status):
    cfg_open = not ui.st.get("configLocked")
    data_open = not ui.st.get("dataLocked")
    if status == 0x0F and not cfg_open and data_open and what in ("otp", "data"):
        return WRITE_ONLY
    if status == 0x0F and cfg_open:
        zone = {"otp": "the OTP zone", "data": "the DATA zone", "counters": "the counters", "keyvalid": "any key"}
        if what in zone:
            return "The CONFIG zone is still open. Until its rules are locked, the chip will not expose %s." % zone[what]
        if what in ("genkey", "sign", "pubkey"):
            return "GenKey and Sign are refused until the CONFIG zone is locked: no key can exist before the rules are sealed."
        return "The chip will not do this while its CONFIG zone is open."
    if status == 0x0F and what == "data":
        return "Slot 8's rules mark it secret: the chip never hands its bytes out in clear. Slots 12 and 13 are the clear ones."
    if status == 0x03:
        return "The chip did not understand the command as sent. That is a firmware bug, not the chip's state."
    if status is None:
        return "The chip did not answer at all: wiring, power, or it fell asleep."
    return atecc.explain(status)


def refuse(ui, what, e, why=None):
    status = getattr(e, "status", None)
    chip = getattr(ui.sig, "chip", None)
    ui.ref = {"what": what, "status": status, "why": why or why_refused(ui, what, status), "err": str(e) if e else "",
              "trace": chip.trace if chip else None}
    ui.ret = ui.view if ui.view not in ("busy",) else ui.ret
    ui.view, ui.dirty = "refused", True


def draw_refused(ui):
    d = ui.d
    r = ui.ref
    header(ui)
    y = 27
    d.text("CHIP SAYS:", 4, y, L.GREY); y += 14
    icon(d, "cross", 6, y, L.RED)
    d.big_text("NOT ALLOWED", 24, y - 1, L.RED, 2)
    y += 22
    d.text("Why?", 4, y, L.YELLOW); y += 12
    for line in wrap(r["why"])[:7]:
        d.text(line, 4, y, L.WHITE); y += 12
    y += 4
    if r["status"] is not None:
        d.text("STATUS 0x%02X" % r["status"], 4, y, L.GREY); y += 12
        for line in wrap(atecc.explain(r["status"]))[:2]:
            d.text(line, 4, y, L.GREY); y += 12
    elif r["err"]:
        for line in wrap(r["err"])[:2]:
            d.text(line, 4, y, L.GREY); y += 12
    footer(ui, "A raw command  Y back" if r["trace"] else "Y back")


def rawcmd_lines(trace):
    if not trace:
        return ["no command was sent"]
    d = trace["data"]
    lines = ["op 0x%02x  p1 0x%02x  p2 0x%04x" % (trace["op"], trace["p1"], trace["p2"]),
             "sent %d data bytes" % len(d)]
    for i in range(0, len(d), 8):
        lines.append("  " + hexs(d[i:i + 8], 8))
    r = trace["resp"]
    if len(r) == 1:
        lines.append("answer: status 0x%02x" % r[0])
        lines += ["  " + l for l in wrap(atecc.explain(r[0]), 27)]
    else:
        lines.append("answer: %d bytes" % len(r))
        for i in range(0, len(r), 8):
            lines.append("  " + hexs(r[i:i + 8], 8))
    lines.append("round trip %d ms" % trace["ms"])
    return lines


def draw_rawcmd(ui):
    header(ui)
    src = ui.ref if ui.view_from == "refused" else ui.lab
    draw_scroll(ui, rawcmd_lines(src["trace"] if src else None))
    footer(ui, "up/dn scroll  Y back")

# The chips this board has seen, by serial: a number, a name and a screen theme for each, so a
# glance at the screen says which chip is in. The first chip seen is chip 1 (dark), the next chip 2
# (light), then dark again. chips.json on flash; every push keeps it (manifest "preserve").
#
# Cosmetic only. Nothing here decides what gets signed: the console's pin (secrets.QUORUM_EXPECT)
# does, from the chip itself, whatever this file says. A chip swapped for another with a doctored
# chips.json still fails the pin.
#
#   entry, new = seen(serial, profile, owner=...)
#   entry: {"n": 2, "name": "chip 2", "theme": "light", "first": unix, "profile": "quorum-v1", ...}
import json
import time

FILE = "chips.json"
THEMES = ("dark", "light")


def load():
    try:
        with open(FILE) as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except (OSError, ValueError):
        return {}       # none yet, or a damaged file: start again (it is only names and colours)


def save(d):
    try:
        with open(FILE + ".tmp", "w") as f:
            json.dump(d, f)
        import os
        os.rename(FILE + ".tmp", FILE)      # whole or not at all
    except OSError as e:
        print("chips:", e)


def _now():
    t = time.time()
    return t if time.gmtime(t)[0] >= 2025 else 0


def seen(serial, profile=None, **extra):
    """This chip's entry, registered the first time it is seen; profile and any extra fields
    (owner, provisioned) brought up to date. -> (entry, new)."""
    if not serial:
        return None, False
    d = load()
    e = d.get(serial)
    new = e is None
    if new:
        n = max([v.get("n", 0) for v in d.values() if isinstance(v, dict)] + [0]) + 1
        e = {"n": n, "name": "chip %d" % n, "theme": THEMES[(n - 1) % 2], "first": _now()}
    changed = new
    for k, v in (("profile", profile),) + tuple(extra.items()):
        if v is not None and e.get(k) != v:
            e[k] = v
            changed = True
    if changed:
        d[serial] = e
        save(d)
    return e, new


PROFILE_SHORT = {"quorum-v1": "quorum v1", "legacy-test": "test table", "factory": "fresh", "unknown": "unknown table",
                 "quorum-tm1": "Trust M", "quorum-tm1-open": "Trust M, open"}

# Layer 5: a Safe transaction's fields in plain language, one item per thing it does. Pure (no
# screen, no network), so test-vectors/run.py checks it on CPython and on MicroPython.
#
# Everything here is decoded from the same to/value/data/operation that safe_tx.py hashes. The
# service's own "dataDecoded" is never read. Names come from the pinned config (quorum_cfg.py) and
# are hints: an item always carries the full address too.
#
#   ctx = context(quorum_cfg.CFG, safe)
#   review(tx, ctx) -> {"summary": "Send 1.5 ETH", "level": "ok" | "warn" | "red", "items": [...]}
#
# An item is a dict: title (one screen header), level, what (one line), and as needed amount,
# to and label (what that address is: "to", "new owner", "spender"...), frm and frm_label (an
# address being replaced or moved from), text (the explanation), and for calls nobody decoded
# selector, size and digest (ERC-8213's calldata digest, to compare with what the proposer sent).
# Items that call a contract carry it as "contract"; identify() says whether it is a known one.
# "red" is anything that can take the Safe away from its owners or pay out more than it shows:
# owner, threshold, module, guard and handler changes, delegatecall, gas refunds, unlimited
# approvals, and every call this file cannot decode.
from binascii import hexlify
from keccak import keccak256

CALL, DELEGATECALL = 0, 1
LEVELS = ("ok", "warn", "red")
ZERO = "0x0000000000000000000000000000000000000000"
UNLIMITED = 1 << 255    # approvals at or above this are "forever" (max uint256 is the usual one)

# selector -> signature. test-vectors/run.py checks every one against keccak.
SIGS = {
    "a9059cbb": "transfer(address,uint256)",
    "095ea7b3": "approve(address,uint256)",
    "23b872dd": "transferFrom(address,address,uint256)",
    "8d80ff0a": "multiSend(bytes)",
    "0d582f13": "addOwnerWithThreshold(address,uint256)",
    "f8dc5dd9": "removeOwner(address,address,uint256)",
    "e318b52b": "swapOwner(address,address,address)",
    "694e80c3": "changeThreshold(uint256)",
    "610b5925": "enableModule(address)",
    "e009cfde": "disableModule(address,address)",
    "e19a9dd9": "setGuard(address)",
    "f08a0323": "setFallbackHandler(address)",
    "85a5affe": "signMessage(bytes)",
}
SIGN_MESSAGE = b"\x85\xa5\xaf\xfe"

DONT = "Don't sign unless you were told exactly what to expect."
AS_SAFE = "Runs this contract's code as the Safe itself: it could move everything and change the owners."


def hx(b):
    return "0x" + hexlify(b).decode()


def _bytes(h):
    if isinstance(h, (bytes, bytearray)):
        return bytes(h)
    h = h[2:] if h.startswith("0x") else h
    return bytes.fromhex(h)


def group(n):
    """12345678 -> 12,345,678"""
    s, out = str(n), ""
    while len(s) > 3:
        out = "," + s[-3:] + out
        s = s[:-3]
    return s + out


def units(n, decimals):
    """An integer amount in its token's units, every significant digit kept: 1500000, 6 -> 1.5"""
    whole, frac = divmod(int(n), 10 ** decimals)
    if not frac:
        return group(whole)
    f = str(frac)
    f = ("0" * (decimals - len(f)) + f).rstrip("0")
    return group(whole) + "." + f


def for_chain(cfg, key, chain):
    """One of cfg's per-chain lists ("tokens", "batchers", "contracts", "delegates") for this chain,
    lowercase: the "*" entries (the same contract everywhere) and the chain's own, or those of the
    chain it is the same as (cfg["sameAs"]: the Anvil fork of Base has Base's). None: every chain's."""
    lists = cfg.get(key, {})
    if chain is None:
        keys = list(lists)
    else:
        c = str(chain)
        keys = ["*", cfg.get("sameAs", {}).get(c, c)]
    out = {}
    for k in keys:
        for a, v in lists.get(k, {}).items():
            out[a.lower()] = v
    return out


def context(cfg, safe, names=None, chain=None):
    """What review() needs from the pinned config, with lowercase keys, for a Safe on this chain.
    names: extra {address: name}, such as this console's own owner address. chain: the pinned
    address book (Alice, Bob...) is the laptop's Anvil accounts, so it names addresses only on the
    chains in cfg["bookChains"]; on Base mainnet those same addresses carry sweeper code
    (docs/LADDER.md). Tokens, batchers, contracts and delegates are this chain's (for_chain)."""
    book = {}
    if chain is None or chain in cfg.get("bookChains", [31337]):
        for a, n in cfg["book"].items():
            book[a.lower()] = n
    for a, n in (names or {}).items():
        book[a.lower()] = n
    return {"safe": safe.lower(), "book": book, "tokens": for_chain(cfg, "tokens", chain),
            "batchers": for_chain(cfg, "batchers", chain), "contracts": for_chain(cfg, "contracts", chain),
            "delegates": for_chain(cfg, "delegates", chain), "messages": for_chain(cfg, "messages", chain)}


def name(ctx, a):
    return ctx["book"].get(a.lower())


def identify(ctx, a):
    """(name, logo, known) for an address: this Safe, a pinned contract, or a name from the
    address book (people have no logo). (None, None, False) for anything else."""
    a = a.lower()
    if a == ctx["safe"]:
        return "This Safe", "safe", True
    k = ctx["contracts"].get(a)
    if k:
        return k[0], k[1], True
    n = ctx["book"].get(a)
    if n:
        return n, None, True
    return None, None, False


# ----------------------------------------------------------------------------- ABI words
def _word(args, i):
    w = args[32 * i:32 * i + 32]
    if len(w) != 32:
        raise ValueError("calldata too short")
    return int.from_bytes(w, "big")


def _addr(args, i):
    n = _word(args, i)
    if n >> 160:
        raise ValueError("not an address")
    return hx(n.to_bytes(20, "big"))


def unpack_multisend(data):
    """multiSend(bytes) calldata -> [(operation, to, value, data), ...]"""
    args = data[4:]
    off = _word(args, 0)
    n = int.from_bytes(args[off:off + 32], "big")
    p = args[off + 32:off + 32 + n]
    if len(p) != n:
        raise ValueError("batch too short")
    calls, i = [], 0
    while i < n:
        if i + 85 > n:
            raise ValueError("batch entry too short")
        op = p[i]
        to = hx(p[i + 1:i + 21])
        value = int.from_bytes(p[i + 21:i + 53], "big")
        ln = int.from_bytes(p[i + 53:i + 85], "big")
        if i + 85 + ln > n:
            raise ValueError("batch entry too short")
        calls.append((op, to, value, p[i + 85:i + 85 + ln]))
        i += 85 + ln
    return calls


def calldata_digest(data):
    """ERC-8213's Calldata Digest: keccak256(uint256(length) || calldata)."""
    return keccak256(len(data).to_bytes(32, "big") + data)


# ----------------------------------------------------------------------------- one call
def _unknown(to, data, why=""):
    sel = hx(data[:4]) if len(data) >= 4 else hx(data)
    return {"title": "UNKNOWN CALL", "level": "red", "what": "Unknown call", "to": to, "label": "contract",
            "text": (why + " " if why else "") + DONT, "selector": sel, "size": len(data), "contract": to,
            "digest": hx(calldata_digest(data))}


def _self_call(sel, args, ctx):
    """The Safe calling itself: its own settings. Every one of these is red."""
    if sel == "0d582f13":
        owner, t = _addr(args, 0), _word(args, 1)
        return {"title": "ADD OWNER", "level": "red", "what": "Add owner", "to": owner, "label": "new owner",
                "text": "Adds this address as an owner, with a vote on everything the Safe does. Approvals needed becomes %d." % t}
    if sel == "f8dc5dd9":
        owner, t = _addr(args, 1), _word(args, 2)
        return {"title": "REMOVE OWNER", "level": "red", "what": "Remove owner", "to": owner, "label": "owner",
                "text": "Removes this owner. Approvals needed becomes %d." % t}
    if sel == "e318b52b":
        old, new = _addr(args, 1), _addr(args, 2)
        return {"title": "SWAP OWNER", "level": "red", "what": "Replace owner", "to": new, "label": "new owner",
                "frm": old, "frm_label": "replaces",
                "text": "Removes one owner and puts the address below in its place, with the same vote."}
    if sel == "694e80c3":
        t = _word(args, 0)
        return {"title": "THRESHOLD", "level": "red", "what": "Approvals needed: %d" % t, "amount": "%d NEEDED" % t,
                "text": "Changes how many owners must approve every transaction from now on, to %d." % t}
    if sel == "610b5925":
        return {"title": "ADD MODULE", "level": "red", "what": "Add module", "to": _addr(args, 0), "label": "module",
                "text": "This contract will be able to move funds and change owners WITHOUT any owner approval."}
    if sel == "e009cfde":
        return {"title": "REMOVE MODULE", "level": "red", "what": "Remove module", "to": _addr(args, 1), "label": "module",
                "text": "Turns off this module; it can no longer act for the Safe."}
    if sel == "e19a9dd9":
        g = _addr(args, 0)
        if g == ZERO:
            return {"title": "REMOVE GUARD", "level": "red", "what": "Remove guard",
                    "text": "Turns off the transaction guard; nothing checks transactions after this."}
        return {"title": "SET GUARD", "level": "red", "what": "Set guard", "to": g, "label": "guard",
                "text": "This contract will check, and can block, every future transaction. A broken guard can lock the Safe for good."}
    if sel == "f08a0323":
        return {"title": "FALLBACK", "level": "red", "what": "Set fallback handler", "to": _addr(args, 0), "label": "handler",
                "text": "This contract answers calls the Safe does not know itself, including checks of messages the Safe has signed."}
    return None


def _token_call(sel, to, args, ctx):
    tok = ctx["tokens"].get(to)
    sym, dec = (tok[0], tok[1]) if tok else ("TOKEN", 0)
    note = "" if tok else " This token is not in the console's list, so the amount is in raw units."
    if sel == "a9059cbb":
        dest, amt = _addr(args, 0), _word(args, 1)
        return {"title": "SEND " + sym, "level": "ok" if tok else "warn", "what": "Send %s %s" % (units(amt, dec), sym),
                "amount": "%s %s" % (units(amt, dec), sym), "to": dest, "text": ("Token " + to + "." + note) if not tok else ""}
    if sel == "095ea7b3":
        sp, amt = _addr(args, 0), _word(args, 1)
        if amt >= UNLIMITED:
            return {"title": "APPROVE " + sym, "level": "red", "what": "Approve UNLIMITED " + sym, "amount": "UNLIMITED " + sym,
                    "to": sp, "label": "spender", "text": "The address below can take every %s this Safe holds, now and later, until someone revokes it.%s" % (sym, note)}
        return {"title": "APPROVE " + sym, "level": "ok" if tok else "warn", "what": "Approve %s %s" % (units(amt, dec), sym),
                "amount": "%s %s" % (units(amt, dec), sym), "to": sp, "label": "spender",
                "text": "The address below may take up to this much from the Safe." + note}
    if sel == "23b872dd":
        src, dest, amt = _addr(args, 0), _addr(args, 1), _word(args, 2)
        return {"title": "MOVE " + sym, "level": "ok" if tok else "warn", "what": "Move %s %s" % (units(amt, dec), sym),
                "amount": "%s %s" % (units(amt, dec), sym), "to": dest, "frm": src, "frm_label": "from",
                "text": "Moves tokens out of another address that approved this Safe." + note}
    return None


def _call(to, value, data, ctx):
    """One plain CALL -> [item]"""
    to = to.lower()
    if not data:
        if to == ctx["safe"] and value == 0:
            return [{"title": "REJECTION", "level": "ok", "what": "On-chain rejection",
                     "text": "Does nothing. Once executed it uses up this transaction number, cancelling every other transaction waiting on it."}]
        if value == 0:
            return [{"title": "EMPTY CALL", "level": "warn", "what": "Empty call", "to": to, "label": "address",
                     "text": "Sends nothing and calls nothing, unless the address is a contract."}]
        return [{"title": "SEND ETH", "level": "ok", "what": "Send %s ETH" % units(value, 18),
                 "amount": units(value, 18) + " ETH", "to": to}]
    if len(data) < 4:
        return [_unknown(to, data)]
    sel, args = hexlify(data[:4]).decode(), data[4:]
    try:
        it = _self_call(sel, args, ctx) if to == ctx["safe"] else _token_call(sel, to, args, ctx)
    except ValueError as e:
        return [_unknown(to, data, "Could not read it (%s)." % e)]
    if it is None:
        k = ctx["contracts"].get(to)
        call = k[2].get(sel) if k else None
        if not call:
            return [_unknown(to, data)]
        it = {"title": "CONTRACT CALL", "level": "warn", "what": call[1], "to": to, "label": "contract",
              "text": "Known contract, but this call isn't decoded here. Confirm what it does with the proposer.",
              "selector": hx(data[:4]), "size": len(data), "digest": hx(calldata_digest(data))}
    it["contract"] = to
    if value:
        it["text"] = (it.get("text", "") + " Also sends %s ETH with the call." % units(value, 18)).strip()
        if it["level"] == "ok":
            it["level"] = "warn"
    return [it]


# ----------------------------------------------------------------------------- a release
def _release(tx, data):
    """A delegatecall to the pinned SignMessageLib that has the Safe sign a message. The console
    signs only one kind: a PicoQuorum release (release.py), and only when the release its origin
    note names gives exactly the D in the calldata. Any other message is refused: a Safe's
    signature on someone's message can authorize spending (a Permit2 permit, an order).
    -> (item, why refused or "")"""
    import release
    msg = None
    if len(data) == 100 and data[4:36] == (32).to_bytes(32, "big") and data[36:68] == (32).to_bytes(32, "big"):
        msg = data[68:100]
    head = {"title": "SAFE MESSAGE", "level": "red", "what": "Sign a message as the Safe"}
    if msg is None:
        return dict(head, text="A message that isn't a single 32-byte digest."), "A message for the Safe to sign that this console can't read. It signs only PicoQuorum releases."
    named = release.from_origin(tx.get("origin"))
    if not named:
        return dict(head, text="Digest %s, with nothing that says what it is." % hx(msg)), "A message for the Safe to sign, with no PicoQuorum release named for it. The console signs only releases it can check."
    v, f, m = named
    try:
        if not release.valid_version(v):
            raise ValueError("version %r" % v)
        d = release.digest(v, f, m)
    except ValueError as e:
        return dict(head, text="The release note can't be read (%s)." % e), "The release named for this message can't be read."
    if d != msg:
        return dict(head, text="The note says release %s, but the digest is another." % v), "The release named doesn't match what the Safe would sign. Signing it could approve something else."
    f = hx(_bytes(f))
    return {"title": "RELEASE", "level": "warn", "what": "Approve release %s" % v, "amount": "Release %s" % v,
            "release": {"version": v, "firmware": f, "manifest": hx(_bytes(m)), "digest": hx(d)},
            "text": "The Safe approves this PicoQuorum release for everyone who runs it: firmware %s\u00b7%s, manifest %s\u2026%s. Nothing is sent." % (
                f[2:6], f[6:10], hx(_bytes(m))[2:8], hx(_bytes(m))[-6:])}, ""


# ----------------------------------------------------------------------------- the transaction
def _gas(tx, ctx):
    gp = int(tx.get("gasPrice") or 0)
    token = (tx.get("gasToken") or ZERO).lower()
    rr = (tx.get("refundReceiver") or ZERO).lower()
    base, stg = int(tx.get("baseGas") or 0), int(tx.get("safeTxGas") or 0)
    if gp:
        if token == ZERO:
            price = units(gp, 18) + " ETH"
        elif token in ctx["tokens"]:
            sym, dec = ctx["tokens"][token]
            price = "%s %s" % (units(gp, dec), sym)
        else:
            price = "%d raw units of the token %s" % (gp, token)
        return {"title": "GAS REFUND", "level": "red", "what": "Pays a gas refund",
                "to": rr if rr != ZERO else None, "label": "paid to",
                "text": "Whoever executes this is paid by the Safe: %s for every unit of gas used, plus %d more units. Paid to %s." % (
                    price, base, "the address below" if rr != ZERO else "whoever sends it")}
    if base or stg or token != ZERO or rr != ZERO:
        return {"title": "GAS FIELDS", "level": "warn", "what": "Unusual gas fields",
                "text": "safeTxGas %d, baseGas %d. No refund is paid because gasPrice is 0." % (stg, base)}
    return None


def worst(items):
    return LEVELS[max([LEVELS.index(i["level"]) for i in items] + [0])]


def review(tx, ctx):
    """The screen's view of a transaction. "refuse" is set when the console must not sign it at
    all, however long A is held: an operation the Safe does not have, or a delegatecall anywhere
    except to a pinned batcher (cfg "batchers", for a multiSend) or a pinned delegate (cfg
    "delegates"). A delegatecall runs the target's code as the Safe itself, so an unpinned one could
    move everything and change the owners (the attack that emptied Bybit's Safe in 2025)."""
    op = int(tx["operation"])
    to = tx["to"].lower()
    value = int(tx["value"])
    data = _bytes(tx.get("data") or "0x")
    items = []
    refuse = ""
    if op not in (CALL, DELEGATECALL):
        refuse = "Operation %d is neither a call nor a delegatecall." % op
    elif op == DELEGATECALL and not (to in ctx["delegates"] or to in ctx["messages"] or (to in ctx["batchers"] and data[:4] == b"\x8d\x80\xff\x0a")):
        refuse = "A delegatecall to a contract this console has not pinned. It would run that code as the Safe itself."
    if op == DELEGATECALL and to in ctx["batchers"] and data[:4] == b"\x8d\x80\xff\x0a":
        try:
            calls = unpack_multisend(data)
        except (ValueError, IndexError) as e:
            calls = None
            items.append(_unknown(to, data, "A batch that could not be read (%s)." % e))
        if calls is not None:
            for iop, ito, ival, idata in calls:
                if iop != CALL:
                    items.append({"title": "DELEGATECALL", "level": "red", "what": "Delegatecall inside a batch", "to": ito,
                                  "label": "contract", "text": AS_SAFE})
                    refuse = refuse or "A delegatecall inside the batch. It would run that code as the Safe itself."
                else:
                    items += _call(ito, ival, idata, ctx)
            summary = "Batch: %d action%s" % (len(calls), "" if len(calls) == 1 else "s")
        else:
            summary = "Unreadable batch"
    elif op == DELEGATECALL and to in ctx["messages"]:
        if data[:4] == SIGN_MESSAGE and not value:
            it, why = _release(tx, data)
        else:
            it, why = (_unknown(to, data, "Only signMessage, with no ETH, is expected here."),
                       "A call to the message library that isn't signMessage.")
        it["contract"] = to
        items.append(it)
        refuse = refuse or why
        summary = it["what"]
    elif op == DELEGATECALL:
        items.append({"title": "DELEGATECALL", "level": "red", "what": "Delegatecall", "to": to, "label": "contract",
                      "text": AS_SAFE, "selector": hx(data[:4]), "size": len(data), "contract": to,
                      "digest": hx(calldata_digest(data))})
        summary = "Delegatecall"
    else:
        items += _call(to, value, data, ctx)
        summary = items[0]["what"]
    g = _gas(tx, ctx)
    if g:
        items.append(g)
    # the contract the Safe calls first (a token, the batch helper, itself), for the header
    return {"summary": summary, "level": worst(items), "items": items, "contract": to if data else None,
            "refuse": refuse}

# Rebuild the ChipAccount Transfer digest on the device. If this does not match the digest the
# app sent, the app is lying about what it wants signed, and the device refuses.
from keccak import keccak256

DOMAIN_TYPEHASH = keccak256(b"EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)")
TRANSFER_TYPEHASH = keccak256(b"Transfer(address token,address to,uint256 amount,uint256 nonce,uint256 deadline)")
SET_NAME_TYPEHASH = keccak256(b"SetName(string name,uint256 nonce,uint256 deadline)")
EXECUTE_TYPEHASH = keccak256(b"Execute(address target,uint256 value,bytes data,uint256 nonce,uint256 deadline)")
CANCEL_RECOVERY_TYPEHASH = keccak256(b"CancelRecovery(uint256 nonce,uint256 deadline)")
NAME_HASH = keccak256(b"ChipAccount")
VERSION_HASH = keccak256(b"1")

_domain_cache = {}


def _addr(a):
    a = a[2:] if a.startswith("0x") else a
    return bytes(12) + bytes.fromhex(a)


def _u256(n):
    return int(n).to_bytes(32, "big")


def domain_separator(chain_id, account):
    key = (chain_id, account.lower())
    if key not in _domain_cache:
        _domain_cache[key] = keccak256(DOMAIN_TYPEHASH + NAME_HASH + VERSION_HASH + _u256(chain_id) + _addr(account))
    return _domain_cache[key]


def transfer_digest(chain_id, account, token, to, amount, nonce, deadline):
    struct = keccak256(TRANSFER_TYPEHASH + _addr(token) + _addr(to) + _u256(amount) + _u256(nonce) + _u256(deadline))
    return keccak256(b"\x19\x01" + domain_separator(chain_id, account) + struct)


def set_name_digest(chain_id, account, name, nonce, deadline):
    struct = keccak256(SET_NAME_TYPEHASH + keccak256(name.encode()) + _u256(nonce) + _u256(deadline))
    return keccak256(b"\x19\x01" + domain_separator(chain_id, account) + struct)


def execute_digest(chain_id, account, target, value, data, nonce, deadline):
    struct = keccak256(EXECUTE_TYPEHASH + _addr(target) + _u256(value) + keccak256(data) + _u256(nonce) + _u256(deadline))
    return keccak256(b"\x19\x01" + domain_separator(chain_id, account) + struct)


def cancel_recovery_digest(chain_id, account, nonce, deadline):
    struct = keccak256(CANCEL_RECOVERY_TYPEHASH + _u256(nonce) + _u256(deadline))
    return keccak256(b"\x19\x01" + domain_separator(chain_id, account) + struct)


def data_hash(data):
    return keccak256(data)

# Anti-aliased text for the 240x240 panel. The glyphs are Atkinson Hyperlegible Next and Mono,
# rendered on the laptop by tools/fonts/gen.py into qf_*.bin (SIL OFL 1.1, tools/fonts/OFL.txt).
# Each glyph is a 4-bit coverage bitmap; framebuf.blit draws it in C through a 16-colour palette
# that runs from the background to the ink, so edges are smooth and nothing is drawn per pixel
# in Python. The one rule: say what the text sits on (bg), because the edges are mixed with it.
#
#   fonts.text(d, "Send 0.05 ETH", x, y, "bold26", (255, 255, 255), (11, 13, 17)) -> x after it
#   fonts.width("0.05 ETH", "bold26"); fonts.wrap(s, 220, "sans14"); fonts.height("sans14")
import framebuf
import os
import struct
import lcd as L

# Named literally, so tools/emu ship copies them to the board with any module that imports this.
FILES = {"sans12": "qf_sans12.bin", "sans14": "qf_sans14.bin", "bold14": "qf_bold14.bin",
         "bold18": "qf_bold18.bin", "bold26": "qf_bold26.bin", "mono13": "qf_mono13.bin",
         "monob28": "qf_monob28.bin"}

EXTRA = {"\u2026": 127, "\u00b7": 128, "\u2014": 129}   # … · —, after "~" (tools/fonts/gen.py)

_fonts = {}
_pal = {}
_set = None                 # a candidate font set from tools/fonts/gen.py --try, or None


class Font:
    def __init__(self, path):
        b = bytearray(os.stat(path)[6])         # framebuf wants a writable buffer
        with open(path, "rb") as f:
            f.readinto(b)
        if b[:3] != b"QF\x01":
            raise ValueError(path + " is not a font")
        self.height, self.ascent, self.first, self.count = b[3], b[4], b[5], b[6]
        self.buf = b
        self.data = memoryview(b)[8 + 8 * self.count:]
        self.glyphs = {}

    def glyph(self, c):
        """(framebuffer or None, xoff, yoff, advance) for one character, built once."""
        g = self.glyphs.get(c)
        if g is None:
            i = EXTRA.get(c, ord(c)) - self.first
            if not 0 <= i < self.count:
                i = ord("?") - self.first
            off, w, h, xo, yo, adv = struct.unpack_from("<HBBbbB", self.buf, 8 + 8 * i)
            fb = framebuf.FrameBuffer(self.data[off:off + h * ((w + 1) // 2)], w, h, framebuf.GS4_HMSB) if w else None
            g = self.glyphs[c] = (fb, xo, yo, adv)
        return g


def get(name):
    f = _fonts.get(name)
    if f is None:
        f = _fonts[name] = Font(FILES[name] if _set is None else "qf_%s_%s.bin" % (_set, name))
    return f


def use(fontset=None):
    """Draw every size in a candidate set (qf_SET_NAME.bin, emulator only); None: our own."""
    global _set
    _set = fontset
    _fonts.clear()
    _w.clear()


def palette(fg, bg):
    """16 colours from bg (coverage 0) to fg (15), as the panel wants them."""
    k = (fg, bg)
    p = _pal.get(k)
    if p is None:
        if len(_pal) > 48:
            _pal.clear()
        p = framebuf.FrameBuffer(bytearray(32), 16, 1, framebuf.RGB565)
        for i in range(16):
            p.pixel(i, 0, L.color(bg[0] + (fg[0] - bg[0]) * i // 15, bg[1] + (fg[1] - bg[1]) * i // 15,
                                  bg[2] + (fg[2] - bg[2]) * i // 15))
        _pal[k] = p
    return p


def text(d, s, x, y, font, fg, bg):
    """Draw s with the top of its line box at y. fg and bg are (r, g, b). Returns x after it."""
    f = get(font)
    if L.BANDS > 1 and (y + f.height + 4 <= d.y0 or y - 4 >= d.y0 + d.band_h):
        return x + width(s, font)       # not in the band being drawn (lcd.LCD.frames)
    p = palette(fg, bg)
    key = L.color(*bg)      # coverage 0 is the background itself: leave those pixels alone
    for c in s:
        fb, xo, yo, adv = f.glyph(c)
        if fb:
            d.blit(fb, x + xo, y + yo, key, p)
        x += adv
    return x


_w = {}


def width(s, font):
    """Remembered: a banded screen (lcd.py) measures every string once per band, and fit() and the
    right-aligned text measure the same ones over and over (~0.5 s a frame on Build 1, uncached)."""
    k = (s, font)
    n = _w.get(k)
    if n is None:
        f = get(font)
        n = sum(f.glyph(c)[3] for c in s)
        if len(_w) >= 160:
            _w.clear()
        _w[k] = n
    return n


def height(font):
    return get(font).height


def wrap(s, w, font):
    """Words into lines no wider than w pixels. A word wider than a line is cut."""
    out, line = [], ""
    for word in s.split(" "):
        while width(word, font) > w:
            if line:
                out.append(line)
                line = ""
            n = len(word)
            while n > 1 and width(word[:n], font) > w:
                n -= 1
            out.append(word[:n])
            word = word[n:]
        cand = line + " " + word if line else word
        if width(cand, font) > w and line:
            out.append(line)
            line = word
        else:
            line = cand
    if line:
        out.append(line)
    return out

# The screen and the keys, for the board in board.py (secrets.BOARD):
#   waveshare: Pico-LCD-1.3, 240x240 ST7789 over SPI1, joystick and A/B/X/Y
#              (pins from waveshare.com/wiki/Pico-LCD-1.3)
#   build1:    2.0" 240x320 ST7789 run landscape as 320x240 on the same SPI pins, the knob
#              (knob.py) and A/B/X/Y (hardware/wiring/BUILD1.md). The console draws at
#              full native resolution, using small horizontal strips.
# W and H are the size the apps draw, in pixels; draw with them rather than with numbers.
#
# Bands (board.BANDS > 1, the 320x240 panels): the framebuffer holds one horizontal strip of the
# screen, W x BAND_H. A frame is drawn once per strip by LCD.frames(draw, ...): every drawing call
# is shifted into the strip, framebuf clips the rest, and show() sends the strip to its rows. The
# drawing code doesn't know; it only has to start from frames() (quorum.py, splash.py do).
from machine import Pin, SPI, PWM
import framebuf, time
import board

BOARD, KNOB, W, H, SMALL = board.BOARD, board.KNOB, board.W, board.H, board.SMALL
DC, CS, SCK, MOSI, RST, BL = board.DC, board.CS, board.SCK, board.MOSI, board.RST, board.BL
KEYS = board.KEYS


def color(r, g, b):
    """RGB888 -> RGB565, byte-swapped because framebuf is little-endian and the panel wants big-endian."""
    c = ((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3)
    return ((c & 0xFF) << 8) | (c >> 8)


BLACK, WHITE = color(0, 0, 0), color(255, 255, 255)
RED, GREEN, BLUE = color(255, 0, 0), color(0, 255, 0), color(0, 0, 255)
YELLOW, GREY, DARK = color(255, 220, 0), color(120, 120, 120), color(30, 30, 30)


# The one 115 KB framebuffer, allocated the moment lcd is imported. On an RP2040 board (264 KB
# RAM) a block that big is only available on a fresh heap: after a 20 KB module like wallet.py
# has been compiled the heap is too fragmented and LCD() dies with MemoryError. So anything that
# runs a big module (main.py, the emulator's send) imports lcd first, and LCD() reuses this.
BANDS = board.BANDS
BAND_H = H // BANDS
_BUF = bytearray(W * BAND_H * 2)


class LCD(framebuf.FrameBuffer):
    def __init__(self):
        self.width, self.height = W, H
        self.y0, self.band_h = 0, BAND_H     # the strip in the buffer: rows y0 .. y0 + band_h - 1
        self.cs = Pin(CS, Pin.OUT, value=1)
        self.rst = Pin(RST, Pin.OUT, value=1)
        self.dc = Pin(DC, Pin.OUT, value=1)
        self.spi = SPI(1, board.SPI_BAUD, polarity=0, phase=0, sck=Pin(SCK), mosi=Pin(MOSI), miso=None)
        self.bl = PWM(Pin(BL))
        self.bl.freq(1000)
        self.backlight(100)
        self.buffer = _BUF
        super().__init__(self.buffer, W, BAND_H, framebuf.RGB565)
        self._init_panel()

    def backlight(self, pct):
        self.bl.duty_u16(int(65535 * pct / 100))

    def _cmd(self, cmd, data=None):
        self.dc(0); self.cs(0); self.spi.write(bytes([cmd])); self.cs(1)
        if data:
            self.dc(1); self.cs(0); self.spi.write(bytes(data)); self.cs(1)

    def _init_panel(self):
        if KNOB:
            self._init_build1()
            return
        self.rst(1); time.sleep_ms(10); self.rst(0); time.sleep_ms(10); self.rst(1); time.sleep_ms(120)
        self._cmd(0x36, [0x70])        # memory access: landscape, matches Waveshare demo
        self._cmd(0x3A, [0x05])        # 16-bit color
        self._cmd(0xB2, [0x0C, 0x0C, 0x00, 0x33, 0x33])
        self._cmd(0xB7, [0x35])
        self._cmd(0xBB, [0x19])
        self._cmd(0xC0, [0x2C])
        self._cmd(0xC2, [0x01])
        self._cmd(0xC3, [0x12])
        self._cmd(0xC4, [0x20])
        self._cmd(0xC6, [0x0F])
        self._cmd(0xD0, [0xA4, 0xA1])
        self._cmd(0xE0, [0xD0, 0x04, 0x0D, 0x11, 0x13, 0x2B, 0x3F, 0x54, 0x4C, 0x18, 0x0D, 0x0B, 0x1F, 0x23])
        self._cmd(0xE1, [0xD0, 0x04, 0x0C, 0x11, 0x13, 0x2C, 0x3F, 0x44, 0x51, 0x2F, 0x1F, 0x1F, 0x20, 0x23])
        self._cmd(0x21)                # inversion on
        self._cmd(0x11)                # sleep out
        time.sleep_ms(120)
        self._cmd(0x29)                # display on

    def _init_build1(self):
        """The bare ST7789 on build1: its own power-on defaults, as bench1.py's Screen."""
        self.rst(1); time.sleep_ms(10); self.rst(0); time.sleep_ms(20); self.rst(1); time.sleep_ms(150)
        self._cmd(0x01)                # software reset
        time.sleep_ms(150)
        self._cmd(0x11)                # sleep out
        time.sleep_ms(120)
        self._cmd(0x3A, [0x55])        # 16-bit color
        self._cmd(0x36, [board.MADCTL])
        self._cmd(0x21)                # inversion on (IPS)
        self._cmd(0x13)                # normal display mode
        self._cmd(0x29)                # display on
        time.sleep_ms(20)
        if (board.PANEL_W, board.PANEL_H) != (W, H):
            self._clear_panel()

    def _clear_panel(self):
        """Black over the whole panel, margins included, from the buffer while it is still all zeros."""
        n = board.PANEL_W * board.PANEL_H * 2
        self._window(0, 0, board.PANEL_W, board.PANEL_H)
        self.dc(1); self.cs(0)
        mv = memoryview(self.buffer)
        while n > 0:
            k = min(n, len(mv))
            self.spi.write(mv[:k])
            n -= k
        self.cs(1)

    def _window(self, x, y, w, h):
        self._cmd(0x2A, [x >> 8, x & 0xFF, (x + w - 1) >> 8, (x + w - 1) & 0xFF])
        self._cmd(0x2B, [y >> 8, y & 0xFF, (y + h - 1) >> 8, (y + h - 1) & 0xFF])
        self._cmd(0x2C)

    def frames(self, draw, *args, rows=None):
        """Run draw(*args) once per band; draw ends with show() as always. One band: just once.
        rows, [(y0, y1), ...] in screen rows: only the bands they touch; the rest of the panel keeps
        what it shows (a knob turn that moved the focus, quorum.turned)."""
        if BANDS == 1:
            return draw(*args)
        try:
            for y0 in range(0, H, BAND_H):
                if rows and not any(a < y0 + BAND_H and b > y0 for a, b in rows):
                    continue
                self.y0 = y0
                draw(*args)
        finally:
            self.y0 = 0

    def show(self):
        self._window(board.X_OFF, board.Y_OFF + self.y0, W, BAND_H)
        self.dc(1); self.cs(0); self.spi.write(self.buffer); self.cs(1)

    def big_text(self, s, x, y, c, scale=2):
        """framebuf's 8x8 font scaled up. Slow-ish, fine for a few words."""
        w = 8 * len(s)
        tmp = framebuf.FrameBuffer(bytearray(w * 8 // 8), w, 8, framebuf.MONO_HLSB)
        tmp.text(s, 0, 0, 1)
        for yy in range(8):
            for xx in range(w):
                if tmp.pixel(xx, yy):
                    self.fill_rect(x + xx * scale, y + yy * scale, scale, scale, c)

    def center_text(self, s, y, c, scale=1):
        x = (self.width - 8 * len(s) * scale) // 2
        if scale == 1:
            self.text(s, x, y, c)
        else:
            self.big_text(s, x, y, c, scale)


class Keys:
    """Every key on the board by name. On build1 the knob adds "down"/"up" (a detent each way) and
    "press" (its push), and A/B/X/Y read high until they are wired."""

    def __init__(self):
        self.pins = {k: Pin(p, Pin.IN, Pin.PULL_UP) for k, p in KEYS.items()}
        self.last = {k: 1 for k in KEYS}
        self.knob = None
        if KNOB:
            import knob
            self.knob = knob.Knob()

    def pressed(self):
        """Names of keys that went down since the last call."""
        out = self.knob.pressed() if self.knob else []
        for k, p in self.pins.items():
            v = p.value()
            if v == 0 and self.last[k] == 1:
                out.append(k)
            self.last[k] = v
        return out

    def held(self, k):
        if self.knob and k == "press":
            return self.knob.held()
        return self.pins[k].value() == 0


class BandLCD(LCD):
    """LCD for board.BANDS > 1: every call takes screen coordinates and lands in the current band.
    Anything wholly outside the band is skipped before framebuf sees it."""

    def _out(self, y, h):
        return y + h <= self.y0 or y >= self.y0 + BAND_H

    def fill(self, c):
        super().fill(c)

    def pixel(self, x, y, *c):
        return super().pixel(x, y - self.y0, *c)

    def hline(self, x, y, w, c):
        if not self._out(y, 1):
            super().hline(x, y - self.y0, w, c)

    def vline(self, x, y, h, c):
        if not self._out(y, h):
            super().vline(x, y - self.y0, h, c)

    def line(self, x0, y0, x1, y1, c):
        if not self._out(min(y0, y1), abs(y1 - y0) + 1):
            super().line(x0, y0 - self.y0, x1, y1 - self.y0, c)

    def rect(self, x, y, w, h, c, f=False):
        if not self._out(y, h):
            super().rect(x, y - self.y0, w, h, c, f)

    def fill_rect(self, x, y, w, h, c):
        if not self._out(y, h):
            super().fill_rect(x, y - self.y0, w, h, c)

    def text(self, s, x, y, c=1):
        if not self._out(y, 8):
            super().text(s, x, y - self.y0, c)

    def ellipse(self, x, y, xr, yr, c, f=False, m=15):
        if not self._out(y - yr, 2 * yr + 1):
            super().ellipse(x, y - self.y0, xr, yr, c, f, m)

    def poly(self, x, y, coords, c, f=False):
        super().poly(x, y - self.y0, coords, c, f)

    def blit(self, fb, x, y, key=-1, palette=None):
        super().blit(fb, x, y - self.y0, key, palette)


if BANDS > 1:
    LCD = BandLCD

