# NIST P-256 ECDSA in pure Python. Runs on MicroPython (RP2350: ~1 s per signature).
# Stand-in for the ATECC608 until it is wired. Same output shape: (r, s) with low s.
import os

P = 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
A = P - 3
B = 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B
GX = 0x6B17D1F2E12C4247F8BCE6E563A440F277037D812DEB33A0F4A13945D898C296
GY = 0x4FE342E2FE1A7F9B8EE7EB4A7C0F9E162BCE33576B315ECECBB6406837BF51F5


def inv(a, m):
    return pow(a, m - 2, m)


# Jacobian coordinates (X, Y, Z); the point at infinity is None.
def _dbl(pt):
    if pt is None:
        return None
    X, Y, Z = pt
    if Y == 0:
        return None
    S = (4 * X * Y * Y) % P
    Zsq = Z * Z
    M = (3 * (X - Zsq) * (X + Zsq)) % P  # a = -3 shortcut
    X3 = (M * M - 2 * S) % P
    Y3 = (M * (S - X3) - 8 * Y * Y * Y * Y) % P
    Z3 = (2 * Y * Z) % P
    return (X3, Y3, Z3)


def _add(p1, p2):
    if p1 is None:
        return p2
    if p2 is None:
        return p1
    X1, Y1, Z1 = p1
    X2, Y2, Z2 = p2
    Z1sq = Z1 * Z1 % P
    Z2sq = Z2 * Z2 % P
    U1 = X1 * Z2sq % P
    U2 = X2 * Z1sq % P
    S1 = Y1 * Z2sq * Z2 % P
    S2 = Y2 * Z1sq * Z1 % P
    if U1 == U2:
        if S1 != S2:
            return None
        return _dbl(p1)
    H = (U2 - U1) % P
    R = (S2 - S1) % P
    Hsq = H * H % P
    Hcu = Hsq * H % P
    U1Hsq = U1 * Hsq % P
    X3 = (R * R - Hcu - 2 * U1Hsq) % P
    Y3 = (R * (U1Hsq - X3) - S1 * Hcu) % P
    Z3 = H * Z1 * Z2 % P
    return (X3, Y3, Z3)


def _mul(k, pt):
    acc = None
    while k:
        if k & 1:
            acc = _add(acc, pt)
        pt = _dbl(pt)
        k >>= 1
    return acc


def _affine(pt):
    X, Y, Z = pt
    zi = inv(Z, P)
    zi2 = zi * zi % P
    return (X * zi2 % P, Y * zi2 * zi % P)


def pubkey(d):
    """Private scalar -> (x, y)."""
    return _affine(_mul(d, (GX, GY, 1)))


def rand_scalar():
    while True:
        k = int.from_bytes(os.urandom(32), "big")
        if 0 < k < N:
            return k


def sign(d, digest, k=None):
    """ECDSA over a 32-byte digest. Returns (r, s) with s in the low half, as the verifier requires."""
    z = int.from_bytes(digest, "big")
    while True:
        k = k or rand_scalar()
        x, _ = _affine(_mul(k, (GX, GY, 1)))
        r = x % N
        if r == 0:
            k = None
            continue
        s = (inv(k, N) * (z + r * d)) % N
        if s == 0:
            k = None
            continue
        if s > N // 2:
            s = N - s
        return r, s


def verify(qx, qy, digest, r, s):
    if not (0 < r < N and 0 < s < N):
        return False
    z = int.from_bytes(digest, "big")
    w = inv(s, N)
    u1 = z * w % N
    u2 = r * w % N
    pt = _add(_mul(u1, (GX, GY, 1)), _mul(u2, (qx, qy, 1)))
    if pt is None:
        return False
    x, _ = _affine(pt)
    return x % N == r

# The console's rules that need no screen, no network and no chip, so they are tested on their own
# (test-vectors/run-console.mjs). quorum.py calls these; nothing here draws or talks to anything.

HEX = "0123456789abcdef"


def is_address(a):
    return isinstance(a, str) and len(a) == 42 and a[:2] in ("0x", "0X") and all(c in HEX for c in a[2:].lower())


def pins(expect):
    """secrets.QUORUM_EXPECT as a list: one pinned chip (a dict) or several (a list of them)."""
    if not expect:
        return []
    return [p for p in (expect if isinstance(expect, (list, tuple)) else [expect]) if isinstance(p, dict)]


def pick(pinned, serial):
    """The pinned entry for the chip with this serial, or None: the board may pin several chips,
    and at boot the one on the bus says which entry applies."""
    for p in pinned:
        if serial and str(p.get("serial", "")).lower() == serial.lower():
            return p
    return None


def expect_check(expect, serial, slot, row, owner):
    """Is this the chip, slot and key the board was pinned to (secrets.QUORUM_EXPECT)?
    expect: {"serial", "slot", "owner", "locked"}; row: atecc.decode_slot for the slot (None on a
    software key); owner: the owner address computed from the chip's public key. -> (ok, why)."""
    if not expect:
        return False, "no QUORUM_EXPECT in secrets.py"
    want = str(expect.get("serial", "")).lower()
    if not want or serial.lower() != want:
        return False, "another chip is in the board"
    if int(expect.get("slot", -1)) != slot:
        return False, "not the pinned slot"
    if row is None:
        return False, "no slot table"
    if row.get("kind") != "P256" or not row.get("extSign"):
        return False, "slot %d is not a signing key" % slot
    if expect.get("locked", True) and not row.get("locked"):
        return False, "slot %d is not locked" % slot
    want_owner = str(expect.get("owner", "")).lower()
    if not owner or owner.lower() != want_owner:
        return False, "its owner is not the pinned one"
    return True, ""


MAX_SAFES = 4       # each one is a queue and a set of decoded transactions in RAM


def safes(many, one):
    """secrets.QUORUM_SAFES (a list) or QUORUM_SAFE (one) as a checked list of
    {"chainId", "address", "name"} (and "url" when one names its own service, overriding the
    chain's). -> (list, why): why says what was dropped, or ""."""
    given = many if many else ([one] if one else [])
    if not isinstance(given, (list, tuple)):
        return [], "QUORUM_SAFES is not a list"
    out, seen, why = [], set(), ""
    for s in given:
        try:
            c, a = int(s["chainId"]), str(s["address"]).lower()
        except (KeyError, TypeError, ValueError):
            why = why or "a Safe without chainId or address"
            continue
        if not is_address(a):
            why = why or "a Safe with a bad address"
            continue
        if (c, a) in seen:
            continue
        if len(out) == MAX_SAFES:
            why = why or "more than %d Safes: the rest are not watched" % MAX_SAFES
            break
        seen.add((c, a))
        e = {"chainId": c, "address": a, "name": str(s.get("name") or "Safe")[:24]}
        if isinstance(s.get("url"), str) and s["url"]:
            e["url"] = s["url"]         # this Safe's own service (a second simulated Safe on the laptop)
        out.append(e)
    return out, why


def service_url(cfg, chain, override=None):
    """Where to ask about a Safe on this chain: secrets.QUORUM_URL when set (the laptop's
    simulation or fork), else Safe's own service for the chain, pinned in cfg["services"]. None for
    a chain the console has no service for."""
    if override:
        return override
    return cfg.get("services", {}).get(str(chain))


def valid_info(info, safe):
    """The service's view of the Safe, checked for shape before anything shows or uses it.
    -> (ok, why)."""
    if not isinstance(info, dict):
        return False, "not an object"
    if str(info.get("address", safe)).lower() != safe.lower():
        return False, "another Safe"
    owners = info.get("owners")
    if not isinstance(owners, list) or not owners or not all(is_address(o) for o in owners):
        return False, "bad owner list"
    try:
        t = int(info.get("threshold"))
        int(info.get("nonce"))
    except (TypeError, ValueError):
        return False, "bad threshold or nonce"
    if not 1 <= t <= len(owners):
        return False, "threshold %d of %d owners" % (t, len(owners))
    return True, ""


def counter_check(stored, now):
    """The chip's signature counter against the one this console last wrote down.
    -> ("first" | "same" | "outside" | "backwards", signatures made outside the console)."""
    if stored is None:
        return "first", 0
    if now == stored:
        return "same", 0
    if now > stored:
        return "outside", now - stored
    return "backwards", 0


def is_sim(base):
    """tools/quorum's simulated service on the laptop (plain HTTP on the LAN) has its own /sim
    endpoints; Safe's real service (HTTPS) must never be sent those."""
    return bool(base) and base.startswith("http://")


def poll_defaults(base, api_key):
    """(active, idle) poll periods in seconds. The real service counts requests against a monthly
    quota: 50,000 with an API key, 5,000 without (each poll is about one request)."""
    if is_sim(base):
        return 3, 120
    if api_key:
        return 20, 600
    return 60, 1800

# Battery and USB state for the perfboard build (hardware/wiring/SOLDERING.md): an 18650 behind a switch and a
# Schottky diode into VSYS, and a 100k/100k divider from the switched battery side to GP28 so the
# wallet can show the cell voltage. Everything here is optional: with nothing wired, or the switch
# off, GP28 sits between 0 and about 1 V (a floating pin, or the Schottky's reverse leakage from
# VSYS through the divider: 1.08 V measured on the perfboard build with the cell out). Anything
# under NO_CELL counts as no cell and the home screen just shows USB.
#
# Why not read VSYS on the Pico's own ADC3 (GP29)? On the Pico W / Pico 2 W that pin doubles as
# the WiFi chip's SPI clock, and borrowing it while the wallet keeps WiFi up is a gamble. A
# divider on a free ADC pin costs two resistors and a capacitor, and never touches the radio.
from machine import ADC, Pin

SENSE_PIN = 28          # GP28 / ADC2, physical pin 34; free on the Waveshare Pico-LCD-1.3
DIVIDER = 2.0           # (R_top + R_bottom) / R_bottom: 100k over 100k
VREF = 3.3
FULL, EMPTY = 4.15, 3.3     # an 18650 under a light load; the Pico's regulator quits well below 3.0
LOW = 3.45                  # warn here; a few percent left
NO_CELL = 2.5               # below this it is leakage or a floating pin: a protected 18650 cuts off near 2.5 V

_adc = None
_vbus = None


def _init():
    global _adc, _vbus
    if _adc is None:
        _adc = ADC(Pin(SENSE_PIN))
    if _vbus is None:
        # VBUS presence: WL_GPIO2 on the Pico W / Pico 2 W, GP24 on a plain Pico
        for name in ("WL_GPIO2", 24):
            try:
                _vbus = Pin(name, Pin.IN)
                break
            except Exception:
                pass


def vbat():
    """Volts at the divider. Near 0 with nothing wired; up to about 1 V of diode leakage with the
    switch off. percent() and status() treat anything under NO_CELL as no cell."""
    _init()
    try:
        raw = sum(_adc.read_u16() for _ in range(8)) // 8
    except Exception:
        return 0.0
    return raw * VREF / 65535 * DIVIDER


def usb():
    """True when VBUS is present (USB plugged in)."""
    _init()
    try:
        return bool(_vbus.value()) if _vbus else True
    except Exception:
        return True


def percent(v=None):
    v = vbat() if v is None else v
    if v < NO_CELL:
        return None
    return max(0, min(100, int((v - EMPTY) * 100 / (FULL - EMPTY))))


def status():
    v = vbat()
    return {"usb": usb(), "vbat": round(v, 2), "percent": percent(v), "low": NO_CELL <= v < LOW}

# A log that survives power cycles: one line per event in log.txt, the older half in log.1.txt.
# Each line is appended and the file closed straight away: MicroPython's LittleFS keeps nothing
# that was not closed (a backup made with one open().write() came out 0 bytes, BUILDLOG 2026-09-25).
# `tools/fw logs` pulls both files. Never raises: a full flash must not stop a signature.
import time

FILE, OLD = "log.txt", "log.1.txt"
MAX = 16 * 1024
_size = None
_last = {}          # message -> (ticks of first sighting, repeats since): see once()


def _stamp():
    t = time.gmtime()
    if t[0] >= 2025:
        return "%04d-%02d-%02d %02d:%02d:%02d" % t[:6]
    return "+%ds" % (time.ticks_ms() // 1000)     # clock not set yet (NTP): seconds since boot


def write(msg):
    global _size
    try:
        import os
        if _size is None:
            try:
                _size = os.stat(FILE)[6]
            except OSError:
                _size = 0
        if _size > MAX:
            try:
                os.remove(OLD)
            except OSError:
                pass
            os.rename(FILE, OLD)
            _size = 0
        line = "%s %s\n" % (_stamp(), msg)
        with open(FILE, "a") as f:
            f.write(line)
        _size += len(line)
    except Exception as e:
        print("qlog:", e)


def once(msg, every_ms=600000):
    """For errors that repeat on every poll: the first one is written, then a count every 10 min."""
    now = time.ticks_ms()
    seen = _last.get(msg)
    if seen is None:
        _last[msg] = (now, 0)
        if len(_last) > 20:
            _last.pop(next(iter(_last)))
        write(msg)
    elif time.ticks_diff(now, seen[0]) > every_ms:
        write("%s (x%d)" % (msg, seen[1] + 1))
        _last[msg] = (now, 0)
    else:
        _last[msg] = (seen[0], seen[1] + 1)

# A small QR code encoder for the Pico: versions 1 to 6 (21 to 41 modules), error correction L or M,
# alphanumeric or byte mode, Reed-Solomon over GF(256), all eight masks scored as the spec asks.
# Pure Python so the same file runs on the laptop for tests. encode(text) returns (n, rows) in the
# form wallet.draw_qr and slots draw: n modules a side, rows[r] an int whose bit c is the dark module
# at column c. A 130-character uppercase hex key fits version 5 (37 modules) at level L.
ALNUM = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:"
# per version: total codewords, then per level: (ec codewords per block, number of blocks)
TOTAL = (0, 26, 44, 70, 100, 134, 172)
BLOCKS = {"L": (None, (7, 1), (10, 1), (15, 1), (20, 1), (26, 1), (18, 2)),
          "M": (None, (10, 1), (16, 1), (26, 1), (18, 2), (24, 2), (16, 4))}
LEVEL_BITS = {"L": 1, "M": 0}

_EXP = [0] * 512
_LOG = [0] * 256
_x = 1
for _i in range(255):
    _EXP[_i] = _x
    _LOG[_x] = _i
    _x <<= 1
    if _x & 0x100:
        _x ^= 0x11D
for _i in range(255, 512):
    _EXP[_i] = _EXP[_i - 255]


def _mul(a, b):
    return 0 if a == 0 or b == 0 else _EXP[_LOG[a] + _LOG[b]]


def _rs(data, nec):
    """Reed-Solomon error-correction codewords for one block."""
    gen = [1]                       # coefficients, highest degree first; times (x + a^i) each round
    for i in range(nec):
        gen = [g ^ (_mul(gen[j - 1], _EXP[i]) if j else 0) for j, g in enumerate(gen + [0])]
    rem = [0] * nec
    for d in data:
        f = d ^ rem[0]
        rem = rem[1:] + [0]
        if f:
            for j in range(nec):
                rem[j] ^= _mul(gen[j + 1], f)
    return rem


def _bits(text, version, level):
    """Mode, count, data, terminator, padding: the data codewords, or None if it does not fit."""
    nec, nb = BLOCKS[level][version]
    cap = TOTAL[version] - nec * nb
    out = []
    alnum = all(c in ALNUM for c in text)
    if alnum:
        out.append((2, 4)); out.append((len(text), 9))
        for i in range(0, len(text) - 1, 2):
            out.append((ALNUM.index(text[i]) * 45 + ALNUM.index(text[i + 1]), 11))
        if len(text) % 2:
            out.append((ALNUM.index(text[-1]), 6))
    else:
        b = text.encode()
        out.append((4, 4)); out.append((len(b), 8))
        for c in b:
            out.append((c, 8))
    n = sum(w for _, w in out)
    if n > cap * 8:
        return None
    out.append((0, min(4, cap * 8 - n)))
    acc, nacc, cw = 0, 0, []
    for v, w in out:
        acc = (acc << w) | v
        nacc += w
        while nacc >= 8:
            cw.append((acc >> (nacc - 8)) & 0xFF)
            nacc -= 8
    if nacc:
        cw.append((acc << (8 - nacc)) & 0xFF)
    pad = (0xEC, 0x11)
    while len(cw) < cap:
        cw.append(pad[len(cw) % 2])
    return cw


def _codewords(data, version, level):
    """Split into blocks, add EC, interleave."""
    nec, nb = BLOCKS[level][version]
    short = len(data) // nb
    blocks, k = [], 0
    for i in range(nb):
        size = short + (1 if i >= nb - len(data) % nb else 0) if len(data) % nb else short
        blocks.append(data[k:k + size]); k += size
    ecs = [_rs(b, nec) for b in blocks]
    out = []
    for i in range(max(len(b) for b in blocks)):
        for b in blocks:
            if i < len(b):
                out.append(b[i])
    for i in range(nec):
        for e in ecs:
            out.append(e[i])
    return out


def _matrix(version):
    """Function patterns and a mask of reserved modules. Returns (grid, reserved)."""
    n = 17 + 4 * version
    g = [[0] * n for _ in range(n)]
    r = [[0] * n for _ in range(n)]

    def finder(x, y):
        for i in range(-1, 8):
            for j in range(-1, 8):
                if 0 <= x + i < n and 0 <= y + j < n:
                    v = 1 if (0 <= i <= 6 and 0 <= j <= 6 and (i in (0, 6) or j in (0, 6) or (2 <= i <= 4 and 2 <= j <= 4))) else 0
                    g[y + j][x + i] = v
                    r[y + j][x + i] = 1
    finder(0, 0); finder(n - 7, 0); finder(0, n - 7)
    for i in range(8, n - 8):
        g[6][i] = g[i][6] = 1 - i % 2
        r[6][i] = r[i][6] = 1
    if version >= 2:
        c = 4 * version + 10
        for i in range(-2, 3):
            for j in range(-2, 3):
                g[c + j][c + i] = 1 if (abs(i) == 2 or abs(j) == 2 or (i == 0 and j == 0)) else 0
                r[c + j][c + i] = 1
    g[4 * version + 9][8] = 1
    r[4 * version + 9][8] = 1
    for i in range(9):          # format info around the top-left finder
        if i != 6:
            r[8][i] = r[i][8] = 1
    for i in range(8):          # its second copy: row 8 on the right, column 8 at the bottom
        r[8][n - 1 - i] = 1
        r[n - 1 - i][8] = 1
    return g, r


def _place(g, r, cw):
    n = len(g)
    bits = []
    for c in cw:
        for k in range(7, -1, -1):
            bits.append((c >> k) & 1)
    i, up, col = 0, True, n - 1
    while col > 0:
        if col == 6:
            col -= 1
        rows = range(n - 1, -1, -1) if up else range(n)
        for row in rows:
            for dx in (0, 1):
                x = col - dx
                if not r[row][x]:
                    g[row][x] = bits[i] if i < len(bits) else 0
                    i += 1
        up = not up
        col -= 2


def _mask(g, r, m):
    n = len(g)
    out = [row[:] for row in g]
    for i in range(n):
        for j in range(n):
            if r[i][j]:
                continue
            if m == 0: f = (i + j) % 2 == 0
            elif m == 1: f = i % 2 == 0
            elif m == 2: f = j % 3 == 0
            elif m == 3: f = (i + j) % 3 == 0
            elif m == 4: f = (i // 2 + j // 3) % 2 == 0
            elif m == 5: f = (i * j) % 2 + (i * j) % 3 == 0
            elif m == 6: f = ((i * j) % 2 + (i * j) % 3) % 2 == 0
            else: f = ((i + j) % 2 + (i * j) % 3) % 2 == 0
            if f:
                out[i][j] ^= 1
    return out


def _format(g, level, m):
    n = len(g)
    v = (LEVEL_BITS[level] << 3) | m
    f = v << 10
    for i in range(14, 9, -1):
        if f >> i & 1:
            f ^= 0x537 << (i - 10)
    f = ((v << 10) | f) ^ 0x5412
    bits = [(f >> i) & 1 for i in range(14, -1, -1)]
    # around the top-left finder
    pos = [(8, 0), (8, 1), (8, 2), (8, 3), (8, 4), (8, 5), (8, 7), (8, 8), (7, 8), (5, 8), (4, 8), (3, 8), (2, 8), (1, 8), (0, 8)]
    for (row, col), b in zip(pos, bits):
        g[row][col] = b
    # split copy: bottom-left column 8 and top-right row 8
    for k in range(7):
        g[n - 1 - k][8] = bits[k]
    for k in range(7, 15):
        g[8][n - 15 + k] = bits[k]


def _penalty(g):
    n = len(g)
    p = 0
    for lines in (g, [[g[i][j] for i in range(n)] for j in range(n)]):
        for line in lines:
            run, prev = 0, -1
            for v in line:
                if v == prev:
                    run += 1
                else:
                    if run >= 5:
                        p += run - 2
                    run, prev = 1, v
            if run >= 5:
                p += run - 2
            s = "".join("1" if v else "0" for v in line)
            p += 40 * (s.count("10111010000") + s.count("00001011101"))
    for i in range(n - 1):
        for j in range(n - 1):
            if g[i][j] == g[i][j + 1] == g[i + 1][j] == g[i + 1][j + 1]:
                p += 3
    dark = sum(sum(row) for row in g)
    k = abs(dark * 100 // (n * n) - 50) // 5
    return p + 10 * k


def encode(text, level="L", max_version=6, mask=None):
    """(n, rows) for the smallest version that fits, best mask by penalty (or `mask`, for tests)."""
    for version in range(1, max_version + 1):
        data = _bits(text, version, level)
        if data is not None:
            break
    else:
        raise ValueError("too long for version %d" % max_version)
    cw = _codewords(data, version, level)
    base, reserved = _matrix(version)
    _place(base, reserved, cw)
    best, best_p = None, None
    for m in (range(8) if mask is None else (mask,)):
        g = _mask(base, reserved, m)
        _format(g, level, m)
        p = _penalty(g)
        if best_p is None or p < best_p:
            best, best_p = g, p
    n = len(best)
    rows = []
    for row in best:
        bits = 0
        for c, v in enumerate(row):
            if v:
                bits |= 1 << c
        rows.append(bits)
    return n, rows

# The console's screens, drawn from quorum.py's state (passed in as q). Nothing here decides
# anything; it only draws.
#
# Type is Atkinson Hyperlegible (fonts.py), anti-aliased: a sans for words, a mono for addresses
# and hashes. Colours are named tokens in THEMES; use("dark") or use("light") picks a set. Text
# edges are mixed with what the text sits on, so every call names its background.
#
# The A/B/X/Y column runs down the right edge, A at the top and Y at the bottom. On a review page
# the SIGN bar runs across the top and ends in an A badge, REJECT across the bottom with a Y badge,
# and B (back) is labelled in the page row. SIGN stays grey until every page has been seen.
# With the knob (lcd.KNOB) the bottom bar holds three actions instead, SIGN, REJECT and BACK: they
# come after the last page as the knob turns, and a press on any page jumps to them. A red
# page is red all over, and the thing at stake (the address that gains power, the amount) is in
# the "stake" colour, as on the chip map's red PERMANENT screen.
#
# Who is being called: a contract pinned in quorum_cfg.py shows its logo and "known"; any other
# contract gets a warning triangle and "unknown contract". The logos are drawn here as coloured
# monograms, not copies of anyone's artwork.
