def txt(d, s, x, y, font, fg="text", bg="bg"):
    return F.text(d, s, x, y, font, rgb(fg), rgb(bg))


def txt_r(d, s, xr, y, font, fg="text", bg="bg"):
    return F.text(d, s, xr - F.width(s, font), y, font, rgb(fg), rgb(bg))


def txt_c(d, s, y, font, fg="text", bg="bg", x0=0, x1=W):
    return F.text(d, s, x0 + (x1 - x0 - F.width(s, font)) // 2, y, font, rgb(fg), rgb(bg))


def fit(s, w, font):
    """s, cut with an ellipsis to fit w pixels."""
    if F.width(s, font) <= w:
        return s
    while s and F.width(s + "…", font) > w:
        s = s[:-1]
    return s + "…"


def para(d, s, x, y, w, font, fg, bg, pitch, bottom):
    """Wrapped text, stopping before bottom. Returns the y after it."""
    for line in F.wrap(s, w, font):
        if y + pitch > bottom:
            break
        txt(d, line, x, y, font, fg, bg)
        y += pitch
    return y


def rrect(d, x, y, w, h, r, col):
    col = c(col)
    d.fill_rect(x + r, y, w - 2 * r, h, col)
    d.fill_rect(x, y + r, r, h - 2 * r, col)
    d.fill_rect(x + w - r, y + r, r, h - 2 * r, col)
    d.ellipse(x + r, y + r, r, r, col, True, 2)
    d.ellipse(x + w - 1 - r, y + r, r, r, col, True, 1)
    d.ellipse(x + r, y + h - 1 - r, r, r, col, True, 4)
    d.ellipse(x + w - 1 - r, y + h - 1 - r, r, r, col, True, 8)


def pill(d, s, x, y, font, fill, ink):
    """Text in a rounded tag, top-left at (x, y). Returns its width."""
    w = F.width(s, font) + 12
    h = F.height(font)
    rrect(d, x, y, w, h, h // 2 - 1, fill)
    txt(d, s, x + 6, y, font, ink, fill)
    return w


def badge(d, key, cx, cy, fill, ink):
    """A button's letter in a circle, next to what it does."""
    d.ellipse(cx, cy, 9, 9, c(fill), True)
    w = F.width(key, "bold14")
    txt(d, key, cx - w // 2 + 1, cy - 10, "bold14", ink, fill)


def thick_line(d, x0, y0, x1, y1, col, t=3):
    col = c(col)
    for i in range(-(t // 2), t - t // 2):
        d.line(x0 + i, y0, x1 + i, y1, col)
        d.line(x0, y0 + i, x1, y1 + i, col)


def mark(d, ok, cx, cy, r):
    """A round check or cross."""
    d.ellipse(cx, cy, r, r, c("ok" if ok else "bad_bar"), True)
    ink = "on_ok" if ok else "on_bad"
    k = r * 45 // 100
    if ok:
        thick_line(d, cx - k, cy, cx - k // 3, cy + k * 2 // 3, ink, r // 6 + 1)
        thick_line(d, cx - k // 3, cy + k * 2 // 3, cx + k, cy - k * 2 // 3, ink, r // 6 + 1)
    else:
        thick_line(d, cx - k, cy - k, cx + k, cy + k, ink, r // 6 + 1)
        thick_line(d, cx - k, cy + k, cx + k, cy - k, ink, r // 6 + 1)


def warn_sign(d, cx, cy, r, fill="warn", ink="on_warn"):
    """A warning triangle with an exclamation mark, r pixels from centre to corner."""
    d.poly(cx, cy, array("h", [0, -r, r, r - 2, -r, r - 2]), c(fill), True)
    d.fill_rect(cx - 1, cy - r // 2 + 1, 2, r // 2 + 1, c(ink))
    d.fill_rect(cx - 1, cy + r // 2 + 1, 2, 2, c(ink))


def logo(d, key, cx, cy, r=8):
    """A known contract's monogram, or the warning triangle for an unknown one."""
    if key == "send":           # a plain transfer: an arrow, no contract
        col = c("muted")
        for k in (0, 1):
            d.hline(cx - 6, cy + k, 11, col)
            d.line(cx, cy - 5 + k, cx + 5, cy + k, col)
            d.line(cx, cy + 5 + k, cx + 5, cy + k, col)
    elif key == "refused":
        mark(d, False, cx, cy, r)
    elif key in LOGO:
        fill, ink, ch = LOGO[key]
        d.ellipse(cx, cy, r, r, c(fill), True)
        font = "bold14" if r >= 8 else "sans12"
        txt(d, ch, cx - F.width(ch, font) // 2 + 1, cy - (10 if r >= 8 else 8), font, ink, fill)
    else:
        warn_sign(d, cx, cy + 1, r)


def ident(q, a):
    """(name, logo, known) for an address: known contracts, this Safe, the address book."""
    return decode.identify(q.ctx, a) if q.ctx else (None, None, False)


def contract_chip(d, q, a, xr, y, fg, bg, room, font="sans12"):
    """Right-aligned in room pixels: [logo] Name for a known contract, the warning triangle and
    "Unknown contract" (or just "Unknown") for any other."""
    name, lg, known = ident(q, a)
    if known and lg:
        s = fit(name, room - 18, font)
        txt_r(d, s, xr, y, font, fg, bg)
        logo(d, lg, xr - F.width(s, font) - 12, y + F.height(font) // 2, 7)
    elif not known:
        s = "Unknown contract" if F.width("Unknown contract", font) + 22 <= room else "Unknown"
        txt_r(d, s, xr, y, font, fg, bg)
        warn_sign(d, xr - F.width(s, font) - 12, y + F.height(font) // 2, 8)


def short(a):
    return a[:6] + "…" + a[-4:] if len(a) > 14 else a


def addr_lines(a):
    """40 hex in 4-character chunks, two lines: 0x7099 7970 c518 12dc 3a01 / 0c7d 01b5 ..."""
    h = a[2:].lower() if a.startswith("0x") else a.lower()
    ch = [h[i:i + 4] for i in range(0, len(h), 4)]
    return ["0x" + " ".join(ch[:5]), "  " + " ".join(ch[5:])]


def hash_lines(h, per=4, size=4):
    """64 hex in chunks, per chunks to a line."""
    h = h[2:] if h.startswith("0x") else h
    ch = [h[i:i + size] for i in range(0, len(h), size)]
    return [" ".join(ch[i:i + per]) for i in range(0, len(ch), per)]


def chain_pill(d, q, x, y, right=False, full=True):
    fill, ink = CHAIN.get(q.CHAIN, ((120, 120, 120), (255, 255, 255)))
    s = q.CFG["chains"].get(str(q.CHAIN), "Chain")
    if full:
        s += " · %d" % q.CHAIN
    if right:
        x -= F.width(s, "sans12") + 12
    return pill(d, s, x, y, "sans12", fill, ink)


def version_pill(d, q, x, y):
    """Safe v1.4.1, red when this console's hash does not fit that version."""
    v, ok = q.safe_version()
    if not v:
        return 0
    return pill(d, "Safe v" + v, x, y, "sans12", "surface" if ok else "bad_bar", "muted" if ok else "on_bad")


def page_colors(level):
    if level == "red":
        return {"bg": "bad_bg", "head": "bad_head", "on_head": "on_bad", "text": "bad_text", "muted": "bad_muted",
                "stake": "stake"}
    if level == "warn":
        return {"bg": "warn_bg", "head": "warn_head", "on_head": "on_bad", "text": "warn_text", "muted": "warn_muted",
                "stake": "warn_text"}
    return {"bg": "bg", "head": "surface", "on_head": "text", "text": "text", "muted": "muted", "stake": "text"}


def footer_hints(d, q, hints, y=222, bg="bg"):
    """Key badges with what they do, or the last message if there is one. With the knob, only the
    first hint: what a press does."""
    if q.msg:
        d.fill_rect(0, y - 12, W, H - y + 12, c(bg))
        txt_c(d, q.msg, y - 9, "bold14", "warn", bg)
        return
    if q.KNOB:
        if hints:
            knob_badge(d, M + 6, y, "raised", "text")
            x = txt(d, "press", M + 19, y - 8, "sans12", "faint", bg)
            txt(d, hints[0][1], x + 6, y - 9, "bold14", "text", bg)
        return
    x = M + 6
    for key, what in hints:
        badge(d, key, x, y, "raised", "text")
        x = txt(d, what, x + 13, y - 8, "sans12", "muted", bg) + 16


def knob_badge(d, cx, cy, fill, ink):
    """The knob, seen from above: a disc with a pointer notch."""
    d.ellipse(cx, cy, 9, 9, c(fill), True)
    d.ellipse(cx, cy, 5, 5, c(ink), False)
    d.fill_rect(cx - 1, cy - 8, 2, 5, c(ink))


def knob_choices(d, q, items, focus, hint, y=222, bg="bg"):
    """A row of choices the knob turns onto, right-aligned, the one in focus lit; a hint on the left.
    items: (key, label); focus: the key in focus, or None."""
    if q.msg:
        d.fill_rect(0, y - 12, W, H - y + 12, c(bg))
        txt_c(d, q.msg, y - 9, "bold14", "warn", bg)
        return
    knob_badge(d, M + 6, y, "raised", "text")
    x = R
    for key, label in reversed(items):
        on = key == focus
        font = "bold14" if on else "sans12"
        x -= F.width(label, font) + 12       # pill()'s width
        pill(d, label, x, y - 9, font, "stake" if on else "surface", "bg" if on else "muted")
        x -= 6
    if F.width(hint, "sans12") <= x - M - 21:
        txt(d, hint, M + 19, y - 8, "sans12", "faint", bg)


def who_line(d, q, label, a, y, pc, bg):
    """label + who the address is (logo and name, a name from the book, or a flag), then the
    address itself in full. Returns the y after it."""
    name, lg, known = ident(q, a)
    x = txt(d, label + " ", M, y + 1, "sans12", pc["muted"], bg)
    if lg:
        logo(d, lg, x + 7, y + 9, 7)
        x = txt(d, name, x + 18, y, "bold14", pc["text"], bg)
        txt(d, " known", x, y + 1, "sans12", "ok" if bg == "bg" else pc["muted"], bg)
    elif name:
        txt(d, name, x, y, "bold14", pc["text"], bg)
    elif label == "contract":
        warn_sign(d, x + 8, y + 9, 8)
        txt(d, "unknown contract", x + 20, y, "bold14", "warn" if bg == "bg" else pc["text"], bg)
    else:
        txt(d, "not in the address book", x, y + 1, "sans12", "warn" if bg == "bg" else pc["text"], bg)
    blockies.draw(d, a.lower(), R - 16, y, 2)           # 16 px: an address seen before looks the same
    y += 18
    for line in addr_lines(a):
        txt(d, line, M, y, "mono13", pc["stake"], bg)
        y += 15
    return y + 5


# ----------------------------------------------------------------------------- home
def refused_short(why):
    """The reason a transaction is refused, in a few words for its row on home."""
    for key, short in (("another Safe", "other Safe"), ("delegatecall", "delegatecall"), ("not a transaction", "malformed"),
                       ("Operation", "bad operation"), ("safeTxHash", "no hash"), ("hash", "bad hash"), ("decoded", "unreadable")):
        if key in why:
            return short
    return "see why"


def sync_status(d, q):
    """Top right: Synced/Offline, or with several Safes how many answered, and its dot."""
    ok = q.net_ok
    if len(q.WATCH) > 1:
        down = sum(1 for w in q.WATCH if w["tried"] and not w["ok"])
        s = ("%d offline" % down) if down else "%d synced" % len(q.WATCH)
    else:
        s = "Synced" if ok else "Offline"
    if q.checking:
        s = "checking\u2026"
    txt_r(d, s, R, 4, "sans12", "muted")
    d.ellipse(R - F.width(s, "sans12") - 8, 12, 3, 3, c("muted" if q.checking else "ok" if ok else "bad"), True)
    return s


FOOT_Y = 210        # knob_choices' row at its usual y=222, a message in its place included


def focus_rows(q):
    """What a knob turn changes on this screen when it only moves the focus: (layout, [(y0, y1),
    ...]). quorum.turned redraws only the bands of those rows when the layout is the same before and
    after the turn. None: anything could change, so the whole screen is drawn."""
    s = q.state
    if q.msg or q.outside or q.checking:
        return None
    if s == "home" and q.status_home():    # draw_status: Safe rows of 28 from y=110, then the footer
        ws = q.WATCH
        sel = max(0, min(q.hsel, len(ws) - 1))
        top = max(0, min(sel - (HOME_ROWS - 1), len(ws) - HOME_ROWS))
        y = 110 + (sel - top) * 28
        spans = [(y, y + 25), (FOOT_Y, H)]
        if len(ws) > HOME_ROWS:
            spans.append((92, 108))         # "2 of 5" above the rows
        return ("status", top, len(ws), tuple(q.home_feet())), spans
    if s == "home":                 # draw_home's list: 4 rows of 28 from y=92, the Safe in view on top
        top = max(0, min(q.sel - 3, len(q.queue) - 4))
        y = 92 + (q.sel - top) * 28
        return ("list", top, len(q.queue), q.SAFE_ADDR), [(y, y + 25), (FOOT_Y, H)]
    if s == "device":
        return ("device",), [(FOOT_Y, H)]
    if s == "result" and q.unsent:
        return ("result",), [(FOOT_Y, H)]
    if s == "review" and q.act is not None:   # moving between SIGN, REJECT and BACK
        return ("review", q.page, q.cur["h"]), [(BOTTOM, H)]
    return None


def chain_short(q, chain):
    return {84532: "Base Sep"}.get(chain) or q.CFG["chains"].get(str(chain), "chain %d" % chain)


def clock_set():
    """Is the wall clock set (NTP, or the host in the emulator)? The clock card needs it."""
    return time.time() > 1700000000


def ago(t):
    """When, briefly: "just now", "5m ago", "3h ago", "2d ago" ("" before the clock is set)."""
    if not t or t < 1700000000:
        return ""
    s = time.time() - t
    if s < 60:
        return "just now"
    if s < 3600:
        return "%dm ago" % (s // 60)
    if s < 86400:
        return "%dh ago" % (s // 3600)
    return "%dd ago" % (s // 86400)


def key_name(q):
    if q.sig and q.sig.name == "passkey":
        return "Your passkey"
    return q.chip["name"] if q.chip else "This key"


def key_kind(q):
    n = q.sig.name if q.sig else ""
    if n == "trustm":
        return "Trust M \u00b7 " + ("sealed" if q.row and q.row.get("locked") else "open")
    if n == "passkey":
        return "Passkey \u00b7 browser"
    if n == "atecc608":
        return "ATECC608" + (" \u00b7 %d uses" % q.counter if q.counter is not None else "")
    if n == "pico-soft":
        return "Software key (testing)"
    return "No key"


def status_card(d, q, y, h):
    """The status home's top card: is this key ready, and if not, the one thing to do next."""
    st = q.readiness()
    fill = {"not_owner": "warn_bg", "nokey": "bad_bg"}.get(st, "surface")
    rrect(d, 6, y, W - 12, h, 6, fill)
    tx, cy = 52, y + h // 2
    total = len(q.queue)
    if st == "ready":
        mark(d, True, 28, cy, 14)
        txt(d, "Ready to approve", tx, y + 7, "bold18", "text", fill)
        sub = ("%d waiting for others \u00b7 Y shows" % total) if total else "Nothing waits for you"
        txt(d, fit(sub, W - 12 - tx, "sans12"), tx, y + 32, "sans12", "muted", fill)
    elif st == "not_owner":
        warn_sign(d, 28, cy, 13)
        txt(d, "Not an owner yet", tx, y + 4, "bold18", "warn_text", fill)
        txt(d, "Add " + short(q.me), tx, y + 26, "mono13", "warn_text", fill)
        how = "in the app: Your passkey" if q.sig and q.sig.name == "passkey" else "deploy its signer, add owner"
        txt(d, fit(how, W - 12 - tx, "sans12"), tx, y + 42, "sans12", "warn_muted", fill)
    elif st == "offline":
        mark(d, False, 28, cy, 14)
        txt(d, "Offline", tx, y + 7, "bold18", "text", fill)
        txt(d, fit(q.net_err or "no answer", W - 12 - tx, "sans12"), tx, y + 32, "sans12", "muted", fill)
    elif st == "starting":
        d.ellipse(28, cy, 13, 13, c("raised"), True)
        txt(d, "Connecting\u2026", tx, y + 7, "bold18", "text", fill)
        txt(d, "asking Safe's service", tx, y + 32, "sans12", "muted", fill)
    else:
        mark(d, False, 28, cy, 14)
        txt(d, "No key", tx, y + 7, "bold18", "bad_text", fill)
        txt(d, "the console can't sign", tx, y + 32, "sans12", "bad_muted", fill)


def safe_row(d, q, w, y, on):
    """One watched Safe: its blockie, name, and what it means for this key."""
    fill = "raised" if on else "surface"
    rrect(d, 6, y, W - 12, 25, 5, fill)
    blockies.draw(d, w["addr"], 12, y + 4, 2)
    n_own, need = len(q.owners(w)), q.threshold(w)
    total, mine = q.queued_for(w)
    if w["tried"] and not w["ok"]:
        st, sc = "offline", "bad"
    elif not n_own:
        st, sc = "\u2026", "faint"
    elif q.me not in q.owners(w):
        st, sc = "not owner", "warn"
    elif total:
        st, sc = "%d queued" % total, "muted"
    else:
        st, sc = "%d of %d" % (need, n_own), "muted"
    sw = F.width(st, "sans12")
    txt_r(d, st, R - 6, y + 4, "sans12", sc, fill)
    if n_own and q.me in q.owners(w) and not (w["tried"] and not w["ok"]):
        d.ellipse(R - 6 - sw - 7, y + 12, 3, 3, c("ok"), True)       # this key is an owner
    f = "bold14" if on else "sans14"
    room = R - 6 - sw - 14 - 34
    nm = fit(w["name"], room, f)
    x = txt(d, nm, 34, y + 3, f, "text", fill)
    ch = chain_short(q, w["chain"])
    if x + 6 + F.width(ch, "sans12") <= R - 6 - sw - 14:
        txt(d, ch, x + 6, y + 5, "sans12", "faint", fill)
    d.fill_rect(R, y + 5, 3, 15, c(CHAIN.get(w["chain"], ((120, 120, 120), 0))[0]))


def draw_status(q):
    """Home when nothing waits for this key: this key, whether it is ready, the Safes it watches.
    A transaction that wants it replaces this with the queue list; a quiet minute, the screensaver."""
    d = q.d
    d.fill(c("bg"))
    if q.me:
        blockies.draw(d, q.me, M, 5, 2)
    s = sync_status(d, q)
    txt(d, fit(key_name(q), R - F.width(s, "sans12") - 20 - (M + 22), "bold14"), M + 22, 4, "bold14")
    status_card(d, q, 28, 58)
    y = 92
    txt(d, "SAFES", M, y, "sans12", "muted")
    ws = q.WATCH
    q.hsel = sel = max(0, min(q.hsel, len(ws) - 1))
    top = max(0, min(sel - (HOME_ROWS - 1), len(ws) - HOME_ROWS))
    if len(ws) > HOME_ROWS:
        txt_r(d, "%d of %d" % (sel + 1, len(ws)), R, y, "sans12", "faint")
    y = 110
    for i in range(top, min(len(ws), top + HOME_ROWS)):
        safe_row(d, q, ws[i], y, i == sel and q.hfoot is None)
        y += 28
    if q.outside:
        rrect(d, 6, 196, W - 12, 22, 5, "warn_bg")
        warn_sign(d, 18, 207, 8)
        txt(d, fit("key used %d\u00d7 outside this console" % q.outside, W - 40, "sans12"), 30, 201, "sans12", "warn_text", "warn_bg")
    elif q.recent:                  # the last approval from this console, under the Safes
        r = q.recent[0]
        when = ago(r["t"])
        x = txt(d, "Last", M, 195, "sans12", "muted")
        txt(d, fit("#%d %s \u00b7 %s%s" % (r["n"], r["what"], r["name"], (" \u00b7 " + when) if when else ""), R - x - 6, "sans12"),
            x + 6, 195, "sans12", "faint")
    if q.KNOB:
        feet = q.home_feet()
        knob_choices(d, q, [(k, {"queue": "Queue", "recent": "Recent", "device": "Device"}[k]) for k in feet], q.hfoot, "turn \u00b7 press")
    else:           # Y opens the queue when others' transactions wait: the card above says so
        footer_hints(d, q, (("A", "Open"), ("B", "Recent"), ("X", "Device")))
    d.show()


# ----------------------------------------------------------------------------- the screensaver
DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")


def draw_saver(q):
    """A card at a time, dimmed: drawn from what the console already knows. Each card sits a few
    pixels off the last one's place, so nothing stays lit in one spot."""
    d = q.d
    d.fill(c("bg"))
    cards = q.saver_cards()
    i = q.saver_card % len(cards)
    kind, w = cards[i]
    k = q.saver_card + i
    dx, dy = (k * 37) % 21 - 10, (k * 53) % 17 - 8
    x0, x1, y0 = dx, W + dx, 44 + dy
    cx = W // 2 + dx
    st = q.readiness()
    if kind == "clock":
        t = time.localtime(int(time.time() + q.UTC_OFFSET * 3600))
        txt_c(d, "%02d:%02d" % (t[3], t[4]), y0 + 18, "monob28", "text", "bg", x0, x1)
        txt_c(d, "%s %d %s%s" % (DAYS[t[6]], t[2], MONTHS[t[1] - 1], "" if q.UTC_OFFSET else " \u00b7 UTC"), y0 + 58, "sans14", "muted", "bg", x0, x1)
        line, col = {"ready": ("Nothing to sign", "ok"), "not_owner": ("Not an owner yet", "warn")}.get(st, ("Offline", "bad") if st == "offline" else ("", "faint"))
        if line:
            lw = F.width(line, "sans12")
            d.ellipse(cx - lw // 2 - 8, y0 + 106, 3, 3, c(col), True)
            txt(d, line, cx - lw // 2, y0 + 98, "sans12", "faint")
    elif kind == "safe":
        blockies.draw(d, w["addr"], cx - 24, y0, 6)
        txt_c(d, fit(w["name"], W - 20, "bold18"), y0 + 56, "bold18", "text", "bg", x0, x1)
        n_own, need = len(q.owners(w)), q.threshold(w)
        txt_c(d, "%s \u00b7 %d of %d" % (chain_short(q, w["chain"]), need, n_own), y0 + 80, "sans14", "muted", "bg", x0, x1)
        total, _ = q.queued_for(w)
        nxt = w["info"].get("nonce")
        line = ("next #%s \u00b7 " % nxt if nxt is not None else "") + ("%d queued" % total if total else "nothing queued")
        txt_c(d, line, y0 + 102, "sans12", "faint", "bg", x0, x1)
        mine = q.me in q.owners(w)
        txt_c(d, "you're an owner" if mine else "not an owner", y0 + 120, "sans12", "ok" if mine else "warn", "bg", x0, x1)
    elif kind == "key":
        if q.me:
            blockies.draw(d, q.me, cx - 24, y0, 6)
        txt_c(d, fit(key_name(q), W - 20, "bold18"), y0 + 56, "bold18", "text", "bg", x0, x1)
        txt_c(d, key_kind(q), y0 + 80, "sans14", "muted", "bg", x0, x1)
        if q.me:
            txt_c(d, short(q.me), y0 + 102, "mono13", "faint", "bg", x0, x1)
        n = sum(1 for x in q.WATCH if q.me in q.owners(x))
        txt_c(d, "owner of %d Safe%s" % (n, "" if n == 1 else "s") if n else "not an owner yet", y0 + 120, "sans12",
              "ok" if n else "warn", "bg", x0, x1)
    elif kind == "recent":
        r = q.recent[0]
        txt_c(d, "LAST APPROVAL", y0, "sans12", "muted", "bg", x0, x1)
        blockies.draw(d, r["safe"], cx - 16, y0 + 20, 4)
        y = y0 + 60
        for line in F.wrap("#%d %s" % (r["n"], r["what"]), W - 30, "bold18")[:2]:
            txt_c(d, line, y, "bold18", "text", "bg", x0, x1)
            y += 22
        when = ago(r["t"])
        txt_c(d, fit("%s \u00b7 %s%s" % (r["name"], chain_short(q, r["chain"]), (" \u00b7 " + when) if when else ""), W - 20, "sans12"),
              y + 4, "sans12", "faint", "bg", x0, x1)
    else:
        import image
        blockies.draw(d, image.SEED, cx - 24, y0, 6)
        txt_c(d, "Release " + image.SHORT, y0 + 56, "bold18", "text", "bg", x0, x1)
        txt_c(d, "%s \u00b7 %s" % (image.VERSION or image.IMAGE, image.BUILD), y0 + 80, "sans14", "muted", "bg", x0, x1)
        txt_c(d, "the same picture on every console", y0 + 102, "sans12", "faint", "bg", x0, x1)
        txt_c(d, "and page running this firmware", y0 + 118, "sans12", "faint", "bg", x0, x1)
    n = len(cards)                  # which card, as dots
    for j in range(n):
        d.ellipse(W // 2 - (n - 1) * 6 + j * 12, 226, 2, 2, c("muted" if j == i else "line"), True)
    d.show()


def draw_recent(q):
    """The signatures this console sent, newest first: which Safe, which #, what, when."""
    d = q.d
    d.fill(c("bg"))
    txt(d, "Recent", M, 4, "bold18")
    pages = q.recent_pages()
    q.rpage = page = min(q.rpage, pages - 1)
    if pages > 1:
        txt_r(d, "%d of %d" % (page + 1, pages), R, 9, "sans12", "muted")
    if not q.recent:
        txt_c(d, "Nothing signed yet", 100, "bold18")
        txt_c(d, "Approvals sent from this", 130, "sans14", "muted")
        txt_c(d, "console show up here", 148, "sans14", "muted")
    y = 34
    for r in q.recent[page * RECENT_PER_PAGE:(page + 1) * RECENT_PER_PAGE]:
        blockies.draw(d, r["safe"], M, y + 3, 2)
