HOLD_PERM = 3000        # A held this long on the red screen
HOLD_REV = 1500         # and this long on the yellow one
ROW_Y, ROW_H = 25, 12   # 16 slot rows between the header and the footer
KIND_COLOR = {"P256": L.WHITE, "PUB": L.GREY, "AES": L.GREY, "DATA": C.DIM, "?": C.DIM}
KIND_LABEL = {"?": "-"}
DESC = {"P256": "P-256 private key", "PUB": "P-256 public key", "AES": "AES-128 key", "DATA": "plain data",
        "?": "untyped by the rules"}
TRANSIENT = ("busy", "confirm", "confirm_write", "result", "refused", "labres")
PARTS = {"00006002": "ATECC608A", "00006003": "ATECC608B", "00005000": "ATECC508A"}


def fp(s):
    return "%08x" % (s["qx"] >> 224)


class SlotsUI:
    HOLD_REV = HOLD_REV

    def __init__(self, d, sig, on_change):
        self.d = d
        self.sig = sig
        self.on_change = on_change      # called after anything that may change the active key or the table
        self.view = "zones"
        self.stack = []                 # (view, act, scroll) trail for Y
        self.ret = "zones"              # where a transient screen returns to
        self.cur = 0                    # cursor on the slot list
        self.act = 0                    # cursor on a menu
        self.act2 = 0                   # cursor on a result's sub-menu
        self.scroll = 0
        self.table = []
        self.st = {}
        self.cfgb = None                # the 128 config bytes as last read
        self.snap = None                # the saved snapshot, if any
        self.action = None              # (kind, slot) while confirming
        self.hold = None                # ticks_ms when A went down on a confirm screen
        self.armhold = None             # ticks_ms when B+Y went down
        self.pend = {}                  # B/Y presses waiting for release (chipmap.arm_tick)
        self.pair = False
        self.msg = ""
        self.ok = True
        self.checks = None              # ((label, ok), ...) on a result screen
        self.sealed = False
        self.lab = None
        self.ref = None
        self.card = None
        self.done = set()
        self.diff = None
        self.difftitle = ""
        self.zone = None
        self.qr = None                  # (slot, form, n, rows): the last public-key QR made
        self.qrform = 0                 # 0 = uncompressed 04||x||y, 1 = compressed 02/03||x
        self.view_from = ""
        self.n = 0
        self.leave = False
        self.dirty = True

    # ----------------------------------------------------------------------------- navigation
    def go(self, view, act=0):
        self.stack.append((self.view, self.act, self.scroll))
        self.view, self.act, self.scroll, self.dirty = view, act, 0, True

    def back(self):
        if self.stack:
            self.view, self.act, self.scroll = self.stack.pop()
        else:
            self.leave = True
        self.dirty = True

    def open(self, view="zones"):
        self.stack = []
        self.view, self.act, self.scroll = view, 0, 0
        self.cur = getattr(self.sig, "slot", 0)
        self.refresh()

    def busy(self, msg):
        self.view, self.msg = "busy", msg
        self.draw()

    def show_result(self, msg, ok):
        if self.view not in TRANSIENT:
            self.ret = self.view
        self.msg, self.ok, self.view, self.dirty = msg[:220], ok, "result", True

    # ----------------------------------------------------------------------------- data
    def refresh(self):
        try:
            self.table = self.sig.slots()
        except Exception as e:
            self.table = []
            self.show_result("slot table: %r" % e, False)
        try:
            self.st = self.sig.status()
        except Exception as e:
            self.st = {"note": str(e)}
        try:
            self.cfgb = self.sig.config()
        except Exception:
            self.cfgb = None
        try:
            self.snap = self.sig.snapshot()
        except Exception:
            self.snap = None
        self.dirty = True

    def row(self, n):
        for s in self.table:
            if s["slot"] == n:
                return s
        return {"slot": n, "kind": "?", "bytes": atecc.SLOT_BYTES[n], "locked": False, "lockable": False, "genKey": False,
                "extSign": False, "pubInfo": False, "privWrite": False, "clearWrite": "?", "encRead": False, "isSecret": False}

    def part(self):
        rev = self.st.get("revision", "")
        return PARTS.get(rev, self.sig.name if not rev else "ATECC?")

    def actions(self, s):
        """What the cursor can do to this slot, with its class and why it is off."""
        out = []
        active = s["slot"] == self.sig.slot
        cfg_locked = self.st.get("configLocked", False)
        data_locked = self.st.get("dataLocked", False)
        if s["kind"] == "P256":
            if s.get("hasKey") and not active:
                out.append(("use", "USE THIS KEY", "safe", ""))
            if s.get("hasKey"):
                out.append(("pubkey", "SHOW PUBLIC KEY", "safe", ""))
                out.append(("signtest", "SIGN TEST", "safe", "" if s["extSign"] else "this slot may not sign"))
            if s["genKey"] and not s["locked"]:
                out.append(("genkey", "NEW KEY", "perm", "config zone still open" if not cfg_locked else self.sig.gate("genkey")))
        if s["kind"] == "DATA":
            if s.get("clearWrite") == "clear" and not s.get("isSecret"):
                out.append(("note", "WRITE A NOTE", "rev", "config zone still open" if not cfg_locked else ""))   # rules say Always: clear writes survive the data lock
            if not s.get("isSecret"):
                out.append(("readnote", "READ THE BYTES", "safe", "config zone still open" if not cfg_locked else ("data zone open: reads after its lock" if not data_locked else "")))
        if s["lockable"] and not s["locked"]:
            out.append(("lockslot", "LOCK SLOT FOREVER", "perm", "config zone still open" if not cfg_locked else self.sig.gate("lock")))
        return out

    # ----------------------------------------------------------------------------- drawing
    def draw(self):
        d = self.d
        d.fill(L.BLACK)
        v = self.view
        if v == "zones":
            C.draw_zones(self)
        elif v == "list":
            self.draw_list()
        elif v == "slot":
            self.draw_slot()
        elif v == "pubkey":
            self.draw_pubkey()
        elif v == "pubqr":
            self.draw_pubqr()
        elif v == "cfg":
            C.draw_cfg(self)
        elif v == "raw":
            C.draw_raw(self)
        elif v == "diff":
            C.draw_diff(self)
        elif v == "otp":
            C.draw_otp(self)
        elif v == "counters":
            C.draw_counters(self)
        elif v == "refused":
            C.draw_refused(self)
        elif v == "rawcmd":
            C.draw_rawcmd(self)
        elif v == "confirm_write":
            C.draw_confirm_write(self)
        elif v == "confirm":
            self.draw_confirm()
        elif v == "lab":
            LN.draw_lab(self)
        elif v == "labres":
            LN.draw_labres(self)
        elif v == "why":
            LN.draw_why(self)
        elif v == "learn":
            LN.draw_learn(self)
        elif v == "card":
            LN.draw_card(self)
        elif v == "snake":
            import snakelab
            snakelab.draw(self)
        elif v == "busy":
            C.header(self, "WORKING")
            d.center_text(self.msg[:28], 100, L.WHITE)
        elif v == "result":
            self.draw_result()
        if self.armhold is not None:
            C.draw_arm_bar(self)
        d.show()
        self.dirty = False

    TILE_W, TILE_H, TILE_X, TILE_Y = 56, 46, 4, 27

    def draw_list(self):
        """The 16 slots as a 4x4 field of tiles, the chip's own layout."""
        d = self.d
        C.header(self)
        cfg = self.st.get("configLocked")
        if not self.table:
            d.center_text("no slot table", 100, L.RED)
        for n in range(16):
            x = self.TILE_X + (n % 4) * (self.TILE_W + 4)
            y = self.TILE_Y + (n // 4) * (self.TILE_H + 3)
            C.draw_tile(d, self, self.row(n), x, y, self.TILE_W, self.TILE_H, sel=n == self.cur)
        C.footer(self, "A open  Y up" if cfg else "cfg OPEN: keys hidden  Y up", L.GREY if cfg else L.RED)

    def draw_slot(self):
        d = self.d
        s = self.row(self.cur)
        C.header(self)
        y = 27
        I.draw(d, "lock" if s["locked"] else C.KIND_ICON.get(s["kind"], "bytes"), 220, y - 1, T.C["perm"] if s["locked"] else C.KIND_COLOR.get(s["kind"], C.DIM))
        d.text(DESC.get(s["kind"], s["kind"]), 4, y, L.WHITE); y += 12
        d.text("%d bytes" % s.get("bytes", atecc.SLOT_BYTES[self.cur]), 4, y, L.GREY); y += 12
        if s["kind"] == "P256":
            if s.get("hasKey"):
                d.text("key " + fp(s), 4, y, L.GREEN if self.cur == self.sig.slot else L.WHITE)
                if self.cur == self.sig.slot:
                    d.text("ACTIVE", 160, y, L.GREEN)
            elif not self.st.get("configLocked"):
                d.text("hidden until the rules lock", 4, y, L.RED)
            else:
                d.text("empty", 4, y, L.YELLOW)
            y += 12
            flags = (("sign external digests", s["extSign"]), ("genkey allowed", s["genKey"]),
                     ("privwrite (import)", s["privWrite"]), ("pubkey readable", s["pubInfo"]),
                     ("limited use (counter)", s.get("limitedUse", False)), ("lockable", s["lockable"]))
        elif s["kind"] == "DATA":
            d.text("write", 12, y, L.WHITE); d.text(s.get("clearWrite", "?"), 120, y, L.GREY); y += 12
            d.text("read", 12, y, L.WHITE)
            d.text("secret" if s.get("isSecret") else ("encrypted" if s.get("encRead") else "clear"), 120, y, L.GREY); y += 12
            flags = (("lockable", s["lockable"]),)
        else:
            flags = (("lockable", s["lockable"]),)
        for name, on in flags:
            d.text(name, 12, y, L.WHITE if on else L.GREY)
            d.text("yes" if on else "no", 200, y, L.GREEN if on else L.GREY)
            y += 12
        d.text("slot locked", 12, y, L.WHITE)
        d.text("YES" if s["locked"] else "no", 200, y, L.RED if s["locked"] else L.GREY)
        y += 16
        acts = self.actions(s)
        if not acts:
            d.text("nothing to do here yet", 12, y, L.GREY)
            C.footer(self, "left/right slots  Y up")
        else:
            C.menu(self, acts, y, self.act)
            C.menu_footer(self, acts, self.act)

    def draw_pubkey(self):
        d = self.d
        s = self.row(self.cur)
        C.header(self)
        y = 30
        for name, v in (("qx", s["qx"]), ("qy", s["qy"])):
            d.text(name, 4, y, L.YELLOW); y += 12
            h = "%064x" % v
            for i in range(0, 64, 32):
                d.text(h[i:i + 32][:29], 4, y, L.WHITE)
                d.text(h[i + 29:i + 32], 4, y + 12, L.WHITE)
                y += 24
            y += 4
        d.center_text("the vault pins this key", 200, L.GREY)
        C.footer(self, "A qr code  Y back")

    def pubkey_text(self, s):
        """The key as text for a QR: SEC1 uncompressed 04||x||y, or compressed 02/03||x. Uppercase
        hex so the QR can use its alphanumeric mode (130 chars fit version 5, 66 fit version 3)."""
        if self.qrform == 0:
            return "04%064X%064X" % (s["qx"], s["qy"])
        return "%02X%064X" % (2 + (s["qy"] & 1), s["qx"])

    def make_qr(self):
        s = self.row(self.cur)
        key = (self.cur, self.qrform, s.get("qx"))
        if self.qr is None or self.qr[0] != key:
            self.busy("making the qr code...")
            n, rows = qrcode.encode(self.pubkey_text(s), "L")
            self.qr = (key, n, rows)
        self.view, self.dirty = "pubqr", True

    def draw_pubqr(self):
        """The key as a QR, as large as the panel allows below the header, two modules of quiet zone.
        Version 5 (37 modules) lands at 5 px a module, version 3 (29) at 6. Y back, left/right form."""
        d = self.d
        C.header(self)
        _, n, rows = self.qr
        avail = 240 - 24
        size = avail // (n + 4)
        box = size * (n + 4)
        x0, y0 = (240 - box) // 2, 24 + (avail - box) // 2
        d.fill_rect(x0, y0, box, box, L.WHITE)
        for r in range(n):
            bits = rows[r]
            for c in range(n):
                if bits >> c & 1:
                    d.fill_rect(x0 + (c + 2) * size, y0 + (r + 2) * size, size, size, L.BLACK)

    def draw_confirm(self):
        """The red screen: what is about to become permanent, and first of all what is LOST."""
        d = self.d
        kind, slot = self.action
        C.header(self, "PERMANENT")
        C.icon(d, "unlock", 4, 26, L.RED, 2)
        d.big_text("PERMANENT", 40, 26, L.RED, 2)
        d.text("! cannot be undone", 40, 44, L.RED)
        y = 62
        s = self.row(slot) if slot is not None else None
        if kind == "genkey":
            d.text("NEW KEY IN SLOT %d" % slot, 4, y, L.WHITE); y += 14
            if s and s.get("hasKey"):
                # the one thing this erases, in the one colour that is not red: the key's fingerprint
                I.draw(d, "key", 4, y, T.C["lost"])
                d.big_text(fp(s), 24, y, T.C["lost"], 2); y += 20
                d.text("erased for good. a vault tied", 4, y, T.C["perm"]); y += 12
                d.text("to it can never spend again", 4, y, T.C["perm"]); y += 14
            else:
                d.text("LOST: nothing, the slot is empty", 4, y, T.C["safe"]); y += 14
            I.draw(d, "dice", 4, y - 3, L.GREY)
            d.text("NEW: from the chip's RNG", 24, y, L.GREY); y += 14
            body = "The chip keeps the new key; you never see or choose it."
        elif kind == "lockslot":
            d.text("LOCK SLOT %d FOREVER" % slot, 4, y, L.WHITE); y += 14
            if s and s.get("hasKey"):
                I.draw(d, "lock", 4, y, T.C["lost"])
                d.big_text(fp(s), 24, y, T.C["lost"], 2); y += 20
            else:
                d.text("(empty slot)", 4, y, L.GREY); y += 14
            d.text("sealed: NEW KEY here, never", 4, y, T.C["perm"]); y += 14
            body = "The key in it can never be replaced or removed."
        elif kind == "lockcfg":
            d.text("SEAL THE RULES", 4, y, L.WHITE); y += 14
            d.text("LOST: any change to the table", 4, y, T.C["perm"]); y += 12
            d.text("LOST: RESTORE SAVED CONFIG", 4, y, T.C["perm"]); y += 14
            body = "The table on the chip is frozen as it is now; keys can then be made and slots written."
        elif kind == "lockdata":
            d.text("LOCK DATA ZONE", 4, y, L.WHITE); y += 14
            d.text("LOST: clear writes, except in", 4, y, T.C["perm"]); y += 12
            d.text("slots ruled Always (12 and 13)", 4, y, T.C["perm"]); y += 14
            body = "Reads of slots and OTP begin. GenKey stays allowed where the rules say. Untested on silicon past this door."
        else:
            d.text(kind, 4, y, L.WHITE); y += 14
            body = ""
        for line in C.wrap(body)[:3]:
            d.text(line, 4, y, L.WHITE); y += 12
        d.center_text("hold A for 3 s", 168, L.YELLOW)
        d.rect(20, 182, 200, 14, L.WHITE)
        if self.hold is not None:
            e = time.ticks_diff(time.ticks_ms(), self.hold)
            d.fill_rect(21, 183, min(198, 198 * e // HOLD_PERM), 12, L.RED)
            d.center_text("%d" % max(1, (HOLD_PERM - e + 999) // 1000), 200, L.RED, 2)
        C.footer(self, "Y cancel")

    def draw_result(self):
        d = self.d
        C.header(self, "SEALED" if self.sealed else ("DONE" if self.ok else "ERROR"))
        y = 30
        if self.sealed:
            C.icon(d, "lock", 4, y - 6, L.GREEN, 2)
            d.big_text("SEALED", 40, y - 2, L.GREEN, 2); y += 28
        for label, ok in self.checks or ():
            C.icon(d, "check" if ok else "cross", 4, y - 4, L.GREEN if ok else L.RED)
            d.text(label[:26], 24, y, L.GREEN if ok else L.RED); y += 14
        if self.checks:
            y += 4
        for line in C.wrap(self.msg)[:9]:
            d.text(line, 4, y, L.WHITE if self.ok else L.YELLOW); y += 12
        C.footer(self, "A ok")

    # ----------------------------------------------------------------------------- input
    def tick(self, pressed, keys):
        """pressed: key names that went down this tick. keys: lcd.Keys, for held(). Returns "home" to leave."""
        self.n += 1
        v = self.view
        if v not in ("confirm", "confirm_write", "busy", "snake"):   # the game takes B and Y on press
            pressed = C.arm_tick(self, pressed, keys)
        if v == "confirm" or v == "confirm_write":
            need = HOLD_PERM if v == "confirm" else HOLD_REV
            if "Y" in pressed or (v == "confirm_write" and "B" in pressed):
                if v == "confirm_write" and "Y" in pressed:
                    self.go("diff")
                else:
                    self.hold, self.view, self.dirty = None, self.ret, True
            elif keys.held("A"):
                if self.hold is None:
                    self.hold = time.ticks_ms()
                if time.ticks_diff(time.ticks_ms(), self.hold) >= need:
                    self.hold = None
                    if v == "confirm":
                        self.run(*self.action)
                    else:
                        self.busy("writing..." if self.action[0] == "note" else "writing the config zone...")
                        C.run_write(self, self.action[0], self.action[1])
                self.dirty = True
            elif self.hold is not None:
                self.hold, self.dirty = None, True
        elif v == "busy":
            pass
        elif v == "result":
            if "A" in pressed or "Y" in pressed:
                self.checks, self.sealed = None, False
                self.view, self.dirty = self.ret, True
        elif v == "refused":
            if "A" in pressed and self.ref and self.ref.get("trace"):
                self.view_from = "refused"
                self.go("rawcmd")
            elif "Y" in pressed or "A" in pressed:
                self.view, self.dirty = self.ret, True
        elif v == "pubkey":
            if "Y" in pressed:
                self.back()
            elif "A" in pressed or "press" in pressed:
                self.make_qr()
        elif v == "pubqr":
            if "Y" in pressed or "A" in pressed:
                self.view, self.dirty = "pubkey", True
            elif "left" in pressed or "right" in pressed:
                self.qrform ^= 1
                self.make_qr()
        elif v in ("raw", "diff", "otp", "counters", "rawcmd", "why"):
            C.scroll_tick(self, pressed)
            if "Y" in pressed or "A" in pressed:
                self.back()
        elif v == "card":
            LN.tick_card(self, pressed)
        elif v == "zones":
            C.tick_zones(self, pressed)
        elif v == "list":
            self.tick_list(pressed)
        elif v == "slot":
            self.tick_slot(pressed)
        elif v == "cfg":
            C.tick_cfg(self, pressed)
        elif v == "lab":
            LN.tick_lab(self, pressed)
        elif v == "labres":
            LN.tick_labres(self, pressed)
        elif v == "learn":
            LN.tick_learn(self, pressed)
        elif v == "snake":
            import snakelab
            snakelab.tick(self, pressed)
        if "B" in pressed and v not in ("confirm", "confirm_write", "busy", "card", "learn", "snake"):
            LN.context(self)
        if S.armed() and self.n % 20 == 0 and self.view != "snake":
            self.dirty = True       # the countdown in the header
        if self.dirty:
            self.draw()
        if self.leave:
            self.leave = False
            return "home"
        return None

    def tick_list(self, pressed):
        for k in pressed:
            if k == "up":
                self.cur = (self.cur - 4) % 16
            elif k == "down":
                self.cur = (self.cur + 4) % 16
            elif k == "left":
                self.cur = (self.cur - 1) % 16
            elif k == "right":
                self.cur = (self.cur + 1) % 16
            elif k == "A" or k == "press":
                self.go("slot")
            elif k == "Y":
                self.back()
            self.dirty = True

    def tick_slot(self, pressed):
        acts = self.actions(self.row(self.cur))
        for k in pressed:
            if k == "up" and acts:
                self.act = (self.act - 1) % len(acts)
            elif k == "down" and acts:
                self.act = (self.act + 1) % len(acts)
            elif k == "left":
                self.cur, self.act = (self.cur - 1) % 16, 0
            elif k == "right":
                self.cur, self.act = (self.cur + 1) % 16, 0
            elif k == "Y":
                self.back()
            elif (k == "A" or k == "press") and acts:
                kind, label, cls, off = acts[self.act]
                if off:
                    self.show_result("off: " + off + ". Nothing was changed.", False)
                else:
                    self.choose(kind, self.cur)
            self.dirty = True

    def choose(self, kind, slot):
        """A live action from a slot or the config page: safe ones run, permanent ones go red."""
        self.ret = self.view
        if kind in ("use", "signtest", "readnote"):
            self.run(kind, slot)
        elif kind == "pubkey":
            self.go("pubkey")
        elif kind == "note":
            C.start_write(self, "note", slot)
        elif kind in ("genkey", "lockslot", "lockcfg", "lockdata"):
            self.action, self.hold, self.view = (kind, slot), None, "confirm"

    def run(self, kind, slot):
        self.busy({"genkey": "making a key in slot %s" % slot, "use": "switching to slot %s" % slot,
                   "signtest": "signing 32 bytes in slot %s" % slot}.get(kind, kind + "..."))
        sealed = False
        self.checks = None
        try:
            if kind == "use":
                self.sig.use(slot)
                out = "slot %d is now the signing key. the app shows paired only if the vault was deployed with it." % slot
            elif kind == "genkey":
                x, _ = self.sig.genkey(slot)
                CE.key_created(self, slot, "%08x" % (x >> 224))
                out = "new key in slot %d: %08x. record qx/qy from SHOW PUBLIC KEY before deploying a vault." % (slot, x >> 224)
            elif kind == "signtest":
                ok_sig, r, sg = self.sig.sign_test(slot)
                cnt = ""
                chip = getattr(self.sig, "chip", None)
                if chip and self.row(slot).get("limitedUse"):
                    try:
                        cnt = " Counter 0 is now %d: this slot spends one count per signature." % chip.counter(0)
                    except Exception:
                        pass
                self.checks = (("SIGNATURE VERIFIED" if ok_sig else "SIGNATURE DID NOT VERIFY", ok_sig),)
                out = "Slot %d signed SHA-256 of 'picowallet' and the Pico verified it with the slot's public key. r %08x.. s %08x..%s" % (slot, r >> 224, sg >> 224, cnt)
                if not ok_sig:
                    raise Exception(out)
            elif kind == "readnote":
                note = self.sig.read_note(slot)
                out = 'Slot %d says: "%s"' % (slot, note) if note else "Slot %d holds no text yet (all zero bytes)." % slot
            elif kind == "lockslot":
                out = str(self.sig.lock_slot(slot)) + ". The key in it can never be replaced."
                CE.sealed(self, "KEY SEALED", "slot %d can never change" % slot)
                sealed = True
            elif kind == "lockcfg":
                out = str(self.sig.lock_config()) + ". These rules can never be changed again. The data zone is open: NEW KEY in slot 0 is next."
                self.refresh()
                CE.rules_sealed(self)
                sealed = True
            elif kind == "lockdata":
                out = str(self.sig.lock_data()) + ". Reads of slots and OTP begin; clear writes stay only where a slot's rules say Always (12, 13)."
                CE.sealed(self, "DATA SEALED", "reads open; writes by the rules")
                sealed = True
            else:
                out = "unknown action " + kind
            ok = True
        except Exception as e:
            out, ok, sealed = "%s failed: %s" % (kind, e), False, False
        self.refresh()
        self.act = 0
        self.sealed = sealed
        self.show_result(out, ok)
        if kind in ("use", "genkey", "lockcfg"):
            self.on_change()

# One palette for the wallet's chip screens: a deep background, an identity colour per zone of
# the chip (used for header tints, icons, tiles and captions), and the three action classes.
# Colours are kept as RGB triples so shades and gradients can be computed; lcd.color turns them
# into the panel's byte-swapped RGB565.
import lcd as L

RGB = {
    "bg": (6, 10, 26), "navy": (14, 26, 70), "panel": (20, 30, 58), "ink": (34, 42, 70),
    "chip": (200, 210, 230),
    "config": (70, 140, 255), "data": (40, 210, 160), "otp": (255, 150, 40), "counters": (180, 110, 255),
    "lab": (255, 90, 160), "learn": (255, 200, 60),
    "safe": (0, 220, 90), "rev": (255, 200, 0), "perm": (255, 40, 40),
    "lost": (90, 230, 255),     # the one thing a permanent action erases or seals: the only non-red on the red screen
    "white": (255, 255, 255), "grey": (120, 120, 120), "dim": (90, 90, 100),
}
C = {name: L.color(*rgb) for name, rgb in RGB.items()}
# which identity a screen belongs to (chipmap.header tints the bar with it)
ZONE = {"zones": "chip", "cfg": "config", "raw": "config", "diff": "config", "confirm_write": "config",
        "list": "data", "slot": "data", "pubkey": "data", "pubqr": "data", "otp": "otp", "counters": "counters",
        "lab": "lab", "labres": "lab", "why": "lab", "rawcmd": "lab", "snake": "lab", "learn": "learn", "card": "learn",
        "refused": "perm", "confirm": "perm", "result": "safe", "busy": "chip"}
RAINBOW = ("config", "data", "learn", "otp", "perm", "lab", "counters")   # the boot screen's leg chase


def shade(name, f):
    """The zone colour scaled by f (0 dark .. 1 full)."""
    r, g, b = RGB[name]
    return L.color(int(r * f), int(g * f), int(b * f))


def mix(a, b, t):
    """Between two RGB triples, t in 0..1."""
    return tuple(int(a[i] + (b[i] - a[i]) * t) for i in range(3))


def gradient(d, y0, y1, a, b, band=8):
    """Horizontal bands from triple a at y0 to b at y1."""
    n = max(1, (y1 - y0) // band)
    for i in range(n):
        d.fill_rect(0, y0 + i * band, L.W, band, L.color(*mix(a, b, i / max(1, n - 1))))


def zone_of(view):
    return ZONE.get(view, "chip")

# OPTIGA Trust M profiles, and what the console and the Trust M ceremony (provision_tm.py) need to
# know about them: the chip's metadata decoded, its factory certificate checked, the record that
# goes into a data object, the key-binding statement, and the lines the screens show. Pure: no
# bus, so the tests and the host tools use it too. The chipcfg.py of the Trust M.
#
# "quorum-tm1" is PicoQuorum's Trust M profile (docs/TRUSTM.md):
#   E0F1   P-256 private key, made on the chip by GenKeyPair (key usage Sign), Execute ALW (no use
#          limit, no PIN: the Safe's threshold and rotation cover theft, as on quorum v1).
#   F1D0   the record: serial, key OID, the public key (a Trust M never hands a private-key OID's
#          public key back), owner address, date, build.
#   F1D1   the binding: the factory key E0F0, whose Infineon certificate is in E0E0, signs
#          "this UID holds this E0F1 key". Anyone with the certificate can check it.
#   seal   LcsO of E0F1, F1D0 and F1D1 raised to operational. Their factory Change condition is
#          "LcsO < operational", so from then on nothing can regenerate the key or rewrite either
#          object, and a lifecycle state never goes down.
#   spares every object the profile does not use (SPARES) frozen the same way, at T9, so nothing
#          else on the chip can be written or get a key; and Infineon's own E0F0, E0E0 and E140
#          (FACTORY_OBJS) frozen with the rules they came with, so those can't be changed either.
#
# Read off a real Adafruit 4351 on 2026-09-28 (chips/trustm-*-probe.txt): LcsA operational,
# E0F1-E0F3 empty with Change "LcsO < op", F1D0-F1DB 140 bytes each with the same Change, E0F0 the
# factory key (Change NEV, Execute ALW, key usage Auth), its certificate from "Infineon OPTIGA(TM)
# Trust M CA 101".
import hashlib
from binascii import hexlify

KEY = 0xE0F1            # the Safe key
FACTORY_KEY = 0xE0F0    # Infineon's, certified in E0E0
CERT = 0xE0E0
RECORD = 0xF1D0
BINDING = 0xF1D1
UID = 0xE0C2
LCSA = 0xE0C0
SEC = 0xE0C5            # the security event counter: rises on suspect events, the chip slows down
SEALED = (KEY, RECORD, BINDING)

_LCS_SHORT = {0x01: "cre", 0x03: "init", 0x07: "op", 0x0F: "term"}
LCS = {0x01: "creation", 0x03: "initialization", 0x07: "operational", 0x0F: "termination"}
OPERATIONAL = 0x07
ALGO = {0x03: "P256", 0x04: "P384", 0x01: "RSA1024", 0x02: "RSA2048"}
USAGE_AUTH, USAGE_ENC, USAGE_SIGN, USAGE_KEYAGREE = 0x01, 0x02, 0x10, 0x20

# Access-condition bytes (Solution Reference Manual, "Access Conditions")
_AC = {0x00: "ALW", 0xFF: "NEV", 0x20: "Conf", 0x21: "Int", 0x23: "Auto", 0x40: "Luc", 0x70: "LcsG",
       0xE0: "LcsA", 0xE1: "LcsO", 0xFA: "==", 0xFB: ">", 0xFC: "<", 0xFD: "&&", 0xFE: "||"}

# The Infineon CA keys a factory certificate may chain to, by the issuer's common name. From
# TrustMAttest's test (a real chip's certificate, 2026-09-17), and matched by this board's chip.
CAS = {
    "Infineon OPTIGA(TM) Trust M CA 101": (
        0x97337734AD7423A14BF40FD4EE1D27AF8ED05AE87970C74DFE29889B499AD2D0,
        0x1EA249AE7910F052C59D85514A8215E2D63E4730CDFB5CC153BBCC00A7E6408B),
}
# The emulator's virtual Trust M (emu/core/shims/trustm_sim.py) signs its certificate with a test
# CA. Accepted only off the Pico: on rp2 this name means nothing.
EMU_CA = "PicoQuorum emulator CA (not Infineon)"


def _emu_ca():
    import sys
    if sys.platform == "rp2":
        return None
    try:
        import trustm_sim
        return trustm_sim._ca_pub()
    except ImportError:
        return None


# ----------------------------------------------------------------------------- the UID
def uid_fields(uid):
    """The 27-byte coprocessor UID (datasheet: CIM, platform, model, ROM mask, chip type, batch,
    wafer X, wafer Y, firmware id, ESW build)."""
    u = bytes(uid)
    if len(u) != 27:
        raise ValueError("a Trust M UID is 27 bytes, not %d" % len(u))
    return {"cim": u[0], "platform": u[1], "model": u[2], "rom": u[3:5], "type": u[5:11], "batch": u[11:17],
            "x": int.from_bytes(u[17:19], "big"), "y": int.from_bytes(u[19:21], "big"),
            "fw": hexlify(u[21:25]).decode(), "build": hexlify(u[25:27]).decode()}


def serial(uid):
    """This chip among all others: batch number and wafer X/Y (UID bytes 11-20), 20 hex chars. The
    UID's tail is the firmware id and build, the same for the whole batch, so screens showing the
    last 8 characters show the wafer position."""
    return hexlify(bytes(uid)[11:21]).decode()


# ----------------------------------------------------------------------------- metadata
def parse_meta(b):
    """A metadata TLV (0x20 len, then tag len value) as a dict. Access conditions stay bytes;
    ac_text() says them."""
    b = bytes(b)
    if not b or b[0] != 0x20:
        raise ValueError("not metadata: %s" % hexlify(b).decode())
    out = {"lcso": None, "change": None, "read": None, "exec": None, "algo": None, "usage": None,
           "max": None, "used": None, "type": None}
    names = {0xC0: "lcso", 0xD0: "change", 0xD1: "read", 0xD3: "exec", 0xE0: "algo", 0xE1: "usage", 0xC4: "max",
             0xC5: "used", 0xE8: "type"}
    i, end = 2, 2 + b[1]
    while i < end:
        tag, n = b[i], b[i + 1]
        v = b[i + 2:i + 2 + n]
        k = names.get(tag)
        if k in ("lcso", "algo", "usage", "type"):
            out[k] = v[0] if n == 1 else v
        elif k in ("max", "used"):
            out[k] = int.from_bytes(v, "big")
        elif k:
            out[k] = v
        i += 2 + n
    return out


def meta_tlv(lcso=None):
    """The metadata a SetDataObject(metadata) writes: only what changes. Here, only LcsO."""
    body = b""
    if lcso is not None:
        body += bytes([0xC0, 1, lcso])
    return bytes([0x20, len(body)]) + body


def ac_text(ac):
    """An access condition in words: "ALW", "NEV", "LcsO<op", "Luc(E120)"."""
    if ac is None:
        return "-"
    ac = bytes(ac)
    out = []
    i = 0
    while i < len(ac):
        x = ac[i]
        if x in (0xE0, 0xE1, 0x70) and i + 2 < len(ac) and ac[i + 1] in (0xFA, 0xFB, 0xFC):
            out.append(_AC[x] + _AC[ac[i + 1]] + _LCS_SHORT.get(ac[i + 2], "%02x" % ac[i + 2]))
            i += 3
        elif x in (0x20, 0x21, 0x23, 0x40) and i + 2 < len(ac):
            out.append("%s(%02X%02X)" % (_AC[x], ac[i + 1], ac[i + 2]))
            i += 3
        else:
            out.append(_AC.get(x, "%02x" % x))
            i += 1
    return " ".join(out)


def lcs_name(v):
    return LCS.get(v, "?") if v is not None else "-"


def key_row(meta):
    """The Safe key's metadata in the shape atecc.decode_slot gives the console, so
    policy.expect_check reads a Trust M key the same way. locked: LcsO operational while Change
    needs LcsO below it (or never), so the key can never be made again."""
    ch = bytes(meta.get("change") or b"")
    frozen = meta.get("lcso") == OPERATIONAL and ch in (b"\xff", b"\xe1\xfc\x07")
    usage = meta.get("usage") or 0
    return {"slot": KEY, "kind": ALGO.get(meta.get("algo"), "?" if meta.get("algo") else "EMPTY"),
            "extSign": bool(usage & USAGE_SIGN) if isinstance(usage, int) else False, "locked": frozen,
            "limitedUse": False, "hasKey": meta.get("algo") is not None, "lcso": meta.get("lcso"),
            "change": ac_text(meta.get("change")), "exec": ac_text(meta.get("exec"))}


def identify(key_meta, record):
    """factory: E0F1 never made and no record. quorum-tm1: E0F1 sealed and our record in F1D0.
    quorum-tm1-open: on the way (a key or a record, nothing sealed). unknown: sealed by someone else."""
    sealed = key_meta.get("lcso") == OPERATIONAL
    if sealed:
        return "quorum-tm1" if record else "unknown"
    if key_meta.get("algo") is None and not record:
        return "factory"
    return "quorum-tm1-open"


# ----------------------------------------------------------------------------- the spares
# Every object quorum-tm1 does not use, as the real chip listed them (2026-09-28 probe): the other
# key objects, the data objects, the trust anchors, a device-certificate slot and the monotonic
# counters, all with the factory Change "LcsO < op". T9 raises each one's LcsO to operational and
# changes nothing else: from then on nothing can write them or make a key in them, as T7 froze the
# key. Never termination.
#
# FACTORY_OBJS: Infineon's factory key, its certificate and the shielded-connection binding secret
# come at LcsO creation too. TM2 (2026-10-01) showed that while an object's LcsO is below
# operational its metadata can be rewritten whatever its Change condition says: E0F0's Change went
# from NEV to ALW, and then GenKeyPair replaced the factory key. So T9 raises their LcsO as well,
# leaving their rules as they came (E0F0/E0E0 Change NEV; E140 "LcsO < op || Conf(E140)", which
# also makes E140 unreadable). A factory object whose rules already differ is "odd": tampered.
SPARE_KEYS = (0xE0F2, 0xE0F3, 0xE0FC, 0xE0FD)
SPARE_CERTS = (0xE0E1, 0xE0E8, 0xE0EF)
SPARE_COUNTERS = (0xE120, 0xE121, 0xE122, 0xE123)
SPARE_DATA = tuple(range(0xF1D2, 0xF1DC)) + (0xF1E0, 0xF1E1)
SPARES = SPARE_KEYS + SPARE_CERTS + SPARE_COUNTERS + SPARE_DATA
FACTORY_OBJS = (0xE0F0, 0xE0E0, 0xE140)
FACTORY_CHANGE = {0xE0F0: b"\xff", 0xE0E0: b"\xff", 0xE140: b"\xe1\xfc\x07\xfe\x20\xe1\x40"}
FROZEN_AT_T9 = SPARES + FACTORY_OBJS
LCSO_BELOW_OP = b"\xe1\xfc\x07"


def spare_state(meta):
    """One spare from its metadata: "frozen" (LcsO operational, Change LcsO<op or NEV), "open" (as
    it came: below operational, Change LcsO<op; T9 freezes it) or "odd" (anything else: T9 leaves
    it alone and says so)."""
    ch = bytes(meta.get("change") or b"")
    lcso = meta.get("lcso")
    if lcso == OPERATIONAL and ch in (b"\xff", LCSO_BELOW_OP):
        return "frozen"
    if isinstance(lcso, int) and lcso < OPERATIONAL and ch == LCSO_BELOW_OP:
        return "open"
    return "odd"


def object_state(oid, meta):
    """spare_state for a spare; for a factory object: "frozen" (operational, its rules as they came),
    "open" (below operational, rules as they came: T9 freezes it), else "odd"."""
    if oid not in FACTORY_CHANGE:
        return spare_state(meta)
    if bytes(meta.get("change") or b"") != FACTORY_CHANGE[oid]:
        return "odd"
    lcso = meta.get("lcso")
    if lcso == OPERATIONAL:
        return "frozen"
    return "open" if isinstance(lcso, int) and lcso < OPERATIONAL else "odd"


def oid_list(v):
    """secrets.TRUSTM_KEEP_OPEN ("F1D2" or 0xF1D2, one or a list) as a tuple of OIDs."""
    if not v:
        return ()
    if isinstance(v, (str, int)):
        v = [v]
    return tuple(int(x, 16) if isinstance(x, str) else int(x) for x in v)


def spares_text(states):
    """{oid: state} in a few words: "all 26 frozen", "19 of 26 frozen; open F1D3 F1E0 ...",
    with any kept open or odd named."""
    n = len([s for s in states.values() if s != "absent"])
    frozen = [o for o, s in states.items() if s == "frozen"]
    out = ["all %d frozen" % n if len(frozen) == n else "%d of %d frozen" % (len(frozen), n)]
    for what, label in (("open", "open"), ("kept", "kept open"), ("odd", "left alone (not factory)")):
        names = sorted("%04X" % o for o, s in states.items() if s == what)
        if names:
            out.append("%s %s" % (label, " ".join(names[:6]) + (" +%d" % (len(names) - 6) if len(names) > 6 else "")))
    return "; ".join(out)


# ----------------------------------------------------------------------------- the certificate
SPKI_P256 = bytes.fromhex("3059301306072a8648ce3d020106082a8648ce3d03010703420004")


def _tlv(b, i):
    """(tag, value start, value end) of the DER element at i."""
    tag, n = b[i], b[i + 1]
    i += 2
    if n & 0x80:
        k = n & 0x7F
        n = int.from_bytes(b[i:i + k], "big")
        i += k
    return tag, i, i + n


def cert_der(e0e0):
    """The X.509 certificate out of E0E0. Infineon stores it in a TLS-style wrapper: C0, a 2-byte
    length, the chain's 3-byte length, the certificate's 3-byte length, then the DER."""
    b = bytes(e0e0)
    if b[:1] == b"\xc0":
        n = int.from_bytes(b[6:9], "big")
        return b[9:9 + n]
    if b[:1] == b"\x30":
        return b
    raise ValueError("E0E0 holds no certificate")


def _cn(tbs, start):
    """The next common name (OID 2.5.4.3) at or after start: (name, end)."""
    i = tbs.find(b"\x06\x03\x55\x04\x03", start)
    if i < 0:
        return None, start
    _, s, e = _tlv(tbs, i + 5)
    return tbs[s:e].decode(), e


def cert_parse(der):
    """{tbs, r, s, qx, qy, serial, issuer, subject} of a P-256 certificate signed with ECDSA-SHA256."""
    der = bytes(der)
    _, s0, _ = _tlv(der, 0)
    _, ts, te = _tlv(der, s0)
    tbs = der[s0:te]
    _, _, ae = _tlv(der, te)                # signatureAlgorithm
    tag, bs, be = _tlv(der, ae)
    if tag != 0x03:
        raise ValueError("no signature")
    sig = der[bs + 1:be]
    _, i, _ = _tlv(sig, 0)
    _, rs, re_ = _tlv(sig, i)
    _, ss, se = _tlv(sig, re_)
    k = tbs.find(SPKI_P256)
    if k < 0:
        raise ValueError("not a P-256 key")
    k += len(SPKI_P256)
    # serial: after the TBS header and the optional [0] version
    _, j, _ = _tlv(tbs, 0)
    if tbs[j] == 0xA0:
        _, _, j = _tlv(tbs, j)
    _, ns, ne = _tlv(tbs, j)
    issuer, at = _cn(tbs, ne)
    subject, _ = _cn(tbs, at)
    # validity: after the serial, the signature algorithm and the issuer
    valid = (None, None)
    try:
        _, _, e = _tlv(tbs, ne)             # signature algorithm
        _, _, e = _tlv(tbs, e)              # issuer
        _, vs, _ = _tlv(tbs, e)             # validity
        _, a0, a1 = _tlv(tbs, vs)
        _, b0, b1 = _tlv(tbs, a1)
        valid = (_date(tbs[a0:a1]), _date(tbs[b0:b1]))
    except (IndexError, ValueError):
        pass
    return {"tbs": tbs, "r": int.from_bytes(sig[rs:re_], "big"), "s": int.from_bytes(sig[ss:se], "big"),
            "qx": int.from_bytes(tbs[k:k + 32], "big"), "qy": int.from_bytes(tbs[k + 32:k + 64], "big"),
            "serial": hexlify(tbs[ns:ne]).decode(), "issuer": issuer, "subject": subject,
            "notBefore": valid[0], "notAfter": valid[1]}


def _date(t):
    """UTCTime (YYMMDD...) or GeneralizedTime (YYYYMMDD...) -> "YYYY-MM-DD"."""
    t = bytes(t).decode()
    if len(t) >= 13 and t[12] == "Z" or len(t) == 13:
        y = int(t[0:2])
        t = ("19" if y >= 50 else "20") + t
    return "%s-%s-%s" % (t[0:4], t[4:6], t[6:8])


def ca_key(issuer):
    if issuer in CAS:
        return CAS[issuer]
    if issuer == EMU_CA:
        return _emu_ca()
    return None


def cert_check(cert):
    """Is the factory certificate signed by the Infineon CA its issuer names? -> (ok, why)."""
    import p256
    ca = ca_key(cert["issuer"])
    if ca is None:
        return False, "unknown issuer %r" % cert["issuer"]
    ok = p256.verify(ca[0], ca[1], hashlib.sha256(cert["tbs"]).digest(), cert["r"], cert["s"])
    return ok, "" if ok else "the CA's signature does not verify"


# ----------------------------------------------------------------------------- record + binding
MAGIC = b"PQ"
BIND_MAGIC = b"PB"
PROFILE_ID = {"quorum-tm1": 3}
BIND_DOMAIN = b"PicoQuorum Trust M key binding v1"


def _b32(v):
    return int(v).to_bytes(32, "big")


def binding_digest(uid, oid, qx, qy):
    """What the factory key E0F0 signs: SHA-256 of the domain, this chip's UID, the key's OID and
    its public key. With E0E0's certificate it says "a genuine Trust M holds this key"."""
    return hashlib.sha256(BIND_DOMAIN + bytes(uid) + oid.to_bytes(2, "big") + _b32(qx) + _b32(qy)).digest()


def record_encode(ser, oid, qx, qy, owner, date, build, profile="quorum-tm1", flags=0):
    """110 bytes for F1D0, integers big-endian:
      0 "PQ" | 2 version 2 | 3 profile | 4 serial (10) | 14 key OID | 16 flags (2) | 18 qx | 50 qy |
      82 owner (20) | 102 date (unix, 4) | 106 build (4)
    Unlike the ATECC's OTP record this one carries the public key: the console reads the key here."""
    ow = bytes.fromhex(owner[2:] if owner.startswith("0x") else owner)
    b = (build or "")[:8]
    bid = bytes.fromhex(b + "0" * (8 - len(b))) if all(c in "0123456789abcdef" for c in b) else bytes(4)
    s = bytes.fromhex(ser) if isinstance(ser, str) else bytes(ser)
    r = (MAGIC + bytes([2, PROFILE_ID.get(profile, 0)]) + s + oid.to_bytes(2, "big") + flags.to_bytes(2, "big")
         + _b32(qx) + _b32(qy) + ow + int(date).to_bytes(4, "big") + bid)
    assert len(r) == 110
    return r


def record_decode(b):
    """F1D0 as a record, or None (a factory chip reads back zeros)."""
    b = bytes(b)
    if len(b) < 110 or b[:2] != MAGIC or b[2] != 2:
        return None
    return {"profile": {v: k for k, v in PROFILE_ID.items()}.get(b[3], "?"), "serial": hexlify(b[4:14]).decode(),
            "oid": int.from_bytes(b[14:16], "big"), "flags": int.from_bytes(b[16:18], "big"),
            "qx": int.from_bytes(b[18:50], "big"), "qy": int.from_bytes(b[50:82], "big"),
            "owner": "0x" + hexlify(b[82:102]).decode(), "date": int.from_bytes(b[102:106], "big"),
            "build": hexlify(b[106:110]).decode()}


def binding_encode(r, s, cert):
    """83 bytes for F1D1: "PB" | version 1 | r | s | SHA-256(certificate DER)[:16]."""
    return BIND_MAGIC + b"\x01" + _b32(r) + _b32(s) + hashlib.sha256(bytes(cert)).digest()[:16]


def binding_decode(b):
    b = bytes(b)
    if len(b) < 83 or b[:2] != BIND_MAGIC or b[2] != 1:
        return None
    return {"r": int.from_bytes(b[3:35], "big"), "s": int.from_bytes(b[35:67], "big"),
            "cert": hexlify(b[67:83]).decode()}


def binding_check(bind, cert_der_bytes, cert, uid, oid, qx, qy):
    """Does F1D1 hold E0F0's signature over this key, made under this certificate? -> bool."""
    import p256
    if not bind or bind["cert"] != hexlify(hashlib.sha256(bytes(cert_der_bytes)).digest()[:16]).decode():
        return False
    return p256.verify(cert["qx"], cert["qy"], binding_digest(uid, oid, qx, qy), bind["r"], bind["s"])


# ----------------------------------------------------------------------------- a remembered pass
# cert_check and binding_check are two P-256 verifies, about 2.3 s each on the Pico, over bytes the
# chip only gives out: its UID, E0E0, F1D1, F1D0 (and the key's OID and the pinned CA key). Their
# answer is a function of those bytes, so a pass is remembered by their hash: a boot that reads
# the same bytes has the same answer without the math. Only a pass is kept; anything else runs
# both checks again. Not handed to the chip's own VerifySign: these ask whether the chip is
# genuine, and a counterfeit would say yes. The file is on the board's flash, which is no weaker
# than the firmware beside it.
PROOF_FILE = "tmproof.txt"
PROOF_DOMAIN = b"PicoQuorum Trust M proof v1"   # change it when either check changes


def proof(uid, oid, der, binding, record, issuer):
    """The hash of everything the two checks decide from, or None (no pinned CA for this issuer)."""
    ca = ca_key(issuer)
    if ca is None:
        return None
    h = hashlib.sha256(PROOF_DOMAIN)
    for part in (bytes(uid), oid.to_bytes(2, "big"), bytes(der), bytes(binding), bytes(record), _b32(ca[0]), _b32(ca[1])):
        h.update(len(part).to_bytes(2, "big"))
        h.update(part)
    return hexlify(h.digest()).decode()


def _proofs():
    try:
        with open(PROOF_FILE) as f:
            return dict(line.split() for line in f if line.strip())
    except (OSError, ValueError):
        return {}


def proof_known(serial, p):
    return _proofs().get(serial) == p


def proof_keep(serial, p):
    d = _proofs()
    d[serial] = p
    try:
        with open(PROOF_FILE, "w") as f:
            for k in d:
                f.write("%s %s\n" % (k, d[k]))
    except OSError:
        pass                                # a full flash costs the next boot the checks, nothing else


# ----------------------------------------------------------------------------- what the screens say
def short_ca(issuer):
    """ "Infineon OPTIGA(TM) Trust M CA 101" -> "CA 101"."""
    if not issuer:
        return "?"
    if issuer == EMU_CA:
        return "emulator CA"
    i = issuer.find("CA ")
    return issuer[i:] if i >= 0 else issuer[-16:]


def info_lines(uid, issuer=None, key=None, bound=None, sec=None):
    """Short facts, each from the chip itself, for the Signing and Device screens and the ceremony,
    most telling first (the Signing screen shows four): which silicon, where the key came from and
    what seals it, the factory binding, and the chip's own brake on bursts of key use."""
    f = uid_fields(uid) if uid else None
    out = ["Infineon OPTIGA Trust M, CC EAL6+"]
    if key:
        if key.get("hasKey"):
            out.append("Key %04X made on-chip, %s" % (KEY, "sealed (LcsO op)" if key.get("locked") else "not sealed"))
        else:
            out.append("Key %04X: empty" % KEY)
    if bound is not None:
        out.append(("Bound to Infineon cert, %s" % short_ca(issuer)) if bound else "No factory binding")
    elif issuer:
        out.append("Factory cert from %s" % short_ca(issuer))
    if sec is not None:
        out.append("Security event counter: %d" % sec)
    if f:
        out.append("fw %s build %s, wafer %d,%d" % (f["fw"], f["build"], f["x"], f["y"]))
    return out


def detail_pages(uid, cert=None, ca_ok=None, key=None, bound=None, rec=None, sec=None, lcsa=None, spares=None):
    """The console's Chip pages for a Trust M, every value read off the chip (quorum.open_chip):
    [(title, [(label, value), ...]), ...]. Values may be long; the screen wraps them."""
    f = uid_fields(uid)
    silicon = [("Part", "Infineon OPTIGA Trust M"), ("Certified", "CC EAL6+ secure element"),
               ("Firmware", "%s build %s" % (f["fw"], f["build"])), ("Serial", serial(uid)),
               ("Wafer", "X %d, Y %d, batch %s" % (f["x"], f["y"], hexlify(f["batch"]).decode())),
               ("Lifecycle", "LcsA %s" % lcs_name(lcsa)),
               ("Spares", "not read" if spares is None else
                "%s: nothing else on the chip can be written or get a key" % spares_text(spares)
                if all(s in ("frozen", "absent") for s in spares.values()) else spares_text(spares) + " (ceremony T9 freezes them)"),
               ("Security", "%s events. Key use is paid from an idle credit; bursts count and slow the chip"
                % ("?" if sec is None else sec))]
    pages = [("The chip", silicon)]
    if cert:
        c = [("Issuer", cert["issuer"] or "?"), ("Subject", cert["subject"] or "?"), ("Serial", cert["serial"]),
             ("Valid", "%s to %s" % (cert.get("notBefore") or "?", cert.get("notAfter") or "?")),
             ("CA check", {True: "verified on this Pico with the pinned %s key" % short_ca(cert["issuer"]),
                           False: "FAILED: not signed by a pinned Infineon CA", None: "not checked"}[ca_ok]),
             ("Its key", "E0F0, the factory key, %08x" % (cert["qx"] >> 224))]
        pages.append(("Factory certificate", c))
    if key:
        k = [("Key", "%04X, %s, made on this chip" % (KEY, key.get("kind", "?"))),
             ("Sealed", "yes: lifecycle operational, can never be made again" if key.get("locked") else
              "no: lifecycle %s, it can still be replaced" % lcs_name(key.get("lcso"))),
             ("Access", "change %s, use %s" % (key.get("change", "-"), key.get("exec", "-")))]
        if rec:
            k.append(("Public key", "%08x (record in F1D0)" % (rec["qx"] >> 224)))
            k.append(("Owner", rec["owner"]))
        k.append(("Binding", {True: "E0F0 signed this key; verified under the Infineon certificate",
                              False: "MISSING or does not verify", None: "not checked"}[bound]))
        if rec and rec.get("date"):
            import time
            t = time.gmtime(rec["date"])
            k.append(("Made", "%04d-%02d-%02d, build %s" % (t[0], t[1], t[2], rec.get("build", "?"))))
        pages.append(("Signing key", k))
    return pages

# Infineon OPTIGA Trust M (Adafruit 4351 breakout) on the wallet's I2C bus, GP4 SDA / GP5 SCL.
# Physical layer only, straight from the datasheet (SLS32AIA, rev 3.70, chapter A):
#   - 7-bit address 0x30
#   - the chip NACKs its address while asleep or busy; retry every 1 ms, give up after 200 tries
#     (Infineon's ifx_i2c_physical_layer.c: PL_POLLING_MAX_CNT 200, PL_POLLING_INVERVAL_US 1000)
#   - GUARD_TIME 50 us between one transaction's STOP and the next START; we wait 100 us
#   - soft reset: write register 0x88 with two zero bytes, then tSTARTUP 15..20 ms
# Registers: 0x80 DATA, 0x82 I2C_STATE (4 bytes: flags, rfu, length hi, length lo).
# I2C_STATE byte 0: 0x80 BUSY, 0x40 RESP_RDY, 0x08 SOFT_RESET supported.
from machine import Pin, I2C
import time

ADDR = 0x30
GUARD_US = 100
TRIES = 200

i2c = None


def bus(sda=4, scl=5, freq=400000):
    global i2c
    i2c = I2C(0 if sda % 4 == 0 else 1, sda=Pin(sda), scl=Pin(scl), freq=freq)
    return i2c


def _write(data):
    for _ in range(TRIES):
        try:
            i2c.writeto(ADDR, data)
            time.sleep_us(GUARD_US)
            return
        except OSError:
            time.sleep_ms(1)
    raise OSError("trustm: write not acked")


def _read(n):
    for _ in range(TRIES):
        try:
            r = i2c.readfrom(ADDR, n)
            time.sleep_us(GUARD_US)
            return r
        except OSError:
            time.sleep_ms(1)
    raise OSError("trustm: read not acked")


def reg(addr, n):
    _write(bytes([addr]))
    return _read(n)


def state():
    return reg(0x82, 4)


def soft_reset():
    _write(b"\x88\x00\x00")
    time.sleep_ms(25)


def wait_response(timeout_ms=1000):
    """Poll I2C_STATE until RESP_RDY; return the response length."""
    t = time.ticks_ms()
    while True:
        s = state()
        if s[0] & 0x40:
            return (s[2] << 8) | s[3]
        if time.ticks_diff(time.ticks_ms(), t) > timeout_ms:
            raise OSError("trustm: no response, state %s" % s.hex())
        time.sleep_ms(5)


def read_data():
    n = wait_response()
    return reg(0x80, n)


def read_frame():
    """Next data frame. The chip may first hand back its zero-length ack of our last write
    (FCTR 0x8x, LEN 0, FCS); skip those."""
    while True:
        f = read_data()
        if len(f) > 5 or f[1:3] != b"\x00\x00":
            return f


# Datasheet A.2: the exact frames (data-link sequence numbers and FCS included), valid as the
# first two exchanges after a reset.
OPEN_APP = bytes.fromhex("8003001500700000" "10D2760000044765" "6E41757468417070" "6C041A")
OPEN_APP_ACK = bytes.fromhex("8080000" "00CEC")
GET_UID = bytes.fromhex("8004000B00010000" "06E0C200000064F0" "9F")
GET_UID_ACK = bytes.fromhex("8081000" "05630")


def coprocessor_uid():
    """Reset, OpenApplication, GetDataObject(0xE0C2). Returns the 27-byte UID field."""
    soft_reset()
    s = state()
    if s != b"\x08\x80\x00\x00":
        raise OSError("trustm: unexpected state after reset %s" % s.hex())
    _write(OPEN_APP)
    resp = read_frame()          # 00 00 05 00 00 00 00 00 14 87: OpenApplication response
    _write(OPEN_APP_ACK)
    _write(GET_UID)
    resp = read_frame()          # 05 00 20 00 | 00 00 00 1B | CD + 27 bytes | fcs
    _write(GET_UID_ACK)
    if len(resp) != 37 or resp[4:8] != b"\x00\x00\x00\x1b":
        raise OSError("trustm: bad UID response %s" % resp.hex())
    return resp[8:35]


# --- IFX I2C data-link + APDU layer (datasheet frames decoded; FCS is CRC-16 poly 0x8408, init 0, big-endian)
def _crc(data):
    c = 0
    for b in data:
        c ^= b
        for _ in range(8):
            c = (c >> 1) ^ 0x8408 if c & 1 else c >> 1
    return c


class Session:
    """One OpenApplication session after a soft reset. Frame numbers run 0..3."""

    def __init__(self):
        soft_reset()
        self.frnr = 0
        self.acknr = 3
        r = self.command(0x70, 0x00, bytes.fromhex("D2760000044765" "6E41757468417070" "6C"))

    def _send(self, apdu):
        body = bytes([(self.frnr << 2) | self.acknr]) + len(apdu + b"\x00").to_bytes(2, "big") + b"\x00" + apdu
        _write(b"\x80" + body + _crc(body).to_bytes(2, "big"))
        self.frnr = (self.frnr + 1) & 3

    def _recv(self):
        f = read_frame()
        if _crc(f[:-2]) != int.from_bytes(f[-2:], "big"):
            raise OSError("trustm: bad fcs %s" % f.hex())
        self.acknr = (f[0] >> 2) & 3
        ack = bytes([0x80 | self.acknr, 0, 0])
        _write(b"\x80" + ack + _crc(ack).to_bytes(2, "big"))
        return f[4:-2]                      # drop FCTR, LEN, PCTR and FCS

    def command(self, cmd, param, data):
        self._send(bytes([cmd, param]) + len(data).to_bytes(2, "big") + data)
        r = self._recv()
        if r[0] != 0:
            raise OSError("trustm: cmd %02x failed, status %02x, %s" % (cmd, r[0], r[4:].hex()))
        return r[4:4 + int.from_bytes(r[2:4], "big")]

    def get(self, oid, offset=None, length=None):
        d = oid.to_bytes(2, "big")
        if length is not None:
            d += offset.to_bytes(2, "big") + length.to_bytes(2, "big")
        return self.command(0x01, 0x00, d)

    def metadata(self, oid):
        return self.command(0x01, 0x01, oid.to_bytes(2, "big"))

    def sign(self, oid, digest):
        """CalcSign 0x31, ECDSA over a 32-byte digest with the key at oid. Returns (r, s)."""
        d = b"\x01" + len(digest).to_bytes(2, "big") + digest + b"\x03\x00\x02" + oid.to_bytes(2, "big")
        r = self.command(0x31, 0x11, d)
        if r[0] == 0x30:                    # some builds wrap r,s in a SEQUENCE
            r = r[2:]
        out = []
        while r:
            n = r[1]
            out.append(int.from_bytes(r[2:2 + n], "big"))
            r = r[2 + n:]
        return out[0], out[1]

    def random(self, n):
        return self.command(0x0C, 0x00, n.to_bytes(2, "big"))

    def get_all(self, oid, step=200):
        out = b""
        while True:
            part = self.get(oid, len(out), step)
            out += part
            if len(part) < step:
                return out


if __name__ == "__main__":
    bus()
    print("state", state().hex())
    uid = coprocessor_uid()
    print("coprocessor UID", uid.hex())
    print("fw build", uid[25:27].hex())

# PicoQuorum's commands for the OPTIGA Trust M, on top of upstream's firmware/trustm.py (kept as it
# came: docs/UPSTREAM-TRACKING.md). trustm.py has the physical and data-link layers, GetDataObject,
# CalcSign and GetRandom; this adds what the console and the ceremony need:
#   present()                    is a Trust M at 0x30 (it NACKs while asleep, so i2c.scan() misses it)
#   TrustM().uid() / serial()    the 27-byte UID, and tmcfg.serial of it
#   meta(oid)                    parsed metadata (tmcfg.parse_meta)
#   gen_keypair(oid)             GenKeyPair: a NEW P-256 key in oid -> (x, y)      replaces any key there
#   set_data(oid, data)          SetDataObject                                     rewritable until sealed
#   set_lifecycle(oid, lcs)      SetDataObject(metadata) with only LcsO            PERMANENT: never goes down
#   sign(oid, digest)            CalcSign -> (r, s) as the chip gives it (not low-s)
# Command codes and layouts: OPTIGA Trust M Solution Reference Manual, "Command definitions".
# One I2C0 bus with the ATECC608 (GP4/GP5): the same pins, 100 kHz, built by atecc.make_i2c.
import trustm
import tmcfg

GET, SET, CALC_SIGN, GEN_KEYPAIR, GET_RANDOM = 0x01, 0x02, 0x31, 0x38, 0x0C
SET_DATA, SET_META, ERASE_WRITE = 0x00, 0x01, 0x40
ECC_P256 = 0x03
ERR_CODES = 0xF1C2      # the chip's last error code, read after a refusal


def bus(sda=None, scl=None):
    """Point upstream's module at the shared I2C0 bus."""
    import atecc
    trustm.i2c = atecc.make_i2c(atecc.SDA if sda is None else sda, atecc.SCL if scl is None else scl, 100_000)
    return trustm.i2c


def present(tries=40):
    """A Trust M answers at 0x30. Asleep it NACKs its address for a moment after the first try, so
    poll its state register like trustm.py does, a little."""
    import time
    if trustm.i2c is None:
        bus()
    for _ in range(tries):
        try:
            trustm.i2c.writeto(trustm.ADDR, b"\x82")
            time.sleep_us(trustm.GUARD_US)
            s = trustm.i2c.readfrom(trustm.ADDR, 4)
            return len(s) == 4
        except OSError:
            time.sleep_ms(1)
    return False


class Refused(OSError):
    """The chip answered and said no (an access condition, a bad OID): not a bus problem."""


class TrustM:
    def __init__(self):
        if trustm.i2c is None:
            bus()
        self.s = None
        self.trace = False

    def _session(self):
        if self.s is None:
            self.s = trustm.Session()
        return self.s

    def command(self, cmd, param, data, retry=True):
        """One APDU. A bus or framing error reopens the session and tries once more (upstream's
        Session has no retransmit); a refusal by the chip raises Refused at once."""
        try:
            return self._session().command(cmd, param, data)
        except OSError as e:
            msg = str(e)
            if "failed, status" in msg:
                raise Refused(msg + self._last_error())
            self.s = None
            if not retry:
                raise
            return self._session().command(cmd, param, data)

    def _last_error(self):
        try:
            code = self._session().command(GET, 0x00, ERR_CODES.to_bytes(2, "big"))
            return " (error code %s)" % "".join("%02x" % b for b in code)
        except Exception:
            self.s = None
            return ""

    # --- reads ------------------------------------------------------------------------
    def get(self, oid, offset=None, length=None):
        d = oid.to_bytes(2, "big")
        if length is not None:
            d += offset.to_bytes(2, "big") + length.to_bytes(2, "big")
        return self.command(GET, 0x00, d)

    def get_all(self, oid, step=200):
        out = b""
        while True:
            part = self.get(oid, len(out), step)
            out += part
            if len(part) < step:
                return out

    def metadata(self, oid):
        return self.command(GET, 0x01, oid.to_bytes(2, "big"))

    def meta(self, oid):
        return tmcfg.parse_meta(self.metadata(oid))

    def uid(self):
        return bytes(self.get(tmcfg.UID))

    def serial(self):
        return tmcfg.serial(self.uid())

    def sec(self):
        """The security event counter (E0C5): 0 on a quiet chip."""
        return self.get(tmcfg.SEC)[0]

    def lcsa(self):
        return self.get(tmcfg.LCSA)[0]

    def random(self, n=32):
        return self.command(GET_RANDOM, 0x00, n.to_bytes(2, "big"))

    # --- the key ----------------------------------------------------------------------
    def sign(self, oid, digest):
        """CalcSign (ECDSA over a 32-byte digest) with the key at oid -> (r, s), s as the chip made it."""
        d = b"\x01" + len(digest).to_bytes(2, "big") + bytes(digest) + b"\x03\x00\x02" + oid.to_bytes(2, "big")
        r = self.command(CALC_SIGN, 0x11, d)
        if r[0] == 0x30:                    # some builds wrap r,s in a SEQUENCE
            r = r[2:]
        out = []
        while r:
            n = r[1]
            out.append(int.from_bytes(r[2:2 + n], "big"))
            r = r[2 + n:]
        return out[0], out[1]

    def gen_keypair(self, oid, usage=tmcfg.USAGE_SIGN):
        """GenKeyPair: a NEW P-256 key in oid, replacing any key there (the chip checks oid's Change
        condition). -> (x, y), which the chip gives only now: keep it (F1D0)."""
        d = b"\x01\x00\x02" + oid.to_bytes(2, "big") + b"\x02\x00\x01" + bytes([usage])
        r = bytes(self.command(GEN_KEYPAIR, ECC_P256, d, retry=False))
        pub = r[-65:]                       # tag 02, length, then the key as a BIT STRING: 03 42 00 04 X Y
        if len(pub) != 65 or pub[0] != 0x04:
            raise OSError("trustm: GenKeyPair answered %s" % "".join("%02x" % b for b in r))
        return int.from_bytes(pub[1:33], "big"), int.from_bytes(pub[33:65], "big")

    # --- data objects -----------------------------------------------------------------
    def set_data(self, oid, data, offset=0, erase=True):
        """SetDataObject: write data at offset (erase: the object is cleared first, so a shorter
        write leaves nothing behind). The chip checks oid's Change condition."""
        d = oid.to_bytes(2, "big") + offset.to_bytes(2, "big") + bytes(data)
        return self.command(SET, ERASE_WRITE if erase else SET_DATA, d)

    def set_lifecycle(self, oid, lcs=tmcfg.OPERATIONAL):
        """PERMANENT. Raise oid's LcsO. A lifecycle state never goes down: with the factory Change
        condition "LcsO < op", operational freezes the object for good."""
        d = oid.to_bytes(2, "big") + b"\x00\x00" + tmcfg.meta_tlv(lcso=lcs)
        return self.command(SET, SET_META, d, retry=False)

# Layer 4: the few calls the console makes to Safe's transaction service, at the real service's
# paths (api.safe.global/tx-service/<chain>), so the same code talks to tools/quorum's mock on the
# laptop and, later, to the real thing. Nothing here is trusted: quorum.py rehashes every
# transaction from its fields and refuses any whose hash or Safe differs from what it pinned.
#
#   s = Service(base_url, safe)
#   s.target(base_url, safe)   another Safe, maybe on another chain's service
#   s.safe_info() -> {"nonce", "threshold", "owners", ...}
#   s.pending(nonce) -> [transaction, ...] oldest nonce first
#   s.confirm(safe_tx_hash, signature) -> (ok, detail)
from binascii import hexlify
import gc
import sys
import requests
from keccak import keccak256
from policy import is_sim

TIMEOUT = 5            # the laptop's service, plain HTTP on the LAN
TIMEOUT_TLS = 15       # api.safe.global: a full TLS handshake on the Pico each call, 1-2 s, sometimes over 5
# HTTPS needs room in one piece. The console's heap fragments as it decodes and draws: on the
# board, after a review, 154 KB were free but no block over 8 KB, and the confirmation's POST failed
# with OSError 12 (2026-09-25). So an https Service holds one block from the start and lets go of it
# only for the length of each call. Measured on the board (2026-10-02, a heap full but for one hole):
# a call to Safe's service fails in 28 KB, takes 8 s in 32 KB (the GC working the whole time),
# 0.9 s in 36 KB. So 40 KB. The body is not read into it: a 6.7 KB queue read as pieces then
# joined needed a 48 KB hole, so it goes into BODY, a buffer of its own kept from boot, and is
# copied out only once the connection is closed and the reserve taken back.
RESERVE = 40 * 1024
BODY = 16 * 1024        # a bigger queue: MemoryError, and quorum.fetch_queue asks for 3 transactions
ON_BOARD = sys.platform == "rp2"     # the emulator's `requests` is the host's curl, which checks certificates itself
_early = None
_body = None


def reserve_early():
    """Take the reserve and the body buffer at boot, before the console's modules load
    (main_console.py): blocks taken then are whole; ones taken after them may not exist any more.
    The first https Service keeps the reserve."""
    global _early, _body
    gc.collect()
    try:
        _early = bytearray(RESERVE)
    except MemoryError:
        _early = None
    if ON_BOARD and _body is None:
        try:
            _body = bytearray(BODY)
        except MemoryError:
            _body = None


def checksum(a):
    """EIP-55 mixed case. Safe's service wants addresses in its paths spelled this way."""
    a = a.lower().replace("0x", "")
    h = hexlify(keccak256(a.encode())).decode()
    return "0x" + "".join(c.upper() if int(h[i], 16) >= 8 else c for i, c in enumerate(a))


class ServiceError(Exception):
    pass


def why(code, out):
    """What the service said, for the screen and the log: its `detail`, else the first message it gave
    under any other name (Safe's validation errors come as {"nonFieldErrors": [...]}, {"signature": [...]}),
    else the bare HTTP code. Kept short. It used to read only `detail`, so a rejected signature showed
    "the service said: " and nothing (2026-09-30)."""
    if code in (200, 201):
        return ""
    msg = ""
    if isinstance(out, dict):
        msg = out.get("detail") or ""
        if not msg:
            for k, v in out.items():
                v = v[0] if isinstance(v, (list, tuple)) and v else v
                if v and not isinstance(v, (dict, list, tuple)):
                    msg = "%s: %s" % (k, v) if k not in ("nonFieldErrors", "non_field_errors") else str(v)
                    break
    elif out:
        msg = str(out)
    return ("HTTP %s" % code + (": " + msg if msg else ""))[:120]


class Service:
    def __init__(self, base, safe, api_key=None, verify=True, floor=0):
        """verify: check the server's certificate against the pinned roots (vhttp.py). Only a
        development board may turn it off (QUORUM_TLS_VERIFY = False); the production image cannot.
        floor: the build's date; the clock is never trusted below it.
        One Service serves every Safe the console watches (target() switches between them), so
        the TLS context and the HTTPS reserve exist once, however many Safes there are."""
        self.api_key = api_key
        self.verify = verify
        self.requests = 0                # since boot, for the device screen (the real service has a monthly quota)
        self.floor = floor
        self._ctx = None
        self._room = None
        self.lost = False
        self.target(base, safe)
        global _early
        if self.base.startswith("https"):
            self._room, _early = _early, None
        self.hold()

    def target(self, base, safe):
        """Ask about this Safe at this service from now on (a Safe on another chain has another
        service: api.safe.global/tx-service/<chain>)."""
        self.base = base.rstrip("/")
        self.safe = safe
        self.sim = is_sim(self.base)     # tools/quorum on the laptop: its /sim endpoints exist
        https = self.base.startswith("https")
        if not https:
            self.tls = "plain"
        elif not ON_BOARD:
            self.tls = "host"
        elif self.verify:
            if self._ctx is None:
                import vhttp
                self._ctx = vhttp.context()      # the first https target: at start, while the heap is whole
            self.tls = "verified"
        else:
            self.tls = "UNVERIFIED"
        # the API key goes only to Safe's own service over HTTPS, never to a laptop on the LAN
        self.headers = {"Authorization": "Bearer " + self.api_key} if self.api_key and https else {}
        self.timeout = TIMEOUT_TLS if https else TIMEOUT

    def hold(self):
        """Take the reserve back (https only). If it no longer fits, `lost` says so: the heap has
        split where the reserve was, and the console restarts at its next quiet moment (quorum.py)
        rather than fail every call from then on (seen on the board, 2026-09-26)."""
        if self._room is None and self.base.startswith("https"):
            gc.collect()
            try:
                self._room = bytearray(RESERVE)
                self.lost = False
            except MemoryError:
                self._room = None
                self.lost = True

    def release(self):
        """Give the reserve back to the heap, for an HTTPS call or anything else that needs room."""
        self._room = None
        gc.collect()

    def _call(self, method, path, body=None):
        try:
            import watch
            # connect and the handshake (each socket step up to the timeout), then vhttp's 40 s
            # budget for the response: a slow call that is still alive must not reset the board
            watch.extend(4 * int(self.timeout * 1000) + 40000)
        except ImportError:
            pass
        if self._ctx is not None and self.base.startswith("https"):
            import vhttp
            vhttp.clock(self.floor)
            return vhttp.request(method, self.base + path, self._ctx, body=body, headers=self.headers, timeout=self.timeout,
                                 into=_body)
        if method == "GET":
            return requests.get(self.base + path, headers=self.headers, timeout=self.timeout)
        return requests.post(self.base + path, json=body, headers=self.headers, timeout=self.timeout)

    def _fetch(self, method, path, body=None):
        """(status, body bytes). The reserve is lent for the call and taken back before anything
        is parsed: what the console keeps from a response must not land where the reserve goes."""
        self.release()
        self.requests += 1
        try:
            r = self._call(method, path, body)
            try:
                status, out = r.status_code, r.content
            finally:
                r.close()
                r = None
        finally:
            self.hold()
        return status, bytes(out)       # out of BODY (a memoryview), now that the reserve is back

    def _get(self, path):
        import json
        status, data = self._fetch("GET", path)
        if status != 200:
            raise ServiceError("HTTP %d" % status)
        return json.loads(data)

    def _post(self, path, body):
        import json
        status, data = self._fetch("POST", path, body)
        try:
            out = json.loads(data)
        except ValueError:
            out = {}
        return status, out

    def safe_info(self):
        return self._get("/api/v1/safes/%s/" % self.safe)

    def pending(self, nonce, limit=10):
        q = "?executed=false&nonce__gte=%d&ordering=nonce&limit=%d" % (nonce, limit)
        return self._get("/api/v2/safes/%s/multisig-transactions/%s" % (self.safe, q)).get("results", [])

    def confirm(self, safe_tx_hash, signature):
        code, out = self._post("/api/v1/multisig-transactions/%s/confirmations/" % safe_tx_hash, {"signature": signature})
        return code in (200, 201), why(code, out)

    # --- the simulation's own endpoints (tools/quorum). Never sent to a real service: they would
    # spend its quota and hand it this key's public key for nothing.
    def announce(self, name, qx, qy):
        if not self.sim:
            return None
        code, out = self._post("/sim/device", {"name": name, "qx": qx, "qy": qy})
        return out.get("owner") if code == 200 else None

    def declined(self, safe_tx_hash, by):
        if not self.sim:
            return
        try:
            self._post("/sim/declined", {"safeTxHash": safe_tx_hash, "by": by})
        except Exception:
            pass

# Layer 3: the chip's P-256 signature packed the way the Safe checks it. A P-256 key cannot own a
# Safe by itself, so each chip key sits behind its own SafeWebAuthnSignerProxy (Safe's audited
# passkey signer, safe-modules passkey v0.2.1), deployed by the factory at an address fixed by the
# key. The Safe asks that proxy "is this a signature over the safeTxHash?", and the proxy checks a
# WebAuthn assertion, so the console produces one:
#
#   authenticatorData = sha256(RP_ID) || flags (UP|UV) || counter 0
#   clientDataJSON    = {"type":"webauthn.get","challenge":"<base64url(safeTxHash)>",<FIELDS>}
#   the chip signs      sha256(authenticatorData || sha256(clientDataJSON))
#
# The challenge is the safeTxHash safe_tx.py computed here from the fields on screen, so this is
# still no blind signature: every byte the chip signs is derived on the device. The contract
# requires the UV flag and ignores the rpIdHash and counter. Pure (no chip, no network), so
# test-vectors/run.py checks it on CPython and on MicroPython against viem and the deployed factory.
#
#   ad, fields, digest = assertion(safe_tx_hash)       the chip signs digest -> (r, s)
#   contract_signature(owner, ad, fields, r, s)         what the transaction service is sent
#   owner_address(qx, qy, CFG["signer"])                this key's Safe owner (the proxy's address)
import hashlib
from binascii import b2a_base64, hexlify
from keccak import keccak256

RP_ID = b"picoquorum"
FLAGS = 0x05                            # user present | user verified (the contract needs UV)
FIELDS = '"origin":"picoquorum"'        # the rest of clientDataJSON after the challenge


def _b(h):
    if isinstance(h, (bytes, bytearray)):
        return bytes(h)
    return bytes.fromhex(h[2:] if h.startswith("0x") else h)


def _u256(n):
    """A uint256 word from an int or a 0x hex string."""
    if isinstance(n, str):
        n = int(n, 16)
    return int(n).to_bytes(32, "big")


def _pad(b):
    return b + bytes(-len(b) % 32)


def b64url(b):
    """base64url without padding, as WebAuthn puts the challenge in clientDataJSON."""
    s = b2a_base64(b).decode().strip()
    return s.replace("+", "-").replace("/", "_").replace("=", "")


def client_json(challenge):
    return '{"type":"webauthn.get","challenge":"%s",%s}' % (b64url(challenge), FIELDS)


def assertion(challenge):
    """(authenticatorData, clientDataFields, the 32 bytes the chip signs) for a 32-byte safeTxHash."""
    challenge = _b(challenge)
    if len(challenge) != 32:
        raise ValueError("challenge must be 32 bytes")
    ad = hashlib.sha256(RP_ID).digest() + bytes([FLAGS]) + bytes(4)
    cd = hashlib.sha256(client_json(challenge).encode()).digest()
    return ad, FIELDS, hashlib.sha256(ad + cd).digest()


def encode(ad, fields, r, s):
    """abi.encode(bytes authenticatorData, string clientDataFields, uint256 r, uint256 s),
    canonical: the contract refuses trailing bytes."""
    f = fields.encode()
    tail_a = _u256(len(ad)) + _pad(ad)
    return _u256(128) + _u256(128 + len(tail_a)) + _u256(r) + _u256(s) + tail_a + _u256(len(f)) + _pad(f)


def contract_signature(owner, ad, fields, r, s):
    """One owner's confirmation in the Safe's signature layout for a contract owner (v = 0): the
    owner as r, the offset of its data as s (65, right after this one 65-byte slot), then the data
    with its length. The service stores it as sent and re-lays it out when it joins others."""
    data = encode(ad, fields, r, s)
    return bytes(12) + _b(owner) + _u256(65) + b"\x00" + _u256(len(data)) + data


def owner_inputs(qx, qy, signer):
    """(factory, init code): everything owner_address depends on."""
    return _b(signer["factory"]), (_b(signer["proxyCode"]) + bytes(12) + _b(signer["singleton"]) + _u256(qx) + _u256(qy)
                                   + _u256(signer["verifiers"]))


def owner_address(qx, qy, signer, inputs=None):
    """The SafeWebAuthnSignerProxy the factory deploys for this key: CREATE2 with salt 0 over the
    proxy's creation code and its constructor arguments (singleton, x, y, verifiers). signer is
    quorum_cfg.CFG["signer"]; its verifiers are part of the address, so they can never change.
    Two pure-Python keccaks over ~0.6 KB: about 0.7 s on the Pico."""
    factory, init = inputs or owner_inputs(qx, qy, signer)
    h = keccak256(b"\xff" + factory + bytes(32) + keccak256(init))
    return "0x" + hexlify(h[12:]).decode()

# The Wi-Fi networks this board has been given (wifi.json), and the parts of the Wi-Fi setup
# hotspot (wifisetup.py) that need no radio: the checks on a name and password, the form a phone
# fills in, the page it gets back, and the one-answer DNS that sends a phone's "is this a captive
# portal?" check to that page. Pure Python, so test-vectors/wifisetup_test.py runs it on the laptop.
#
# wifi.json is written only by the setup screen and read by net.py before secrets.py's WIFI_SSID.
# It holds Wi-Fi and nothing else: setup can never touch the pin, the Safes or the API key.
import json
import os

FILE = "wifi.json"
MAX_SAVED = 4           # the newest first; a fifth network pushes the oldest out
MAX_BODY = 1024         # a form bigger than this is not ours


def load(path=FILE):
    """[(ssid, password)], the most recently set up first. A missing or broken file is no networks."""
    try:
        with open(path) as f:
            d = json.load(f)
        return [(n["ssid"], n.get("pass", "")) for n in d["networks"] if n.get("ssid")]
    except (OSError, ValueError, KeyError, TypeError, AttributeError):
        return []


def save(ssid, pw, path=FILE):
    """Put this network first, keep the others (but not a second copy of this one)."""
    nets = [(ssid, pw)] + [n for n in load(path) if n[0] != ssid]
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        json.dump({"networks": [{"ssid": s, "pass": p} for s, p in nets[:MAX_SAVED]]}, f)
    os.rename(tmp, path)        # a power cut leaves the old file or the new one, never half of one


def forget(path=FILE):
    try:
        os.remove(path)
    except OSError:
        pass


def check(ssid, pw):
    """Why this name and password cannot be a Wi-Fi network, or None. An empty password is an
    open network; otherwise WPA2 wants 8 to 63 printable ASCII characters (or 64 hex digits)."""
    if not ssid:
        return "Pick or type a network name"
    if len(ssid.encode()) > 32:
        return "A network name is at most 32 bytes"
    if not pw:
        return None
    if len(pw) == 64 and all(c in "0123456789abcdefABCDEF" for c in pw):
        return None
    if any(not " " <= c <= "~" for c in pw):
        return "The password has a character Wi-Fi does not allow"
    if len(pw) < 8:
        return "A Wi-Fi password is at least 8 characters"
    if len(pw) > 63:
        return "A Wi-Fi password is at most 63 characters"
    return None


def qr_join(ssid, pw):
    """The text of a QR code that a phone's camera turns into "join this network"."""
    esc = lambda s: "".join("\\" + c if c in "\\;,:\"" else c for c in s)
    return "WIFI:T:WPA;S:%s;P:%s;;" % (esc(ssid), esc(pw))


# ------------------------------------------------------------------------------------- the form

def unquote(s):
    """application/x-www-form-urlencoded value -> str."""
    s = s.replace("+", " ")
    out = bytearray()
    i = 0
    while i < len(s):
        c = s[i]
        if c == "%" and _hex(s[i + 1:i + 3]):
            out.append(int(s[i + 1:i + 3], 16))
            i += 3
        else:
            out.extend(c.encode())
            i += 1
    try:
        return out.decode()
    except UnicodeError:
        return ""


def _hex(s):
    return len(s) == 2 and all(c in "0123456789abcdefABCDEF" for c in s)


def parse_form(body):
    if isinstance(body, (bytes, bytearray)):
        try:
            body = bytes(body).decode()
        except UnicodeError:
            return {}
    out = {}
    for part in body.split("&"):
        if "=" in part:
            k, v = part.split("=", 1)
            out[unquote(k)] = unquote(v)
    return out


def parse_request(raw):
    """(method, path, headers, body) from the bytes a browser sent, or None if they are not a request."""
    head, sep, body = bytes(raw).partition(b"\r\n\r\n")
    if not sep:
        return None
    try:
        lines = head.decode().split("\r\n")
        method, path = lines[0].split(" ")[:2]
    except (UnicodeError, ValueError):
        return None
    headers = {}
    for line in lines[1:]:
        if ":" in line:
            k, v = line.split(":", 1)
            headers[k.strip().lower()] = v.strip()
    return method, path, headers, body


def body_length(headers):
    try:
        return max(0, min(int(headers.get("content-length", "0")), MAX_BODY))
    except ValueError:
        return 0


# ------------------------------------------------------------------------------------- the page

def esc(s):
    return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace('"', "&quot;")


_CSS = ("body{font:17px system-ui,sans-serif;margin:0;padding:20px;background:#060a1a;color:#eef}"
        "h1{font-size:22px;margin:0 0 14px}label{display:block;margin:14px 0 6px;color:#aab}"
        "select,input{width:100%;box-sizing:border-box;font-size:18px;padding:11px;border-radius:9px;"
        "border:1px solid #3a4670;background:#141e3a;color:#fff}"
        "button{margin-top:20px;width:100%;font-size:19px;padding:14px;border:0;border-radius:10px;"
        "background:#2f7dff;color:#fff}.m{padding:12px;border-radius:9px;margin-bottom:8px}"
        ".bad{background:#4a1418;color:#ffb4ae}.ok{background:#0d3d24;color:#9ff0c0}.wait{background:#1d2a52}"
        "small{color:#8890a8}")


def page(st):
    """The setup page, for whatever state setup is in (st: wifisetup.st)."""
    state, ssid = st.get("state"), esc(st.get("ssid") or "")
    out = ["<!doctype html><html><head><meta charset=utf-8>"
           "<meta name=viewport content='width=device-width,initial-scale=1'><title>%s Wi-Fi</title>"
           % esc(st.get("name", "PicoQuorum"))]
    if state == "joining":
        out.append("<meta http-equiv=refresh content=3>")
    out.append("<style>%s</style></head><body><h1>Connect %s to <span style=white-space:nowrap>Wi-Fi</span></h1>"
               % (_CSS, esc(st.get("name", "PicoQuorum"))))
    if state == "joining":
        out.append("<p class='m wait'>Joining <b>%s</b>&hellip;</p><p>Watch the console's screen. "
                   "When it says <b>Connected</b> you are done and can close this page.</p></body></html>" % ssid)
        return "".join(out)
    if state == "ok":
        out.append("<p class='m ok'>Connected to <b>%s</b>. The console is restarting. "
                   "You can close this page.</p></body></html>" % ssid)
        return "".join(out)
    if st.get("msg"):
        out.append("<p class='m bad'>%s</p>" % esc(st["msg"]))
    out.append("<form method=post action=/join><label for=s>Your Wi-Fi network</label><select id=s name=ssid>")
    for name in st.get("nets", ()):
        sel = " selected" if name == st.get("ssid") else ""
        out.append("<option value=\"%s\"%s>%s</option>" % (esc(name), sel, esc(name)))
    out.append("<option value=''>Another network (type it below)</option></select>"
               "<label for=o>Network name, if it is not in the list</label>"
               "<input id=o name=other autocapitalize=off autocorrect=off spellcheck=false maxlength=32>"
               "<label for=p>Wi-Fi password</label>"
               "<input id=p name=pass type=password autocapitalize=off autocorrect=off spellcheck=false maxlength=64>"
               "<label style='display:flex;gap:8px;align-items:center'><input type=checkbox style='width:auto' "
               "onclick=\"p.type=this.checked?'text':'password'\">Show password</label>"
               "<button>Connect</button></form><p><small>Leave the password empty for an open network. "
               "This page only sets the console's Wi-Fi.</small></p></body></html>")
    return "".join(out)


def handle(method, path, body, st):
    """One request to the setup hotspot -> (status, content type, body bytes). Every path is the
    page, which is what makes a phone show it by itself as a sign-in page after it joins.
    A POST of the form asks wifisetup to join: st["pending"] = (ssid, password)."""
    if path.startswith("/favicon"):
        return "404 Not Found", "text/plain", b"not here"
    if method == "POST" and st.get("state") not in ("joining", "ok"):
        f = parse_form(body)
        ssid = (f.get("other") or "").strip() or f.get("ssid", "")
        pw = f.get("pass", "")
        why = check(ssid, pw)
        if why:
            st["msg"] = why
        else:
            st["pending"] = (ssid, pw)
            st["state"], st["ssid"], st["msg"] = "joining", ssid, ""
    return "200 OK", "text/html; charset=utf-8", page(st).encode()


def response(status, ctype, body):
    return ("HTTP/1.1 %s\r\nContent-Type: %s\r\nContent-Length: %d\r\nCache-Control: no-store\r\n"
            "Connection: close\r\n\r\n" % (status, ctype, len(body))).encode() + body


# ------------------------------------------------------------------------------------- DNS

def dns_reply(q, ip):
    """Answer one DNS query: every name is ip (4 bytes). Only A records get an answer; anything
    else (AAAA, say) gets an empty one, which sends the phone back to IPv4. None: not a query."""
    if len(q) < 17 or q[2] & 0x80 or q[4:6] != b"\x00\x01":
        return None
    i = 12
    while i < len(q) and q[i]:
        if q[i] & 0xC0:
            return None
        i += q[i] + 1
    end = i + 5
    if end > len(q):
        return None
    a = q[i + 1:i + 3] == b"\x00\x01"
    head = bytes(q[:2]) + b"\x81\x80\x00\x01" + (b"\x00\x01" if a else b"\x00\x00") + b"\x00\x00\x00\x00"
    ans = b"\xc0\x0c\x00\x01\x00\x01\x00\x00\x00\x3c\x00\x04" + bytes(ip) if a else b""
    return head + bytes(q[12:end]) + ans

# Wi-Fi setup: what a board with no Wi-Fi shows at power-up (boot.py), and what holding Y at
# power-up opens on any board. Two ways in, on one screen:
#   - a phone: the console makes its own hotspot and shows a QR code that joins it. The phone then
#     opens the setup page by itself (every web address on the hotspot leads to it), and the
#     person picks their network and types the password there.
#   - the console alone: a list of the networks it can see, then an on-screen keyboard. The
#     Waveshare joystick moves around the keyboard; the build1 knob walks along it one key at a
#     time, and pressing types.
# Either way the console joins the network itself before saving it to wifi.json (wificfg.py), so a
# wrong password is caught here and not at the next boot. Then it restarts.
#
# Nothing else is reachable from here: the hotspot page sets Wi-Fi and nothing more, and the
# console is not running (boot.py starts this before main.py and never returns to it).
#
#   wifisetup.run()     blocking, from boot.py: never returns (restarts the board)
#   wifisetup.start()   the same on a timer, for the emulator (emu/sketches/wifisetup_demo.py)
import os
import time
import network
import lcd as L
import theme as T
import wificfg

AP_IP = "192.168.4.1"
JOIN_S = 20             # a join that has not finished by now has failed
STA_IDLE, STA_CONNECTING = 0, 1
NAME = "PicoQuorum"

# Shared with wificfg.handle (the phone's page): state, ssid, msg, nets, pending.
st = {"state": "idle", "ssid": "", "msg": "", "nets": [], "pending": None, "name": NAME}
view = "qr"             # qr | list | kbd | join | done
qr_mode = "join"        # join: the hotspot's QR; url: a phone is on it, the page's QR
sel = 0                 # list row
scan = []               # [(ssid, rssi, secured)]
kb = None               # the keyboard
ap = sta = web = dns = None
ap_ssid = ap_pass = ""
can_cancel = False
_d = _keys = _timer = None
_dirty = True
_t_join = 0
_t_done = 0
_origin = "qr"          # where a failed join goes back to
_busy = False
_frame = 0


# ------------------------------------------------------------------------------------- radio

def _rand(n, alphabet="abcdefghjkmnpqrstuvwxyz23456789"):
    return "".join(alphabet[b % len(alphabet)] for b in os.urandom(n))


def _scan():
    """The networks in range, strongest first, each name once."""
    global scan
    best = {}
    try:
        for s, _bssid, _ch, rssi, sec, *_ in sta.scan():
            try:
                name = s.decode()
            except UnicodeError:
                continue
            if name and (name not in best or rssi > best[name][0]):
                best[name] = (rssi, bool(sec))
    except Exception as e:
        print("wifisetup: scan:", e)
    scan = sorted(((n, r, s) for n, (r, s) in best.items()), key=lambda x: -x[1])[:12]
    st["nets"] = [n for n, _r, _s in scan]


def _start_ap():
    """The setup hotspot, its web page on :80 and its DNS on :53. Without sockets (the emulator)
    the QR still shows; only the phone's page is missing."""
    global ap, web, dns, ap_ssid, ap_pass
    mac = sta.config("mac") or b"\0\0"
    ap_ssid = "%s-%02X%02X" % (NAME, mac[-2], mac[-1])
    ap_pass = _rand(8)
    ap = network.WLAN(network.AP_IF)
    try:
        ap.config(ssid=ap_ssid, key=ap_pass)
        ap.active(True)
    except Exception as e:
        print("wifisetup: hotspot:", e)
    try:
        import socket
        a = socket.getaddrinfo("0.0.0.0", 80)[0][-1]
        web = socket.socket()
        web.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        web.bind(a)
        web.listen(2)
        web.setblocking(False)
        dns = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        dns.bind(socket.getaddrinfo("0.0.0.0", 53)[0][-1])
        dns.setblocking(False)
    except Exception as e:
        print("wifisetup: no setup page:", e)
        web = dns = None
    print("wifisetup: hotspot %s, password %s, page http://%s/" % (ap_ssid, ap_pass, AP_IP))


def _stop_ap():
    for s in (web, dns):
        try:
            s.close()
        except Exception:
            pass
    try:
        ap.active(False)
    except Exception:
        pass


def _serve():
    """At most one DNS answer and one web request per call; neither blocks while nothing waits."""
    global qr_mode, _dirty
    if dns:
        try:
            q, addr = dns.recvfrom(512)
            r = wificfg.dns_reply(q, bytes(int(x) for x in AP_IP.split(".")))
            if r:
                dns.sendto(r, addr)
        except OSError:
            pass
    if web:
        try:
            conn, _addr = web.accept()
        except OSError:
            return
        try:
            conn.settimeout(3)
            raw = b""
            while b"\r\n\r\n" not in raw and len(raw) < 4096:
                chunk = conn.recv(1024)
                if not chunk:
                    break
                raw += chunk
            req = wificfg.parse_request(raw)
            if req:
                method, path, headers, body = req
                want = wificfg.body_length(headers)
                while len(body) < want:
                    chunk = conn.recv(want - len(body))
                    if not chunk:
                        break
                    body += chunk
                status, ctype, page = wificfg.handle(method, path, body, st)
                conn.sendall(wificfg.response(status, ctype, page))
                if qr_mode == "join":
                    qr_mode, _dirty = "url", True       # a phone is on the hotspot
        except OSError as e:
            print("wifisetup: page:", e)
        finally:
            conn.close()


def _phone_on():
    try:
        n = ap.status("stations")
        return isinstance(n, (list, tuple)) and len(n) > 0
    except Exception:
        return False


def join(ssid, pw, origin):
    """Start joining (the hotspot stays up) and show the joining screen; _poll_join finishes it."""
    global view, _t_join, _origin, _dirty
    st.update(state="joining", ssid=ssid, msg="", pending=None)
    st["pw"] = pw
    _origin = origin
    view, _t_join, _dirty = "join", time.ticks_ms(), True
    try:
        sta.disconnect()
    except Exception:
        pass
    try:
        sta.connect(ssid, pw) if pw else sta.connect(ssid)
    except Exception as e:
        _failed("couldn't start: %s" % e)


def _failed(why):
    global view, _dirty
    st.update(state="failed", msg="%s: %s" % (st["ssid"], why))
    st.pop("pw", None)
    try:
        sta.disconnect()
    except Exception:
        pass
    view, _dirty = _origin, True
    if view == "kbd" and kb:
        kb.note = why


def _poll_join():
    global view, _t_done, _dirty
    s = sta.status()
    waited = time.ticks_diff(time.ticks_ms(), _t_join)
    if sta.isconnected():
        wificfg.save(st["ssid"], st.pop("pw", ""))
        st["state"] = "ok"
        view, _t_done, _dirty = "done", time.ticks_ms(), True
        print("wifisetup: joined %s, saved" % st["ssid"])
    elif s == getattr(network, "STAT_WRONG_PASSWORD", -3) and waited > 1500:
        _failed("wrong password")
    elif s == getattr(network, "STAT_NO_AP_FOUND", -2) and waited > 1500:
        _failed("network not found")
    elif s == getattr(network, "STAT_CONNECT_FAIL", -1) and waited > 1500:
        _failed("couldn't connect")
    elif waited > JOIN_S * 1000:
        _failed("no answer in %d s" % JOIN_S)


# ------------------------------------------------------------------------------------- keyboard

PAGES = (("abcdefghij", "klmnopqrst", "uvwxyz-_.@", "1234567890"),
         ("ABCDEFGHIJ", "KLMNOPQRST", "UVWXYZ-_.@", "1234567890"),
         ("!?#$%&*+=/", "()[]{}<>:;", "'\"`~^|\\,.@", "1234567890"))
SPECIAL = 5             # the last row: case, symbols, space, delete, OK, each two keys wide


class Keyboard:
    """Text entry for both inputs. Joystick: up/down/left/right move on the grid. Knob: "down"
    (clockwise) and "up" step through every key in reading order, wrapping at the ends."""

    def __init__(self, title, what, text="", limit=63):
        self.title, self.what, self.text, self.limit = title, what, text, limit
        self.page, self.r, self.c = 0, 0, 0
        self.note = ""

    def width(self, r):
        return SPECIAL if r == 4 else 10

    def move(self, k):
        r, c = self.r, self.c
        if L.KNOB:
            step = 1 if k == "down" else -1
            c += step
            if c >= self.width(r):
                r, c = (r + 1) % 5, 0
            elif c < 0:
                r = (r - 1) % 5
                c = self.width(r) - 1
        elif k in ("left", "right"):
            c = (c + (1 if k == "right" else -1)) % self.width(r)
        else:
            nr = (r + (1 if k == "down" else -1)) % 5
            if nr == 4:
                c = c // 2
            elif r == 4:
                c = c * 2
            r = nr
        self.r, self.c = r, c

    def label(self, i):
        return (("ABC" if self.page == 0 else "abc"), ("#+=" if self.page != 2 else "abc"),
                "space" if not L.SMALL else "spc", "del", "OK")[i]

    def type(self):
        """The key under the cursor: True when OK was pressed."""
        if self.r < 4:
            if len(self.text) < self.limit:
                self.text += PAGES[self.page][self.r][self.c]
        elif self.c == 0:
            self.page = 1 if self.page == 0 else 0
        elif self.c == 1:
            self.page = 2 if self.page != 2 else 0
        elif self.c == 2:
            if len(self.text) < self.limit:
                self.text += " "
        elif self.c == 3:
            self.text = self.text[:-1]
        else:
            return True
        self.note = ""
        return False


# ------------------------------------------------------------------------------------- keys

def _list_items():
    items = [("net", n, sec) for n, _r, sec in scan]
    items += [("other", "Other network…", False), ("rescan", "Scan again", False), ("qr", "Use a phone instead", False)]
    if can_cancel:
        items.append(("cancel", "Keep the saved Wi-Fi", False))
    return items


def _key(k):
    global view, sel, kb, _dirty, qr_mode
    ok = k in ("A", "press")
    back = k == "Y"
    _dirty = True
    if view == "qr":
        if ok:
            view, sel = "list", 0
        elif k == "X" and can_cancel:
            _restart()
        elif k == "B":
            qr_mode = "url" if qr_mode == "join" else "join"
    elif view == "list":
        items = _list_items()
        if k in ("down", "right"):
            sel = (sel + 1) % len(items)
        elif k in ("up", "left"):
            sel = (sel - 1) % len(items)
        elif back:
            view = "qr"
        elif ok:
            what, name, sec = items[sel]
            if what == "net" and sec:
                kb = Keyboard("Password for " + name, "pass")
                kb.ssid = name
                view = "kbd"
            elif what == "net":
                join(name, "", "list")
            elif what == "other":
                kb = Keyboard("Network name", "ssid", limit=32)
                view = "kbd"
            elif what == "rescan":
                _draw_busy("Looking for networks…")
                _scan()
                sel = 0
            elif what == "qr":
                view = "qr"
            else:
                _restart()
    elif view == "kbd":
        if k in ("up", "down", "left", "right"):
            kb.move(k)
        elif k == "B":
            kb.text = kb.text[:-1]
        elif back:
            view = "list"
        elif ok:
            if kb.r == 4 and kb.c == 3 and not kb.text:
                view = "list"           # del on an empty field: back (the knob has no Y)
            elif kb.type():
                _submit()


def _submit():
    global kb, view
    if kb.what == "ssid":
        name = kb.text
        why = wificfg.check(name, "")
        if why:
            kb.note = why
            return
        kb = Keyboard("Password for " + name, "pass")
        kb.ssid = name
        kb.note = "Leave it empty for an open network"
        return
    why = wificfg.check(kb.ssid, kb.text)
    if why:
        kb.note = why
        return
    join(kb.ssid, kb.text, "kbd")


def _restart():
    _stop_ap()
    import machine
    machine.reset()


# ------------------------------------------------------------------------------------- drawing

BG = T.RGB["bg"]
INK, DIM, ACC = (238, 240, 255), (136, 144, 168), T.RGB["config"]
BAD, GOOD = (255, 110, 100), (60, 220, 130)
BIG = not L.SMALL


def _f():
    import fonts
    return fonts


def tx(s, x, y, font, fg, bg=BG):
    if BIG:
        return _f().text(_d, s, x, y, font, fg, bg)
    s = s.replace(ELL, "")              # framebuf's 8 px font has no ellipsis; fit() adds "~" instead
    _d.text(s, x, y, L.color(*fg))
    return x + 8 * len(s)


def tw(s, font):
    return _f().width(s, font) if BIG else 8 * len(s)


def th(font):
    return _f().height(font) if BIG else 10


def ctx(s, y, font, fg, bg=BG):
    tx(s, (L.W - tw(s, font)) // 2, y, font, fg, bg)


ELL = "…"


def fit(s, w, font):
    """s cut with an ellipsis to w pixels."""
    e = ELL if BIG else "~"
    if tw(s, font) <= w:
        return s
    while s and tw(s + e, font) > w:
        s = s[:-1]
    return s + e


def hint():
    return ("turn to pick, press to choose" if L.KNOB else "A choose · Y back")


_qrc = (None, 0, None)


def _enc(text):
    """qrcode.encode, once per text: it scores all eight masks, too slow for every band of a frame."""
    global _qrc
    if _qrc[0] != text:
        import qrcode
        _qrc = (text,) + qrcode.encode(text)
    return _qrc[1], _qrc[2]


def _qr(text, x0, y0, size):
    n, rows = _enc(text)
    q = 2 * size
    box = n * size + 2 * q
    _d.fill_rect(x0, y0, box, box, L.WHITE)
    for r in range(n):
        bits, c = rows[r], 0
        while c < n:                    # one rectangle per run of dark modules
            if bits >> c & 1:
                e = c
                while e < n and bits >> e & 1:
                    e += 1
                _d.fill_rect(x0 + q + c * size, y0 + q + r * size, (e - c) * size, size, L.BLACK)
                c = e
            else:
                c += 1
    return box


def _qr_size(text, room):
    return max(1, room // (_enc(text)[0] + 4))


def _draw():
    _d.fill(L.color(*BG))
    {"qr": _draw_qr, "list": _draw_list, "kbd": _draw_kbd, "join": _draw_join, "done": _draw_done}[view]()
    _d.show()


def _title(s, color=INK):
    """The top line; an error goes there too, a size smaller so that it fits."""
    f = "bold18" if color != BAD else "bold14"
    ctx(fit(s, L.W - 8, f), (4 if f == "bold18" else 7) if BIG else 2, f, color)


def _draw_qr():
    W, H = L.W, L.H
    url = qr_mode == "url"
    text = ("http://%s/" % AP_IP) if url else wificfg.qr_join(ap_ssid, ap_pass)
    if not BIG:
        size = _qr_size(text, H - 4)
        x = _qr(text, 1, 2, size) + 3       # 7 characters of the 8 px font fit beside it
        for i, s in enumerate(["Open", "the page", "on the", "phone"] if url else ["Scan me", "to set", "up", "Wi-Fi"]):
            tx(s, x, 4 + i * 11, "", INK)
        tx("press", x, H - 26, "", DIM)
        tx("to type", x, H - 15, "", DIM)
        return
    msg = st.get("msg")
    _title(msg if msg else ("Open the page on your phone" if url else "Scan to set up Wi-Fi"), BAD if msg else INK)
    top = 4 + th("bold18") + 4
    foot = 3 * (th("sans12") + 2) + 4
    size = _qr_size(text, H - top - foot)
    y = top + _qr(text, (W - _box(text, size)) // 2, top, size) + 4
    if url:
        ctx("If no page opened, go to", y, "sans12", DIM)
        ctx("http://%s" % AP_IP, y + 16, "bold14", INK)
    else:
        ctx("Point your phone's camera here, or join", y, "sans12", DIM)
        x = (W - tw(ap_ssid + "  " + ap_pass, "bold14")) // 2
        x = tx(ap_ssid + "  ", x, y + 16, "bold14", INK)
        tx(ap_pass, x, y + 16, "bold14", T.RGB["learn"])
    ctx(("press: set up on this screen" if L.KNOB else "A: set up on this screen") +
        ("" if L.KNOB or not can_cancel else " · X: cancel"), H - th("sans12") - 2, "sans12", DIM)


def _box(text, size):
    return (_enc(text)[0] + 4) * size


def _draw_list():
    W, H = L.W, L.H
    msg = st.get("msg")
    _title(msg if msg else "Choose your Wi-Fi", BAD if msg else INK)
    items = _list_items()
    row = 26 if BIG else 12
    top = (4 + th("bold18") + 6) if BIG else 14
    n = (H - top - (th("sans12") + 4 if BIG else 0)) // row
    first = min(max(0, sel - n // 2), max(0, len(items) - n))
    for i in range(first, min(len(items), first + n)):
        what, name, sec = items[i]
        y = top + (i - first) * row
        on = i == sel
        bg = ACC if on else BG
        if on:
            _d.fill_rect(2, y, W - 4, row - 2, L.color(*ACC))
        fg = INK if what == "net" or on else DIM
        pad = (row - 2 - th("sans14")) // 2 if BIG else 1
        tx(fit(name, W - (40 if BIG else 30), "sans14"), 10 if BIG else 4, y + pad, "sans14", fg, bg)
        if what == "net":
            rssi = scan[i][1]
            bars = 3 if rssi > -60 else 2 if rssi > -75 else 1
            for b in range(3):
                h = 3 + b * 3
                _d.fill_rect(W - 22 + b * 5, y + row - 6 - h, 3, h, L.color(*(fg if b < bars else (60, 70, 100))))
            if sec and BIG:
                _d.rect(W - 36, y + row // 2 - 2, 8, 6, L.color(*fg))     # a padlock: body
                _d.rect(W - 34, y + row // 2 - 6, 4, 5, L.color(*fg))     # and shackle
    if BIG:
        ctx(hint(), H - th("sans12") - 2, "sans12", DIM)


def _draw_kbd():
    W, H = L.W, L.H
    tx(fit(kb.title, W - 8, "sans14"), 4, 2 if BIG else 0, "sans14", DIM)
    fy = (4 + th("sans14")) if BIG else 10
    fh = (th("mono13") + 8) if BIG else 12
    _d.fill_rect(2, fy, W - 4, fh, L.color(20, 30, 58))
    shown = kb.text
    while shown and tw(shown + "_", "mono13") > W - 14:
        shown = shown[1:]               # the end of a long password, where the typing is
    x = tx(shown, 7, fy + (4 if BIG else 2), "mono13", INK, (20, 30, 58))
    _d.fill_rect(x + 1, fy + 3, 2, fh - 6, L.color(*ACC))
    gy = fy + fh + (4 if BIG else 2)
    note_h = (th("sans12") + 2) if BIG else 0
    rh = (H - gy - note_h) // 5
    cw = W // 10
    x0 = (W - cw * 10) // 2
    rows = PAGES[kb.page]
    for r in range(5):
        for c in range(kb.width(r)):
            wide = 2 if r == 4 else 1
            x, y, w = x0 + c * cw * wide, gy + r * rh, cw * wide
            on = r == kb.r and c == kb.c
            bg = ACC if on else ((26, 36, 66) if r == 4 else BG)
            if on or r == 4:
                _d.fill_rect(x + 1, y + 1, w - 2, rh - 2, L.color(*bg))
            s = rows[r][c] if r < 4 else kb.label(c)
            font = "bold18" if r < 4 else "sans12"
            tx(s, x + (w - tw(s, font)) // 2, y + (rh - th(font)) // 2 + (1 if BIG else 0), font, INK if r < 4 or on else DIM, bg)
    if BIG:
        if kb.note:
            ctx(fit(kb.note, W - 8, "sans12"), H - th("sans12") - 1, "sans12", BAD)
        else:
            ctx("turn to move, press to type" if L.KNOB else "A type · B delete · Y back", H - th("sans12") - 1, "sans12", DIM)


def _draw_join():
    W, H = L.W, L.H
    _title("Joining")
    ctx(fit(st["ssid"], W - 8, "bold18"), H // 2 - 30, "bold18", INK)
    for i in range(5):
        on = (_frame // 3) % 5 == i
        _d.fill_rect(W // 2 - 44 + i * 18, H // 2 + 4, 10, 10, L.color(*(ACC if on else (40, 50, 80))))
    if BIG:
        ctx("This takes up to %d seconds" % JOIN_S, H // 2 + 30, "sans12", DIM)


def _draw_done():
    W, H = L.W, L.H
    _title("Connected", GOOD)
    ctx(fit(st["ssid"], W - 8, "bold18"), H // 2 - 20, "bold18", INK)
    ctx("Saved. Restarting…", H // 2 + 14, "sans14" if BIG else "", DIM)


def _draw_busy(s):
    def draw():
        _d.fill(L.color(*BG))
        ctx(s, L.H // 2 - 8, "sans14", INK)
        _d.show()
    _d.frames(draw)


# ------------------------------------------------------------------------------------- loop

def _setup():
    global sta, _d, _keys, can_cancel, view
    import net
    import splash
    can_cancel = bool(net.networks())
    _d = splash.begin()
    _keys = L.Keys()
    sta = network.WLAN(network.STA_IF)
    sta.active(True)
    try:
        sta.disconnect()
    except Exception:
        pass
    _draw_busy("Looking for networks…")
    _scan()
    _start_ap()
    view = "qr"


def step():
    """One pass: keys, the hotspot's page and DNS, the join in progress, the screen."""
    global _busy, _dirty, _frame, qr_mode
    if _busy:
        return
    _busy = True
    try:
        _frame += 1
        for k in _keys.pressed():
            _key(k)
        _serve()
        if st.get("pending") and view != "join":
            ssid, pw = st["pending"]
            join(ssid, pw, "qr")
        if view == "join":
            _poll_join()
            _dirty = _dirty or _frame % 3 == 0
        if view == "qr" and qr_mode == "join" and _frame % 40 == 0 and _phone_on():
            qr_mode, _dirty = "url", True
        if view == "done" and time.ticks_diff(time.ticks_ms(), _t_done) > 2500:
            _restart()
        if _dirty:
            _dirty = False
            _d.frames(_draw)
    finally:
        _busy = False


def run():
    """From boot.py. Never returns: a saved network (or a cancel) restarts the board."""
    _setup()
    while True:
        step()
        time.sleep_ms(30)


def start():
    """The same on a timer, so the emulator's REPL stays free (tools/emu exec, --key)."""
    global _timer
    from machine import Timer
    _setup()
    _timer = Timer(period=40, mode=Timer.PERIODIC, callback=lambda t: step())


def stop():
    if _timer:
        _timer.deinit()
    _stop_ap()

shims.atecc_sim:
# A virtual ATECC608 on the emulator's I2C bus at 0x60. Speaks the chip's packet protocol
# (wake token, 0x03 command packets with CRC-16, count+payload+CRC responses) so firmware/atecc.py
# runs here unchanged. Models what a wallet touches: the config zone and its locks, the slot table
# (SlotConfig / KeyConfig), GenKey, Nonce pass-through + Sign, Random, Info, per-slot locks.
# Also answered: Info KeyValid/State, SelfTest (all pass), SHA-256, Counter reads, clear data
# and OTP writes (32 or 4 bytes; any slot but a private key before the data lock, only WriteConfig
# Always after it), reads of the OTP and data zones only once the DATA zone is locked, and the
# CRC-checked locks: the config zone's summary is the CRC of its 128 bytes, the data zone's of every
# slot that is not a private key followed by the OTP zone; a slot lock ignores it. LimitedUse stops
# a slot at counter 0's cap. Not modeled: MAC/encrypted anything, the watchdog.
#
# A fresh emulator answers like a real fresh part: the factory config of an Adafruit 4314 breakout
# (docs/UPSTREAM.md section 3: slots 0-2 already typed P-256, GenKey allowed), config zone unlocked, and
# Random returning the datasheet's fixed pattern until the lock. The state persists across reboots
# through the host (server: emu/chip.json). wipe() / provision() reset it.
import json
import _emu

ADDR = 0x60
WAKE = b"\x04\x11\x33\x43"
STATUS_OK, STATUS_PARSE, STATUS_EXEC, STATUS_CRC = 0x00, 0x03, 0x0F, 0xFF
OP_READ, OP_NONCE, OP_GENKEY, OP_SIGN, OP_RANDOM, OP_INFO, OP_WRITE, OP_LOCK = 0x02, 0x16, 0x40, 0x41, 0x1B, 0x30, 0x12, 0x17
OP_COUNTER, OP_SHA, OP_SELFTEST = 0x24, 0x47, 0x77
SLOT_BYTES = (36,) * 8 + (416,) + (72,) * 7

# what a fresh part answers: the serial (bytes 0-3, 8-12) and revision 00006002 (608A) of the
# virtual chip, then byte for byte the factory table read off a real Adafruit breakout on
# 2026-09-16: I2C address 0xC0, SlotConfig 2083 2087 208f for slots 0-2, lock bytes 86/87 = 0x55,
# SlotLocked = 0xFFFF, KeyConfig 0033 for slots 0-2 (P-256 private, GenKey allowed).
FRESH = bytearray(bytes([
    0x01, 0x23, 0xE1, 0x00, 0x00, 0x00, 0x60, 0x02, 0xE1, 0xE1, 0xE1, 0xE1, 0xEE, 0xC1, 0x55, 0x00,
    0xC0, 0x00, 0x00, 0x00, 0x83, 0x20, 0x87, 0x20, 0x8F, 0x20, 0xC4, 0x8F, 0x8F, 0x8F, 0x8F, 0x8F,
    0x9F, 0x8F, 0xAF, 0x8F, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0xAF, 0x8F, 0xFF, 0xFF, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x00, 0xFF, 0xFF, 0xFF, 0xFF,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x55, 0x55, 0xFF, 0xFF, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
    0x33, 0x00, 0x33, 0x00, 0x33, 0x00, 0x1C, 0x00, 0x1C, 0x00, 0x1C, 0x00, 0x1C, 0x00, 0x1C, 0x00,
    0x3C, 0x00, 0x3C, 0x00, 0x3C, 0x00, 0x3C, 0x00, 0x3C, 0x00, 0x3C, 0x00, 0x3C, 0x00, 0x1C, 0x00,
]))
FIXED_RANDOM = bytes([0xFF, 0xFF, 0x00, 0x00]) * 8     # what an unlocked chip answers to Random
COUNTER_MAX = 2097151       # counter 0's cap; a LimitedUse slot signs no more once it is there


def crc16(data):
    crc = 0
    for b in data:
        for shift in range(8):
            data_bit = (b >> shift) & 1
            crc_bit = (crc >> 15) & 1
            crc = (crc << 1) & 0xFFFF
            if data_bit != crc_bit:
                crc ^= 0x8005
    return bytes([crc & 0xFF, crc >> 8])


class Chip:
    def __init__(self):
        self.cfg = bytearray(FRESH)
        self.keys = {}          # slot -> private scalar
        self.counters = [0, 0]
        self.otp = bytearray(b"\xff" * 64)   # "All OTP bits have a value of one upon shipment"
        self.data = {}          # slot -> bytearray, on first use (factory contents: all ones here)
        self.sha = None
        self.awake = False
        self.tempkey = None
        self.resp = b""
        self.load()

    # --- persistence through the host ----------------------------------------------------
    def load(self):
        try:
            raw = _emu.chip_load()
        except Exception:
            raw = None
        if not raw:
            return
        try:
            st = json.loads(raw)
            if "config" not in st:
                return          # only the Trust M's state (or the bus) is stored so far
            self.cfg = bytearray(bytes.fromhex(st["config"]))
            self.keys = {int(k): int(v, 16) for k, v in st.get("keys", {}).items()}
            self.counters = list(st.get("counters", [0, 0]))
            self.data = {int(k): bytearray(bytes.fromhex(v)) for k, v in st.get("data", {}).items()}
            if "otp" in st:
                self.otp = bytearray(bytes.fromhex(st["otp"]))
        except Exception as e:
            print("atecc_sim: bad saved state (%s), starting blank" % e)

    def save(self):
        st = {"config": "".join("%02x" % b for b in self.cfg), "keys": {str(k): "%064x" % v for k, v in self.keys.items()},
              "counters": self.counters, "data": {str(k): "".join("%02x" % b for b in v) for k, v in self.data.items()},
              "otp": "".join("%02x" % b for b in self.otp)}
        try:
            old = json.loads(_emu.chip_load() or "{}")     # keep what else is stored (the Trust M's)
        except Exception:
            old = {}
        old.update(st)
        try:
            _emu.chip_save(json.dumps(old))
        except Exception as e:
            print("atecc_sim: could not save state: %s" % e)

    # --- config zone helpers ---------------------------------------------------------------
    def config_locked(self):
        return self.cfg[87] == 0x00

    def data_locked(self):
        return self.cfg[86] == 0x00

    def slot_cfg(self, slot):
        return self.cfg[20 + 2 * slot] | self.cfg[21 + 2 * slot] << 8

    def key_cfg(self, slot):
        return self.cfg[96 + 2 * slot] | self.cfg[97 + 2 * slot] << 8

    def slot_locked(self, slot):
        return not (self.cfg[88 + (slot >> 3)] >> (slot & 7)) & 1

    def is_p256_private(self, slot):
        kc = self.key_cfg(slot)
        return bool(kc & 1) and (kc >> 2) & 7 == 4

    def slot_data(self, slot):
        return self.data.setdefault(slot, bytearray(b"\xff" * SLOT_BYTES[slot]))

    def data_summary_bytes(self):
        out = b""
        for n in range(16):
            if self.key_cfg(n) & 1:
                continue            # private keys are never part of the data zone's CRC
            out += bytes(self.slot_data(n))
        return out + bytes(self.otp)

    # --- bus ---------------------------------------------------------------------------------
    def write(self, buf):
        """One I2C write to 0x60. Word address byte first: 0x01 sleep, 0x02 idle, 0x03 command."""
        if not self.awake:
            raise OSError(5, "EIO: chip is asleep")
        wa = buf[0]
        if wa == 0x01 or wa == 0x02:
            self.awake = False
            self.tempkey = None
            self.resp = b""
            return
        if wa != 0x03:
            raise OSError(5, "EIO: unknown word address 0x%02x" % wa)
        pkt = bytes(buf[1:])
        if len(pkt) < 7 or pkt[0] != len(pkt) or crc16(pkt[:-2]) != pkt[-2:]:
            self.resp = self._status(STATUS_CRC)
            return
        opcode, p1, p2 = pkt[1], pkt[2], pkt[3] | pkt[4] << 8
        data = pkt[5:-2]
        try:
            out = self.execute(opcode, p1, p2, data)
        except _Fail as f:
            out = self._status(f.code)
        self.resp = out

    def read(self, n):
        if not self.awake:
            raise OSError(5, "EIO: chip is asleep")
        if not self.resp:
            raise OSError(5, "EIO: busy")   # the driver retries until the wait time has passed
        out = self.resp[:n]
        return out + bytes(n - len(out))

    def wake_token(self):
        self.awake = True
        self.tempkey = None
        self.resp = WAKE

    def _status(self, code):
        body = bytes([4, code])
        return body + crc16(body)

    def _data(self, payload):
        body = bytes([len(payload) + 3]) + payload
        return body + crc16(body)

    # --- commands ----------------------------------------------------------------------------
    def execute(self, opcode, p1, p2, data):
        if opcode == OP_INFO:
            mode = p1 & 0x0F
            if mode == 0:
                return self._data(bytes(self.cfg[4:8]))
            if mode == 1:       # KeyValid: byte 0 is 1 when the slot holds a usable key
                return self._data(bytes([1 if (p2 & 0xF) in self.keys and self.config_locked() else 0, 0, 0, 0]))
            if mode == 2:       # State: bit 7 of byte 0 = TempKey valid (the rest is not modeled)
                return self._data(bytes([0x80 if self.tempkey else 0x00, 0, 0, 0]))
            if mode == 3:       # GPIO
                return self._data(bytes(4))
            raise _Fail(STATUS_PARSE)
        if opcode == OP_RANDOM:
            if not self.config_locked():
                return self._data(FIXED_RANDOM)    # datasheet: a fixed pattern until the config lock
            return self._data(bytes(_emu.random(32)))
        if opcode == OP_SELFTEST:
            return self._data(b"\x00")             # every test passes
        if opcode == OP_SHA:
            return self.sha_cmd(p1 & 0x07, p2, data)
        if opcode == OP_COUNTER:
            if p2 > 1:
                raise _Fail(STATUS_PARSE)
            if p1 & 1:
                self.counters[p2] += 1
                self.save()
            return self._data(self.counters[p2].to_bytes(4, "little"))
        if opcode == OP_READ:
            zone = p1 & 3
            if zone == 3:
                raise _Fail(STATUS_PARSE)
            if zone != 0 and not self.data_locked():
                raise _Fail(STATUS_EXEC)      # data and OTP cannot be read until the DATA zone is locked (seen on silicon)
            if zone == 1:
                block = p2 >> 3
                if block > 1 or not p1 & 0x80:
                    raise _Fail(STATUS_PARSE)
                return self._data(bytes(self.otp[block * 32:block * 32 + 32]))
            if zone == 2:
                slot, block = (p2 >> 3) & 0xF, p2 >> 8
                if block * 32 + 32 > SLOT_BYTES[slot] or not p1 & 0x80:
                    raise _Fail(STATUS_PARSE)
                if self.slot_cfg(slot) & 0x80:
                    raise _Fail(STATUS_EXEC)  # IsSecret: never readable in clear
                buf = self.slot_data(slot)
                return self._data(bytes(buf[block * 32:block * 32 + 32]))
            if p1 & 0x80:
                block = p2 >> 3
                if block > 3:
                    raise _Fail(STATUS_PARSE)
                return self._data(bytes(self.cfg[block * 32:block * 32 + 32]))
            if p2 > 31:
                raise _Fail(STATUS_PARSE)
            return self._data(bytes(self.cfg[p2 * 4:p2 * 4 + 4]))
        if opcode == OP_WRITE:
            n = 32 if p1 & 0x80 else 4
            if p1 & 3 in (1, 2) and len(data) != n:
                raise _Fail(STATUS_PARSE)
            if p1 & 3 == 2:
                # a data slot in clear, 32 bytes at a block or 4 at a word, only after the config lock.
                # Before the data lock any slot but a private key (those take PrivWrite); after it,
                # only where WriteConfig says Always, and never a locked slot.
                slot, block, word = (p2 >> 3) & 0xF, p2 >> 8, p2 & 7 if n == 4 else 0
                off = block * 32 + word * 4
                if off >= SLOT_BYTES[slot] or (n == 4 and off + n > SLOT_BYTES[slot]):
                    raise _Fail(STATUS_PARSE)
                if not self.config_locked() or self.key_cfg(slot) & 1 or self.slot_locked(slot):
                    raise _Fail(STATUS_EXEC)
                if self.data_locked() and self.slot_cfg(slot) >> 12:
                    raise _Fail(STATUS_EXEC)
                if n == 4 and not self.data_locked() and self.slot_cfg(slot) >> 12:
                    raise _Fail(STATUS_EXEC)      # seen on silicon: no 4-byte writes into these slots before the data lock
                n = min(n, SLOT_BYTES[slot] - off)  # a 32-byte write at the last, partial block keeps what fits
                self.slot_data(slot)[off:off + n] = data[:n]
                self.save()
                return self._status(STATUS_OK)
            if p1 & 3 == 1:
                # the OTP zone: writable in clear only while the data zone is open
                block, word = (p2 >> 3) & 1, p2 & 7 if n == 4 else 0
                if not self.config_locked() or self.data_locked():
                    raise _Fail(STATUS_EXEC)
                self.otp[block * 32 + word * 4:block * 32 + word * 4 + n] = data
                self.save()
                return self._status(STATUS_OK)
            if p1 & 3 != 0 or p1 & 0x80 or len(data) != 4:
                raise _Fail(STATUS_PARSE)
            if self.config_locked() or p2 < 4 or p2 == 21 or p2 > 31:
                raise _Fail(STATUS_EXEC)     # locked zone, or the read-only words
            self.cfg[p2 * 4:p2 * 4 + 4] = data
            self.save()
            return self._status(STATUS_OK)
        if opcode == OP_LOCK:
            return self.lock(p1, p2)
        if opcode == OP_GENKEY:
            return self.genkey(p1, p2)
        if opcode == OP_NONCE:
            if p1 & 3 != 3 or len(data) != 32:
                raise _Fail(STATUS_PARSE)     # only pass-through mode is modeled
            self.tempkey = bytes(data)
            return self._status(STATUS_OK)
        if opcode == OP_SIGN:
            return self.sign(p1, p2)
        raise _Fail(STATUS_PARSE)

    def sha_cmd(self, mode, length, data):
        try:
            import hashlib
        except ImportError:
            raise _Fail(STATUS_PARSE)
        if mode == 0:
            self.sha = hashlib.sha256()
            return self._status(STATUS_OK)
        if self.sha is None:
            raise _Fail(STATUS_EXEC)
        if mode == 1:
            if len(data) != 64:
                raise _Fail(STATUS_PARSE)
            self.sha.update(data)
            return self._status(STATUS_OK)
        if mode == 2:
            if len(data) != length or length > 63:
                raise _Fail(STATUS_PARSE)
            self.sha.update(data)
            out, self.sha = self.sha.digest(), None
            return self._data(out)
        raise _Fail(STATUS_PARSE)

    def _crc_ok(self, mode, summary, data):
        """Bit 7 of the mode: ignore the summary. Otherwise the zone must match it exactly."""
        if mode & 0x80:
            return True
        c = crc16(data)
        return summary == (c[0] | c[1] << 8)

    def lock(self, mode, summary=0):
        what = mode & 3
        if what == 0:
            if self.config_locked():
                raise _Fail(STATUS_EXEC)
            if not self._crc_ok(mode, summary, bytes(self.cfg)):
                raise _Fail(STATUS_EXEC)      # the zone is not what the summary says: nothing is locked
            self.cfg[87] = 0x00
        elif what == 1:
            if not self.config_locked() or self.data_locked():
                raise _Fail(STATUS_EXEC)
            if not self._crc_ok(mode, summary, self.data_summary_bytes()):
                raise _Fail(STATUS_EXEC)
            self.cfg[86] = 0x00
        elif what == 2:
            slot = (mode >> 2) & 0xF
            if not self.config_locked() or not self.key_cfg(slot) & 0x20 or self.slot_locked(slot):
                raise _Fail(STATUS_EXEC)      # KeyConfig.Lockable clear, or already locked
            self.cfg[88 + (slot >> 3)] &= ~(1 << (slot & 7)) & 0xFF
        else:
            raise _Fail(STATUS_PARSE)
        self.save()
        return self._status(STATUS_OK)

    def genkey(self, mode, slot):
        import p256
        if slot > 15:
            raise _Fail(STATUS_PARSE)
        if not self.config_locked() or not self.is_p256_private(slot):
            raise _Fail(STATUS_EXEC)          # a blank chip, or the slot is not a private key
        if mode & 0x04:
            # create: SlotConfig.WriteConfig bit 13 (GenKey allowed) and the slot not locked
            if not self.slot_cfg(slot) >> 13 & 1 or self.slot_locked(slot):
                raise _Fail(STATUS_EXEC)
            self.keys[slot] = p256.rand_scalar()
            self.save()
        elif mode & 0x0F:
            raise _Fail(STATUS_PARSE)
        else:
            # public key of the stored key: needs a key and KeyConfig.PubInfo
            if slot not in self.keys or not self.key_cfg(slot) & 2:
                raise _Fail(STATUS_EXEC)
            if self.data_locked() and self.slot_cfg(slot) & 0x20:
                # seen on silicon (chip 2, quorum v1): once the data zone is locked, a public-key
                # read counts as a use of a LimitedUse key; chip 1 (data zone open) never counted it
                if self.counters[0] >= COUNTER_MAX:
                    raise _Fail(STATUS_EXEC)
                self.counters[0] += 1
                self.save()
        x, y = p256.pubkey(self.keys[slot])
        return self._data(x.to_bytes(32, "big") + y.to_bytes(32, "big"))

    def sign(self, mode, slot):
        import p256
        if not mode & 0x80:
            raise _Fail(STATUS_PARSE)         # only external (TempKey) signing is modeled
        if slot > 15 or self.tempkey is None:
            raise _Fail(STATUS_EXEC)
        if not self.config_locked() or not self.is_p256_private(slot) or slot not in self.keys:
            raise _Fail(STATUS_EXEC)
        if not self.slot_cfg(slot) & 1 or not self.slot_cfg(slot) & 0x80:
            raise _Fail(STATUS_EXEC)          # ReadKey bit 0: external signatures not permitted; IsSecret required
        digest, self.tempkey = self.tempkey, None
        if self.slot_cfg(slot) & 0x20:          # LimitedUse: every signature spends one on counter 0, first
            if self.counters[0] >= COUNTER_MAX:
                raise _Fail(STATUS_EXEC)
            self.counters[0] += 1
            self.save()
        r, s = p256.sign(self.keys[slot], digest)
        return self._data(r.to_bytes(32, "big") + s.to_bytes(32, "big"))


class _Fail(Exception):
    def __init__(self, code):
        self.code = code


def _on_bus():
    try:
        return json.loads(_emu.chip_load() or "{}").get("bus", {}).get("atecc608", True)
    except Exception:
        return True


_chip = None
present = _on_bus()     # False: nothing answers at 0x60, as with the chip unplugged (tests, tools/emu chip trustm)


def chip():
    global _chip
    if _chip is None:
        _chip = Chip()
    return _chip


# --- knobs for tools/emu chip ... and sketches -------------------------------------------
def wipe(revision="608a"):
    """Back to a fresh part: the factory table, config unlocked, no keys, factory data and OTP.
    revision "608b" answers Info with 00006003 (and has it at config bytes 4-7), as a 608B does."""
    c = chip()
    c.cfg = bytearray(FRESH)
    c.cfg[7] = 0x03 if revision == "608b" else 0x02
    c.keys = {}
    c.counters = [0, 0]
    c.data = {}
    c.otp = bytearray(b"\xff" * 64)
    c.save()
    return "chip wiped: fresh %s, config zone unlocked" % revision.upper()


def provision(slot=0):
    """A chip as the wallet ships it: reference config written and locked, a fresh key in `slot`."""
    import p256
    from atecc import CONFIG
    c = chip()
    cfg = bytearray(CONFIG)
    cfg[0:16] = FRESH[0:16]
    cfg[84:88] = bytes([0x00, 0x00, 0x00, 0x00])   # data zone stays unlocked, config locked
    cfg[86] = 0x55
    c.cfg = cfg
    c.keys = {slot: p256.rand_scalar()}
    c.save()
    return "chip provisioned: config locked, key in slot %d" % slot


def provision_v1(slot=0):
    """A chip after the whole quorum v1 ceremony (docs/PROVISIONING.md): the table locked, a key in
    slot 0 and the slot locked, slots 1-15 zeroed, the data zone locked. No OTP record."""
    import p256
    from chipcfg import QUORUM_V1
    c = chip()
    cfg = bytearray(QUORUM_V1)
    cfg[0:16] = c.cfg[0:16]
    cfg[84:88] = bytes([0x00, 0x00, 0x00, 0x00])
    cfg[88] = 0xFE
    c.cfg = cfg
    c.keys = {slot: p256.rand_scalar()}
    c.counters = [0, 0]
    c.data = {n: bytearray(SLOT_BYTES[n]) for n in range(1, 16)}
    c.otp = bytearray(64)
    c.save()
    return "chip provisioned as quorum v1: sealed key in slot 0, data zone locked"


def state():
    c = chip()
    return {"configLocked": c.config_locked(), "dataLocked": c.data_locked(), "keys": sorted(c.keys),
            "slotLocked": [n for n in range(16) if c.slot_locked(n)]}

