class I2C:
    """The key bus: a virtual ATECC608 at 0x60 (atecc_sim.py) and a virtual OPTIGA Trust M at
    0x30 (trustm_sim.py), each there or not, so firmware/atecc.py, trustm.py and signer.py run here
    unchanged. A write to address 0 is the ATECC's wake token. An asleep Trust M NACKs its address,
    so scan() does not list it (as on the real bus); addressed directly it answers. Every other
    address fails with ENODEV, like an empty bus."""

    def __init__(self, id=0, **kw):
        self.id = id

    def _dev(self, addr):
        if addr == 0x60:
            import atecc_sim
            if atecc_sim.present:
                return atecc_sim.chip()
        elif addr == 0x30:
            import trustm_sim
            if trustm_sim.present:
                return trustm_sim.chip()
        raise OSError(19, "ENODEV: no I2C device at 0x%02x" % addr)

    def scan(self):
        import atecc_sim
        return [0x60] if atecc_sim.present else []

    def writeto(self, addr, buf, stop=True):
        if addr == 0:
            import atecc_sim
            if not atecc_sim.present:
                raise OSError(19, "ENODEV: no I2C device at 0x00")
            atecc_sim.chip().wake_token()
            return len(buf)
        self._dev(addr).write(bytes(buf))
        return len(buf)

    def readfrom(self, addr, n, stop=True):
        return self._dev(addr).read(n)

    def readfrom_into(self, addr, buf, stop=True):
        buf[:] = self.readfrom(addr, len(buf))

    def writevto(self, addr, vec, stop=True):
        return self.writeto(addr, b"".join(bytes(v) for v in vec))

    def _fail(self, *a, **k):
        raise OSError(19, "ENODEV: memory-addressed transfers are not modeled")

    readfrom_mem = writeto_mem = readfrom_mem_into = _fail


SoftI2C = I2C


class PWM:
    def __init__(self, pin, freq=None, duty_u16=None, **kw):
        self.pin = pin
        self._freq = freq or 1000
        self._duty = 0
        if duty_u16 is not None:
            self.duty_u16(duty_u16)

    def freq(self, f=None):
        if f is None:
            return self._freq
        self._freq = f

    def duty_u16(self, d=None):
        if d is None:
            return self._duty
        self._duty = d
        _emu.pwm(self.pin.id, d / 65535)

    def duty_ns(self, ns=None):
        if ns is None:
            return int(self._duty / 65535 * 1e9 / self._freq)
        self.duty_u16(int(ns * self._freq / 1e9 * 65535))

    def deinit(self):
        _emu.pwm(self.pin.id, 0)


class ADC:
