        self._h = None
        if kw:
            self.init(**kw)

    def init(self, mode=PERIODIC, period=-1, freq=None, callback=None, tick_hz=1000, **kw):
        self.deinit()
        if freq:
            period = int(1000 / freq)
        if period < 0:
            period = 1000
        if callback is None:
